INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-crv34', 'crv34', 'Juventudes e aprendizagens musicais na contemporaneidade', NULL, '["Margarete Arroyo","Renato de Carvalho Cardoso","Heloisa Faria Braga Feichas","Flávia Motoyama Narita"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro foi idealizado durante o IV Seminário Temático do Apremus – Grupo de Pesquisa sobre Aprendizagens Musicais na Contemporaneidade do Instituto de Artes da Universidade Estadual Paulista (Unesp), ocorrido em outubro de 2017. As ideias que nortearam as exposições e as discussões durante o evento permeiam esta publicação e estão sintetizadas na afirmação de que práticas musicais participam ativamente da constituição juvenil ao mesmo tempo em que novas estéticas musicais são criadas a partir das ações d@s jovens. As condições da contemporaneidade potencializam a criação com sons, da qual @s jovens são protagonistas. Esse cenário nos instiga a compreender as dimensões vinculadas às interações de jovens e músicas (processos e produtos). Questões como as novas práticas musicais que @s jovens inauguram, as quais requerem novos instrumentos de análise e interpretação, e a presença marcante da música na vida cotidiana deles nos levam a supor uma ‘epistemologia musical’, isto é, uma maneira sonoro-musical de conhecer a si, ao outro e ao mundo. Nesse quadro, nos impulsiona desvelar os papéis da aprendizagem musical.', '["youth","music learning","contemporary music","everyday music","musical knowledge"]', '10.7476/9786557140116', '9786557140116', 'https://books.scielo.org/id/crv34', 'https://books.scielo.org/id/crv34/pdf/arroyo-9786557140116.pdf', NULL, 'https://books.scielo.org/id/crv34/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cs454', 'cs454', 'O abolicionismo', NULL, '["Joaquim Nabuco"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Já existe, felizmente, em nosso país, uma consciência nacional – em formação, é certo – que vai introduzindo o elemento da dignidade humana em nossa legislação, e para a qual a escravidão, apesar de hereditária, é uma verdadeira mancha de Caim que o Brasil traz na fronte... [trecho retirado do Prefácio do livro]', '["abolitionism","slavery","human dignity","national consciousness","slavery in Brazil","abolition of slavery"]', '10.7476/9788579820700', '9788579820700', 'https://books.scielo.org/id/cs454', 'https://static.scielo.org/scielobooks/cs454/pdf/nabuco-9788579820700.pdf', NULL, 'https://books.scielo.org/id/cs454/cover/cover_thumbnail.jpeg', NULL, 169, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-csdpm', 'csdpm', 'Carta sobre a felicidade (A Meneceu)', NULL, '["Epicuro","Lorencini, Álvaro","Enzo Del Carratore"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '(Edição bilíngüe: grego/português) "Que ninguém hesite em se dedicar à filosofia enquanto jovem, nem se canse de fazê-lo depois de velho, porque ninguém jamais é demasiado jovem ou demasiado velho para alcançar a saúde do espírito. Quem afirma que a hora de dedicar-se à filosofia ainda não chegou, ou que ela já passou, é como se dissesse que ainda não chegou ou que já passou a hora de ser feliz. Desse modo, a filosofia é útil tanto ao jovem quanto ao velho: para quem está envelhecendo sentir-se rejuvenescer através da grata recordação das coisas que já se foram, e para o jovem poder envelhecer sem sentir medo das coisas que estão por vir; é necessário, portanto, cuidar das coisas que trazem a felicidade, já que, estando esta presente, tudo temos, e, sem ela, tudo fazemos para alcançá-la..."', '["happiness","philosophy","youth","old age","spiritual health","ancient Greek philosophy","Stoicism"]', '10.7476/9788539302796', '9788571393974', 'https://books.scielo.org/id/csdpm', NULL, NULL, 'https://books.scielo.org/id/csdpm/cover/cover_thumbnail.jpeg', 51, 47, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cspqq', 'cspqq', 'Desconstruindo a discriminação do negro no livro didático', NULL, '["Ana Célia Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As relações sociais na escola ainda refletem as consequências do recalque das diferenças internalizado por muitos alunos e professores. A segunda edição deste livro objetiva oferecer condições para que educadores e educadoras possam utilizar o livro didático de forma crítica, transformando-o em um instrumento gerador de consciência reflexiva. Desconstruir a ideologia que desumaniza contribui para o processo de reconstrução da identidade étnicoracial e da autoestima da criança negra, com efeitos positivos para a sua aprendizagem e sua interação social.', '["racial discrimination","Black students","textbooks","ethnic-racial identity","self-esteem","school relationships","internalized racism","deconstruction of ideology","social interaction"]', '10.7476/9788523211783', '9788523207366', 'https://books.scielo.org/id/cspqq', NULL, NULL, 'https://books.scielo.org/id/cspqq/cover/cover_thumbnail.jpeg', 100, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-csxj3', 'csxj3', 'O papel da filosofia na teoria crítica de Herbert Marcuse', NULL, '["Robespierre de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Herbert Marcuse (1898-1979) obteve nos anos 1960 uma popularidade para além do meio acadêmico. Filósofo de formação, participou do Instituto de Pesquisas Sociais, conhecido como “Escola de Frankfurt”, colaborando para o projeto da teoria crítica da sociedade junto com Max Horkheimer e Theodor Adorno. Os estudos sobre Marcuse sofreram uma espécie de “eclipse” nos anos 1980, mas foram retomados no final dos 1990. A organização de uma Sociedade Internacional Herbert marcuse (IHMS) e, 2002 colaborou para agregar pesquisadores e estudiosos de Marcuse e da teoria crítica. O objetivo não é tanto a mera interpretação teórica da obra de Marcuse, mas sua atualização crítica frente à realidade do tempo presente. No Brasil, desde os anos 2000, houve um aumento no interesse por Marcuse. Este livro inclui-se nesse processo e visa colaborar para o entendimento e a compreensão da teoria crítica marcusiana. Sua intenção é mostrar o caráter filosófico da obra de Marcuse e, ao mesmo tempo, o significado de filosofia pra ele. Percorre-se a questão ontológica, a perspectiva marxista e a influência psicanalítica.', '["Herbert Marcuse","critical theory","Frankfurt School","Marxist ontology","Max Horkheimer","Theodor W. Adorno"]', '10.7476/9786557145029', '9786557145029', 'https://books.scielo.org/id/csxj3', 'https://books.scielo.org/id/csxj3/pdf/oliveira-9786557145029.pdf', NULL, 'https://books.scielo.org/id/csxj3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cszd4', 'cszd4', 'Cidade de lobos: a representação de territórios marginais na obra de Rubens Figueiredo', NULL, '["Paulo Roberto Tonani do Patrocínio"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os ensaios reunidos em Cidade de Lobos discorrem sobre as formas de representação das margens urbanas na obra de Rubens Figueiredo, um dos mais expressivos escritores da literatura brasileira contemporânea. Em sua análise, Paulo Roberto Tonani do Patrocínio destaca a cidade como palco primordial para o exame das diferenças e desigualdades sociais, privilegiando o olhar sobre territórios marginais. Ao propor uma leitura acerca da obra de Rubens Figueiredo, o crítico coloca em relevo o diálogo que o autor realiza com a tradição naturalista e analisa os recursos adotados na tematização da violência urbana a partir da leitura crítica do romance Passageiro do fim do dia e dos livros de contos Contos de Pedro e O livro dos lobos.', '["urban periphery","marginal territories","representation of the city","urban violence","social inequality","naturalism","contemporary Brazilian literature","short stories"]', '10.7476/9788542303087', '9788542301618', 'https://books.scielo.org/id/cszd4', NULL, NULL, 'https://books.scielo.org/id/cszd4/cover/cover_thumbnail.jpeg', 187, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ctchz', 'ctchz', 'Mitos e outras narrativas Kamayura', NULL, '["Pedro Agostinho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro é uma das mais relevantes coletâneas de mitos ameríndios das terras baixas da América do Sul, sendo exemplar pela cobertura ampla, densa e profunda que faz da mitologia Kamayurá. O mito constitui o modelo universal de explanação do mundo, estando na base de sua intensa vida cerimonial caracterizada pela beleza, pelo encanto e pela eficácia das artes e do corpo.', '["Amazonian indigenous peoples","ceremonial life"]', '10.7476/9788523212032', '9788523212032', 'https://books.scielo.org/id/ctchz', 'https://books.scielo.org/id/ctchz/pdf/agostinho-9788523212032.pdf', NULL, 'https://books.scielo.org/id/ctchz/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
