nguage = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cthmw', 'cthmw', 'Errante no campo da razão: o inédito na história; contribuição para um estudo de história e ecologia', NULL, '["Jozimar Paes de Almeida"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este trabalho objetivou realizar um estudo temático das relações da História com a Ecologia, procurando vincular esta análise a um referencial de uma dada sociedade, período e atividade produtiva. Procurei, através deste referencial, aplicar empiricamente em um determinado contexto histórico algumas reflexões teóricas, fruto dessa realidade constatada.', '["unpublished historical sources","historical ecology","historical context","productive activities"]', '10.7476/9788599662700', '9788599662700', 'https://books.scielo.org/id/cthmw', 'https://books.scielo.org/id/cthmw/pdf/almeida-9788599662700.pdf', NULL, 'https://books.scielo.org/id/cthmw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cvgxd', 'cvgxd', 'brazil digitaldivide com Confronting Inequality in the Information Society', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'The topic of this book, the digital divide, refers to the unequal distribution of resources associated with information and communication technology between countries and within societies. We will explore how one factor, in this case information technology, can potentially support contradictory tendencies: towards greater freedom and social participation and to deeper social inequality and new forms of concentration of power (excerpt taken from the book''s Introduction).', '["digital divide","information society","information and communication technologies","social inequality","social participation","concentration of power"]', '10.7476/9788599662489', '9788599662489', 'https://books.scielo.org/id/cvgxd', 'https://books.scielo.org/id/cvgxd/pdf/sorj-9788599662489.pdf', NULL, 'https://books.scielo.org/id/cvgxd/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cvrhf', 'cvrhf', 'A cruzada das crianças: intelectuais, cultura e política na América Latina', NULL, '["Alejandra Judith Josiowicz","Carolina de Souza Machado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-08-30', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro retrata a infância na produção literária de quatro importantes intelectuais latino-americanos: José Martí, Horacio Quiroga, Mário de Andrade e Clarice Lispector. Com base em uma diversificada gama de textos, pouco conhecidos do público, retirados de revistas, jornais, textos pedagógicos, livros destinados a adultos, jovens e crianças –, e em estendido recorte temporal, a autora reflete sobre como os intelectuais utilizaram-se da infância para analisar desigualdades sociais e renovar a linguagem literária. Resultado de tese de doutorado defendida na Universidade de Princeton, originalmente publicada em espanhol em 2018, esta edição em português conta com um último capítulo inédito, no qual analisam-se práticas culturais e políticas públicas latino-americanas voltadas para a preservação e a manutenção da saúde na infância.', '["children in literature","Latin American intellectuals","José Martí","Horacio Quiroga","Mário de Andrade","Clarice Lispector","social inequality","children''s literature","public health policy","cultural policy","Latin America"]', '10.7476/9786557082157', '9786557081525', 'https://books.scielo.org/id/cvrhf', NULL, NULL, 'https://books.scielo.org/id/cvrhf/cover/cover_thumbnail.jpeg', 294, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cvtx2', 'cvtx2', 'Prospectiva del desarrollo de competencias para los profesionales de contaduría pública desde la perspectiva de la formación por ciclos propedéuticos', NULL, '["Doris Stella Orduy Ruiz"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Recordando las palabras de uno de los personajes más internacionales en cuanto a gastronomía se refiere, Ferrán Adriá “No puedes tener una influencia de la cocina de un país si no la entiendes. Y para entenderla, tienes que estudiarla”. Y eso, es lo que han hecho los autores analizando con detalle un modelo de turismo gastronómico sostenible para la región Andina colombiana (subregión cundiboyacense) manifestado principalmente en un producto turístico (ruta gastronómica) compuesta a su vez por tours, anillos y recorridos turísticos en el eje vial que pasa por los municipios de Ventaquemada, Tunja, Sotáquira, Villa de Leyva y Sutamarchán', '["accounting education","propaedeutic cycles","competency-based training","professional development of accountants","food tourism","sustainable tourism","gastronomic routes","Andean region","Cundinamarca"]', '10.7476/9786289558234', '9786289558234', 'https://books.scielo.org/id/cvtx2', 'https://books.scielo.org/id/cvtx2/pdf/orduy-9786289558234.pdf', NULL, 'https://books.scielo.org/id/cvtx2/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cwcpz', 'cwcpz', 'O ensino de Ciências e as Tecnologias Digitais da Informação e Comunicação (TDIC): pesquisas desenvolvidas na educação básica', NULL, '["Ana Maria Osório Araya","Gustavo Bizarria Gibin","Moacir Pereira de Souza Filho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta uma coletânea de trabalhos sobre as tecnologias digitais da informação e comunicação (TDIC) e as novas metodologias de ensino desenvolvidas por meio de pesquisas sobre o ensino de Ciências e aplicadas na educação básica. O livro está dividido em duas partes: a primeira trata das potencialidades dessas novas tecnologias e das políticas e legislações que regem os cursos de formação de professores; a segunda, apresenta trabalhos desenvolvidos e aplicados no “chão da escola”, como animações com o stop motion; simulação com Phet sobre a escala de pH; o Phet utilizado no estudo gráfico de Cinemática; a Plataforma AppInventor para desenvolvimento de aplicativos para smartphones; o ensino híbrido com as ferramentas do Google for Education e relacionado à rotação de estações. A partir dessas abordagens, os autores desenvolvem e compartilham algumas experiências didáticas de sucesso de aplicação de Tecnologias Digitais da Informação e Comunicação (TDIC) no ensino de Física e de Química.', '["ICT in education","science education","basic education","stop-motion animation","PhET simulation","pH scale","kinematics","hybrid teaching","Google for Education","Earth rotation","teacher education policy","physics education"]', '10.7476/9786557140543', '9786557140543', 'https://books.scielo.org/id/cwcpz', 'https://books.scielo.org/id/cwcpz/pdf/araya-9786557140543.pdf', NULL, 'https://books.scielo.org/id/cwcpz/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cx2hy', 'cx2hy', 'Ensino superior e desenvolvimento regional: reconfigurando as relações entre as cidades e o campo', NULL, '["Maia, Doralice Sátyro","Glaúcio José Marafon"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os artigos aqui reunidos possibilitam o acesso aos resultados da pesquisa realizada sobre o ensino superior e o desenvolvimento regional: reconfigurando as relações entre as cidades e o campo. Dentre esses destaca-se a importância das políticas governamentais que promoveram a ampliação do ensino superior tanto através da criação de instituições de ensino superior federais, como de ensino técnico (IFs), mas também da rede privada que também se beneficiou de tal política. Tais repercussões vão além das cidades e municípios estudados, uma vez que atingem diretamente os municípios da região, mas também municípios de diferentes unidades federativas desde o sistema de acesso SISU. Acrescenta-se que o conjunto de textos que compõe este livro é apenas um registro da importância da temática eleita e da necessidade de se pesquisar a problemática abordada sob diferentes perspectivas analíticas, trata-se, pois, de um convite à continuidade da pesquisa.', '["higher education","regional development","urban-rural relations","federal universities","private higher education","SISU","university access","government education policy","municipalities"]', '10.7476/9786587949086', '9786587949086', 'https://books.scielo.org/id/cx2hy', 'https://books.scielo.org/id/cx2hy/pdf/maia-9786587949086.pdf', NULL, 'https://books.scielo.org/id/cx2hy/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cx47m', 'cx47m', 'Civilizaciones en disputa: Educación y evangelización en el territorio Shuar', NULL, '["José Enrique Juncosa Blasco"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La obra analiza cómo el pueblo shuar ejerció su capacidad de acción frente a las tres dimensiones de la misión salesiana: civilización, evangelización y educación, a través de movimientos que fluctúan entre la disputa, la resistencia y la apropiación en función de su existencia colectiva diferenciada. “Saber para prevalecer” expresa la expectativa histórica que explicó la aceptación de la alfabetización porque ofreció herramientas estratégicas que fortalecieron sus capacidades de confrontación con la colonización. La evangelización tardía, a su vez, fue asumida como condición de posibilidad para articular el territorio y las redes de liderazgo shuar. Finalmente, la investigación pone en escena las disputas civilizatorias de fondo que surgen de la relación entre misioneros y salesianos y que ofrecen, hoy, la posibilidad de remover los patrones civilizatorios de la modernidad colonialidad implantados en el territorio amazónico. Esas disputas enfrentan la desespiritualización de la naturaleza con la experiencia del territorio como ámbito sagrado de vida; la escisión del alma y el cuerpo con la espiritualidad que articula ambas instancias y las emociones; y el quiebre entre existencia y conocimiento con el conocimiento contextual y existencial del pueblo shuar. Cada capítulo abra con una “conversación” (aujmatsamu) ofrecida por hombres y mujeres shuar profesionales en las que narran su paso por las distintas etapas de educación formal a lo largo de su existencia. Ellos son: Serafín Patti Wajai, Rosa Naikiai Jintiach, Rosa Mariana Awak Tentets y José Nantipia Juepa, docentes del Instituto Nacional Bilingüe Intercultural Shuar Achuar de Bomboiza. Sus conversaciones constituyen lugares desde los que se abren preguntas antes que materiales sobre los cuales pensar o analizar, reorientado de muchas maneras el plan inicial de investigación y escritura hacia lugares imprevistos.', '["Shuar people","evangelism","indigenous education","literacy","coloniality","indigenous resistance","indigenous leadership","indigenous spirituality","indigenous knowledge","indigenous teachers","Amazon","indigenous territories"]', '10.7476/9789978105696', '9789978105696', 'https://books.scielo.org/id/cx47m', 'https://books.scielo.org/id/cx47m/pdf/juncosa-9789978105696.pdf', NULL, 'https://books.scielo.org/id/cx47m/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cxpqd', 'cxpqd', 'A escrita do passado entre monges e leigos: Portugal – séculos XIV e XV', NULL, '["Leandro Alves Teodoro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'other', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A escrita do passado entre monges e leigos é o testemunho direto da atual vitalidade dos estudos medievais no Brasil, em especial aqueles dedicados às novas problemáticas históricas sobre o reino português nos séculos finais da Idade Média. Leandro Alves Teodoro revisita as fontes cronísticas portuguesas oriundas de dois lugares de produção: o scriptorium do mosteiro de Santa Cruz de Coimbra e a corte régia quatrocentista da dinastia de Avis. O mérito deste livro está na comparação entre esses dois tipos de crônicas, desvelando o percurso da escrita da história em dois momentos distintos. No século XII, a fundação do mosteiro crúzio dos cônegos regrantes de Santo Agostinho esteve entrelaçada com a própria criação do reino de Portugal. Foram os monges os responsáveis pela constituição e pelo ordenamento da memória de glórias do reino. A partir de 1385, o autor analisa o processo de transformação dessa história monástica em um saber histórico laico nas mãos dos cronistas régios. Nesse processo, foram incorporados valores cristãos para que essas crônicas pudessem ter igualmente uma ação pedagógica na formação dos nobres cavaleiros do reino, buscando idealizar o presente e o futuro por meio dos triunfos do passado. Com um texto bem escrito, Teodoro propicia tanto a leitura prazerosa quanto o retorno às origens da arte da composição cronística portuguesa.', '["Portuguese chronicles","medieval historiography","Avis dynasty","monastic memory","education of the nobility","Kingdom of Portugal","late Middle Ages","14th century","15th century"]', '10.7476/9788539304356', '9788539304356', 'https://books.scielo.org/id/cxpqd', 'https://books.scielo.org/id/cxpqd/pdf/teodoro-9788539304356.pdf', NULL, 'https://books.scielo.org/id/cxpqd/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cy8br', 'cy8br', 'Saúde e jornalismo: interfaces contemporâneas', NULL, '["Kátia Lener","Igor Pinto Sacramento"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresenta análises sobre os modos como o campo jornalístico produz sentidos e representações sobre a saúde e a doença no contexto contemporâneo. Aborda as implicações das narrativas jornalísticas na construção do cuidado com a saúde; na preocupação com epidemias e com os riscos de adoecer e sofrer; na obsessão pelo bem estar e pela boa forma; e nas percepções sobre o SUS e os serviços públicos de saúde. Discute também teorias e procedimentos analíticos para o estudo da mediação jornalística no contexto da cobertura de temas da saúde.', '["medical journalism","media representation of health","disease","health narratives","health care","epidemics","risk perception","well-being","public health services","journalistic mediation","health insurance coverage"]', '10.7476/9788575415856', '9788575414545', 'https://books.scielo.org/id/cy8br', NULL, NULL, 'https://books.scielo.org/id/cy8br/cover/cover_thumbnail.jpeg', 269, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cywyh', 'cywyh', 'Avaliação por triangulação de métodos: abordagem de programas sociais', NULL, '["Maria Cecília de Souza Minayo","Simone Gonçalves de Assis","Edinilsa Ramos de Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro sintetiza teoria e prática para a análise, o acompanhamento e o monitoramento de programas sociais. Trata-se de obra inédita na literatura científica cuja proposta é servir de base para a pesquisa de gestores de programas sociais, professores e estudantes universitários e de pós-graduação que necessitem de conhecimentos técnicos e operacionais sobre como avaliar os resultados de ações sociais.', '["social programs","program evaluation","program management"]', '10.7476/9788575415474', '9788589697064', 'https://books.scielo.org/id/cywyh', NULL, NULL, 'https://books.scielo.org/id/cywyh/cover/cover_thumbnail.jpeg', 244, 340, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cz3jj', 'cz3jj', 'O poeta-espião: a antilírica de Sebastião Uchoa Leite', NULL, '["Paulo Andrade"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Paulo Andrade analisa nesta obra os procedimentos técnicos, temas e motivos construídos pelo poeta Sebastião Uchoa Leite para refletir sobre seu projeto poético e seu sujeito lírico. O estudo focaliza uma produção poética submetida a certa tensão, por desvios e aproximações, tanto com a tradição moderna quanto com as propostas modernistas, o que impossibilita demarcar limites para classificá-la. O grande mérito do autor é precisamente situar a obra de Uchoa nesse contexto específico.Andrade mostra que Uchoa não concebe o modernismo como força propulsora, mas como forma. O poeta não descarta as conquistas de 1922 e das décadas seguintes, no entanto, empenha-se em transgredi-las, contaminando-as com referências de toda ordem, seja da alta cultura, seja de elementos líricos retomados de tradições mais antigas, como a obra de François Villon, seja da cultura de massa ou de linguagens as mais diversas. Adepto do modernismo, Uchoa centra-se no contexto de seu tempo, e utiliza-se de uma linguagem concisa para expressar as preocupações em relação à cultura contemporânea.A análise de Andrade traz à tona um poeta que alia pensamento e poesia e, fortemente crítico à realidade, coloca-se em permanente desconfiança em relação ao mundo, ao outro e a si próprio. No percurso o estudo também aborda outros temas e procedimentos afins para articular a questão central, como o humor, a ironia, a autoironia e a difícil relação entre a retomada e a transgressão de certa tradição moderna, que faz de Uchoa um herdeiro singular de Paul Valéry, T. S. Eliot, João Cabral, Carlos Drummond, Manuel Bandeira e dos poetas concretistas.', '["Brazilian modernist poetry","lyric subject","François Villon","humor and irony","self-irony","Paul Valéry","T. S. Eliot","Manuel Bandeira","concretism","contemporary culture"]', '10.7476/9788568334409', '9788568334409', 'https://books.scielo.org/id/cz3jj', 'https://books.scielo.org/id/cz3jj/pdf/andrade-9788568334409.pdf', NULL, 'https://books.scielo.org/id/cz3jj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cz6y5', 'cz6y5', 'O mundo a zero: Drummond, Haroldo de Campos, Ricardo Aleixo e as máquinas do mundo', NULL, '["Eduardo Jorge de Oliveira"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nos anos recentes, Eduardo Jorge de Oliveira lançou para seus leitores e leitoras uma teia de conhecimentos translúcida e complexa. O poeta e o pesquisador coorganizam essa teia com abordagens marcadas pela transversalidade teórica, valendo-se do ensaio para analisar as derivações de conceitos e experiências estéticas. Integrados, esses aspectos nos estimulam a ver o real pela lente da especulação e nos lembram, com sutileza, das injunções que fazem uma experiência valer mais do que sugere a sua finitude. Um exemplo desse encadeamento pode ser observado em dois de seus livros: o ensaio crítico A invenção de uma pele (2018), dedicado à obra de Nuno Ramos, e o ensaio poético Teoria do hotel (2019), que mostram – sem desvendar de todo – o ponto de tangência entre o pensamento e as flutuações do lirismo. Em O mundo a zero, o autor parte desse ponto para dialogar com Carlos Drummond de Andrade, Haroldo de Campos e Ricardo Aleixo, vozes e corpos poéticos que se revelam, cada um à sua maneira, sensíveis às fricções da vida, da reflexão e dos artefatos da escrita. O mundo representado na tradição literária ocidental como máquina desafiadora ou lugar obscuro (e revisitado por esses poetas) nos intriga pela sua ambivalência, ora acolhendo, ora expulsando quem se dispõe a interpretá-lo. No presente ensaio, Eduardo Jorge investe na prática da interpretação para tecer indagações delicadas e contundentes sobre esse palco onde nossos dramas são encenados. O mundo a zero consiste, teoricamente, numa viagem às viagens que outros realizaram para confeccionar um certo modelo de mundo. Diferentes em suas personalidades, vincados por perdas e aquisições, esses autores pensam o mundo que tivemos e sondam o mundo que, talvez, devêssemos construir. Nas reflexões de Eduardo Jorge, o saber gerado por essas vozes constitui um testemunho estético no qual “se algo se perde da informação, algo se ganha na forma”. Assim, se o modelo camoniano entreviu nas ruínas um mundo tensionado por forças contrárias, os olhares de Drummond, Haroldo de Campos e Aleixo questionam, em algum momento, a sua existência tal como a conhecemos. Nesse sentido, este livro ressalta que as vozes poéticas deduzem do vazio, do precário, da ruína possibilidades de mundo, estabelecendo no poema “uma fabricação da realidade”. Tais possibilidades, mediadas por múltiplas formas de linguagem, instam o poeta a traduzir o intraduzível e os leitores a acionarem o desejo de decifrar o poema. É assim, regido por tensionamentos, que o mundo sobressai no tempo e no espaço. Não seria de outro modo, como demonstra Eduardo Jorge de Oliveira, que certa poesia e o pensamento crítico tentariam compreendê-lo.', '["Carlos Drummond de Andrade","Haroldo de Campos"]', '10.7476/9786558581581', '9786558581307', 'https://books.scielo.org/id/cz6y5', NULL, NULL, 'https://books.scielo.org/id/cz6y5/cover/cover_thumbnail.jpeg', 347, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-czm3m', 'czm3m', 'Imigração na União Europeia: uma leitura crítica a partir do nexo entre securitização, cidadania e identidade transnacional', NULL, '["Suzana de Souza Lima Velasco"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro analisa como o imigrante foi institucionalizado como ameaça existencial à União Europeia, sobretudo a partir dos anos 1990. Além de legislação e medidas securitárias, como controle de fronteiras e vistos, o livro se debruça sobre discursos políticos que identificam a imigração como um problema de segurança, com campanhas de partidos extremistas e casos de racismos contra mulçumanos e indivíduos de origem romana na UE. Mostra como esse processo se vincula à resistência do Estado Nação como lugar de identidade política e condição de cidadania.', '["immigration","European Union","securitization","citizenship","transnational identity","border control","Visa","security discourse","far-right parties","racism","Muslims","Roma"]', '10.7476/9788578792817', '9788578792817', 'https://books.scielo.org/id/czm3m', 'https://books.scielo.org/id/czm3m/pdf/velasco-9788578792817.pdf', NULL, 'https://books.scielo.org/id/czm3m/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-czwv6', 'czwv6', 'Entre sertões: comunismo e campesinato na obra de Bernardo Élis', NULL, '["Pauliane de Carvalho Braga"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As décadas de 1940 a 1960 foram marcadas por uma crescente organização dos trabalhadores rurais brasileiros, apoiados, em grande medida, pelo Partido Comunista do Brasil. A organização de Ligas Camponesas, associações e sindicatos rurais, e a realização de conferências e passeatas no campo foram vivenciadas pelo autor goiano Bernardo Élis e discutidas em sua obra literária. Considerado por muitos o introdutor do modernismo no Centro-Oeste, guia intelectual da região por décadas e comunista “notório”, Élis orientou sua reflexão para o universo particular do sertanejo e para a força de suas reações diante do mundo. Ao costurar história, política e ficção, o autor oferece um anova leitura sobre o campo brasileiro, iluminando possibilidades e/ou apontando os limites de um mundo que não poderia mais existir.', '["Bernardo Élis","communism","peasants","sertão","rural workers","Partido Comunista do Brasil","rural unions","Goiás","Brazilian modernism","sertanejos","rural Brazil","literature and politics"]', '10.7476/9786558580133', '9788542302639', 'https://books.scielo.org/id/czwv6', NULL, NULL, 'https://books.scielo.org/id/czwv6/cover/cover_thumbnail.jpeg', 156, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
