publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d2frp', 'd2frp', 'Antropologia, saúde e envelhecimento', NULL, '["Carlos Ε. A. Coimbra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea de artigos que se propõe a desvendar os rótulos impostos pela sociedade à ''terceira idade''. Dessa forma, poderemos acompanhar as transformações ocorridas nessa faixa etária, como o crescimento demográfico, e refletir sobre o idoso do futuro. Analisa-se, na obra, o envelhecimento sob o ponto de vista dos próprios idosos e idosas, revelando o que significa ser saudável para eles e elas. Constrói um idoso que protagoniza sua própria história, em vez de se corroborar a idéia estereotipada do velho como um fardo para a família e para a sociedade.', '["aging","older adults","elderly health","age stereotypes","social representations of aging","population growth","future of aging","health perception","anthropology of aging"]', '10.7476/9788575413043', '9788575413043', 'https://books.scielo.org/id/d2frp', 'https://books.scielo.org/id/d2frp/pdf/minayo-9788575413043.pdf', NULL, 'https://books.scielo.org/id/d2frp/cover/cover_thumbnail.jpeg', NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d2vfg', 'd2vfg', 'Descartes: diálogos musicais', 'diálogos musicais', '["Tiago de Lima Castro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O filósofo René Descartes escreveu o Compendium musicæ em 1618. Mesmo não sendo conhecido pela sua produção musical, manteve uma longa correspondência em torno do assunto, principalmente em diálogo com Marin Mersenne, Constantjin Huygens, Isaac Beeckman e Joan-Albert Ban. Contudo, suas proposições em torno da música são tidas como um assunto marginal em seu percurso intelectual. Para compreender se a temática musical se relaciona com o desenvolvimento de suas ideias, primeiramente, foi organizado a sua correspondência sobre música e as citações a esta em suas obras, sejam em textos menores ou nas obras publicadas pelo autor.', '["René Descartes","music theory","Marin Mersenne","Constantijn Huygens","Isaac Beeckman","philosophy of music","17th-century music"]', '10.7476/9786559544417', '9786559544417', 'https://books.scielo.org/id/d2vfg', 'https://books.scielo.org/id/d2vfg/pdf/castro-9786559544417.pdf', NULL, 'https://books.scielo.org/id/d2vfg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d3532', 'd3532', 'Gravidez na adolescência: entre fatos e estereótipos', NULL, '["Aline de Carvalho Martins"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-09-21', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este livro te convida a refletir sobre a necessidade de articular as vivências individuais aos processos históricos e à questão dos direitos humanos e reprodutivos permitindo pensar a centralidade, a autonomia e o desenvolvimento das mulheres.', '["adolescent pregnancy","adolescence","stereotypes","reproductive rights","human rights","women''s autonomy","women''s development"]', '10.7476/9786557081181', '9786557080436', 'https://books.scielo.org/id/d3532', NULL, NULL, 'https://books.scielo.org/id/d3532/cover/cover_thumbnail.jpeg', 163, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d36xv', 'd36xv', 'In memoriam: urbanismo, literatura e morte', NULL, '["Ribeiro, André Luiz Rosa"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2017, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Este livro propõe compreender práticas e representações relativas à morte no sul da Bahia, relacionando-as com o contexto histórico de emergência e florescimento do urbanismo regional. Enfoca os mecanismos baseados na construção da memória, utilizados na afirmação do poder de determinados grupos políticos. Na análise das formas arquitetônicas e dos materiais empregados em túmulos percebe-se o vínculo entre os discursos construídos sobre a morte e a trajetória das relações sociais locais.', '[]', '10.7476/9786586213881', '9788574554501', 'https://books.scielo.org/id/d36xv', 'https://books.scielo.org/id/d36xv/pdf/ribeiro-9786586213881.pdf', 'https://books.scielo.org/id/d36xv/epub/ribeiro-9786586213881.epub', 'https://books.scielo.org/id/d36xv/cover/cover_thumbnail.jpeg', 267, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d38dc', 'd38dc', 'Contextos de ocorrência da gravidez não planejada em mulheres adultas', NULL, '["Boer, Jussilene Jesus Sousa","Coelho, Edméia de Almeida Cardoso","Barros, Andiara Rodrigues"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra divulga resultados de pesquisa em que foram investigadas circunstâncias da ocorrência de gravidez não planejada em mulheres adultas sob o enfoque de gênero. Seus resultados revelam múltiplas interseções entre fatores que participam da ocorrência da gravidez não planejada, com forte presença das relações com o parceiro e com o serviço de saúde. As autoras reforçam que o acolhimento, o acesso à informação de qualidade e aos métodos contraceptivos assegurados nos serviços de saúde são essenciais para que os direitos reprodutivos sejam plenamente exercidos pelas mulheres.', '["unintended pregnancy","adult women","gender perspective","reproductive rights","contraceptive access","contraceptive information","couple relationships","health services","intersectionality"]', '10.7476/9786556308944', '9786556306643', 'https://books.scielo.org/id/d38dc', 'https://books.scielo.org/id/d38dc/pdf/boer-9786556308944.pdf', NULL, 'https://books.scielo.org/id/d38dc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d3r7w', 'd3r7w', 'As teorias e o caso', NULL, '["Mariana Batista","Ednaldo Ribeiro","Rogério Bastos Arantes"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'De cunho teórico e analítico, a presente obra tem como objetivo fortalecer a reflexão sobre a Ciência Política praticada no Brasil e sobre o Brasil como caso concreto. Seu amplo escopo reflete o engajamento das diferentes áreas ou subdisciplinas da Ciência Política nacional. O eixo principal do livro, comum a todos os capítulos, se baseia no levantamento das principais teorias (em perspectiva comparada) que têm sido mobilizadas para compreender o caso brasileiro, acompanhado de reflexões e análises sobre como as características específicas do nosso contexto incidem ao mesmo tempo na utilização, aplicabilidade e limitações dessas teorias. Dessa forma, o livro serve ao duplo propósito de realizar um levantamento dos principais argumentos usados pelos pesquisadores nacionais, oferecendo ao leitor um estado da arte da pesquisa em Ciência Política, e mapear as principais características do Brasil como caso concreto e como essas características importam para a avaliação das teorias produzidas aqui e no exterior.', '["political theory","comparative theory","theory testing"]', '10.7476/9786589992295', '9786589992295', 'https://books.scielo.org/id/d3r7w', 'https://books.scielo.org/id/d3r7w/pdf/batista-9786589992295.pdf', NULL, 'https://books.scielo.org/id/d3r7w/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d48x7', 'd48x7', 'Uma escola para a saúde', NULL, '["Nísia Trindade Lima","Cristina M. Oliveira Fonseca","Paulo Roberto Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta os caminhos percorridos na direção da profissionalização e da especialização em saúde pública no Brasil, refletindo as influências e iniciativas nacionais e internacionais.na criação da Escola Nacional de Saúde Pública (Ensp), em 1954. Nesse laboratório de idéias em que se constituiu a Escola, formularam-se propostas que contribuíram para as grandes conquistas da saúde pública brasileira e que subsidiaram o processo de Reforma Sanitária, cujos resultados se expressam na constituição e no fortalecimento do SUS. Organizado em duas partes, na primeira é apresentado um texto narrativo sucinto sobre a Ensp, desde a sua criação até os anos recentes. A segunda, traz artigos sobre temas relevantes para o entendimento da história da Ensp e de seu papel na saúde pública contemporânea.', '["history of public health education","Reforma Sanitária","Brazilian public health"]', '10.7476/9788575414002', '9788575414002', 'https://books.scielo.org/id/d48x7', 'https://books.scielo.org/id/d48x7/pdf/lima-9788575414002.pdf', NULL, 'https://books.scielo.org/id/d48x7/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d4fr6', 'd4fr6', 'Légua tirana: sociedade e economia no alto sertão da Bahia / Caetité, 1890-1930', NULL, '["Paulo Henrique Duque Santos"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Paulo Duque, historiador e pesquisador nato, participa ativamente de uma renovada produção historiográfica sobre os sertões da Bahia, uma produção que tem custado muitos esforços a todos aqueles que perseguem outros caminhos. Este livro move-se no sentido contrário aos estereótipos de um sertão atavicamente envolto em rudezas, incivilidades, isolamentos. Essa imagem distorcida e preconceituosa, que ainda encontra assentimento em nossos dias, tem suas bases desmontadas diante do livro. Leitura fundamental para todos que querem conhecer melhor o Brasil.', '["sertão","Caetité","Bahia","rural society","rural economy","agricultural history"]', '10.7476/9786588211960', '9786588211830', 'https://books.scielo.org/id/d4fr6', 'https://books.scielo.org/id/d4fr6/pdf/santos-9786588211960.pdf', 'https://books.scielo.org/id/d4fr6/epub/santos-9786588211960.epub', 'https://books.scielo.org/id/d4fr6/cover/cover_thumbnail.jpeg', 328, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
