ions.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d56ks', 'd56ks', 'Metodología para la planificación energética a partir de la norma ISO 50001', NULL, '["Rosaura del Pilar Castrillón Mendoza","Adriana Janeth González Hinestroza"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Colombia', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Energy', 'Metodología para la planificación energética a partir de la norma ISO 50001, es una propuesta para la ejecución de la etapa de planificación energética en la implementación de un Sistema de Gestión Energética (SGE) acorde con los requisitos de la norma ISO 50001. Cada una de los capítulos de la planificación energética, se desarro­lla a través de una propuesta metodológica y el uso de herramientas apli­cadas en casos demostrativos, lo cual permite a las organizaciones contar con una referencia técnica para la implementación de esta etapa.', '["energy planning","ISO 50001","energy management systems","energy management system implementation","energy efficiency"]', '10.7476/9789588994604', '9789588994598', 'https://books.scielo.org/id/d56ks', NULL, NULL, 'https://books.scielo.org/id/d56ks/cover/cover_thumbnail.jpeg', 274, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d5t55', 'd5t55', 'O Clássico e o Novo: tendências, objetos e abordagens em ciências sociais e saúde', 'tendências, objetos e abordagens em ciências sociais e saúde', '["Paulete Goldenberg","Regina Maria Giffoni Marsiglia","Mara H. de Andréa Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Tratando de temas, como a cultura e a subjetividade, as questões éticas da atualidade, a qualidade de vida no mundo contemporâneo etc., O Clássico e o Novo é o fruto de trabalhos apresentados no 2o Congresso Brasileiro de Ciências Sociais em Saúde, e reúne uma gama dos mais qualificados profissionais que tratam de diferentes temas, intencionando uma perspectiva multidisciplinar. Partindo do pressuposto de que dentro da própria área das Ciências Sociais há um processo de fragmentação que vem exigindo cada vez mais novas interlocuções interdisciplinares, procura-se aqui estabelecer um diálogo profícuo entre este campo do saber e a área da saúde. Dessa forma, ao abordar questões relacionadas à área da saúde, este livro se constitui como leitura obrigatória para os profissionais de saúde coletiva, introduzindo diferentes e instigantes propostas de reflexão para a saúde na atualidade.', '["social sciences and health","interdisciplinary dialogue","ethics","quality of life","collective health","healthcare workers"]', '10.7476/9788575412510', '9788575410257', 'https://books.scielo.org/id/d5t55', 'https://books.scielo.org/id/d5t55/pdf/goldenberg-9788575412510.pdf', NULL, 'https://books.scielo.org/id/d5t55/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d63fk', 'd63fk', 'Fundamentos da vigilância sanitária', NULL, '["Suely Rozenfeld"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Instância de mediação entre a produção de bens e serviços variados e a saúde da população, a complexidade da Vigilância Sanitária (VS) impõe um enfoque multidisciplinar. Este aparece em cada um dos capítulos desta coletânea: a sociologia, que fornece o instrumental para a análise histórica e para a compreensão do papel do Estado, a epidemiologia, o planejamento, a legislação e a avaliação, que fornecem os conceitos, os procedimentos e as técnicas necessárias ao desempenho da função reguladora e normativa. Define e constrói, assim, um tripé de competências para qualificar o agir em VS: conhecimento técnico, responsabilidade pública e compromisso ético. Alcança e interessa, assim, não só a profissionais de saúde, como àqueles em busca de uma educação para a cidadania.', '["disease surveillance","multidisciplinary approach","medical sociology","epidemiology","health planning","health care legislation","health assessment","regulatory function","public responsibility","professional ethics","citizenship education"]', '10.7476/9788575413258', '9788575413258', 'https://books.scielo.org/id/d63fk', 'https://books.scielo.org/id/d63fk/pdf/rozenfeld-9788575413258.pdf', NULL, 'https://books.scielo.org/id/d63fk/cover/cover_thumbnail.jpeg', NULL, 37, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d6bcc', 'd6bcc', 'Arte e vida no século XXI: tecnologia, ciência e criatividade', NULL, '["Diana Maria Gallicchio Domingues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro testemunha alguns dos desenvolvimentos artísticos mais recentes, tal como a ciberarte, a poesia, o teatro interativo, a arte genética e a arte transgênica. Nesse horizonte estético, aparecem visões tal como aquela de Roy Ascott, que prevê o advento de "mídias úmidas", caracterizadas por simbioses pós-biológicas entre a telemática, a biotecnologia e a nanoengenharia. É por tudo isso que as documentações contemporâneas e as visões futuristas deste livro serão capazes de conduzir os leitores além do limiar da cibercultura até os confins do horizonte de uma estética pós-biológica e uma cultura pós-humana.', '["cyberart","interactive theatre","transgenic art","Roy Ascott","posthumanism","biotechnology in art","nanotechnology","telematics","digital culture","poetry","technology and creativity"]', '10.7476/9788539302826', '9788571394896', 'https://books.scielo.org/id/d6bcc', NULL, NULL, 'https://books.scielo.org/id/d6bcc/cover/cover_thumbnail.jpeg', 380, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d7pyr', 'd7pyr', 'Em busca do som: a música de Karlheinz Stockhausen nos anos 1950', NULL, '["Gustavo Oliveira Alfaix Assis"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Gustavo Alfaix se dedica ao estudo do universo estético do compositor alemão Karlheinz Stockhausen, um dos artistas mais relevantes da segunda metade do século XX, concentrando-se nas suas criações da década de 1950. Esse recorte temporal foi estabelecido justamente por colocar em foco a época áurea da música serial, período no qual se podem encontrar as raízes de boa parte das perspectivas que, nos anos seguintes, levariam à formação das diversas escolas estéticas que compõem o rico cenário da música atual. Com análises detalhadas e reproduções de trechos de partituras de Stockhausen, bem como dos escritos conceituais do compositor e de outros importantes musicólogos, Alfaix investiga os principais conceitos e estratégias composicionais elaborados por Stockhausen ao longo de sua carreira. O texto também lança luz na articulação entre o desenvolvimento do pensamento teórico do compositor e sua materialização na forma de obras musicais, além de observar a relação entre o processo criativo do artista e sua biografia, com atenção sobre as personalidades que o influen­ciaram e contribuíram para a consolidação de sua poética musical.', '["Karlheinz Stockhausen","serial music","1950s music","compositional techniques","music aesthetics","music theory","creative process","musical poetics","German composers","20th-century music"]', '10.7476/9786557145258', '9786557145258', 'https://books.scielo.org/id/d7pyr', 'https://books.scielo.org/id/d7pyr/pdf/assis-9786557145258.pdf', NULL, 'https://books.scielo.org/id/d7pyr/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d7tch', 'd7tch', 'Biodiesel o "Óleo Filosofal": desafios para a educação ambiental no caldeirão do "desenvolvimento sustentável"', NULL, '["Jozimar Paes de Almeida"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Tivemos como objetivo principal de nosso trabalho expressar uma contribuição para efetivação de consciência ambiental, por intermédio de reflexão histórica buscando analisar o Programa Nacional de Produção e uso do Biodiesel (PNPB) do Ministério da Ciência e Tecnologia, gerado, ao nosso ver, pela inspiração dos preceitos do “desenvolvimento sustentável que preceitua o crescimento econômico como solução para problemas sócio-ambientais. [trecho retirado da apresentação do livro]', '["biodiesel","environmental education","environmental awareness","sustainable development","economic growth","socio-environmental problems","history of environmental thought"]', '10.7476/9788579820274', '9788579820274', 'https://books.scielo.org/id/d7tch', 'https://books.scielo.org/id/d7tch/pdf/almeida-9788579820274.pdf', NULL, 'https://books.scielo.org/id/d7tch/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d823m', 'd823m', 'Mejigã e o contexto da escravidão', NULL, '["Ruy do Carmo Póvoas"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é resultado de pesquisas do Núcleo de Estudos Afro-Baianos Regionais, o Kawé, e traz textos sobre os saberes transmitidos pela oralidade, que guardam parte da história regional contada sob a perspectiva do excluído. Memórias e história da superação de Inês Maria, de nome nagô Mejigã, sacerdotisa de Oxum na África, escrava no Engenho de Santana, em Ilhéus. Como destaca o organizador, Mejigã é destinado não só a acadêmicos, mas a integrantes de movimentos sociais e estudantes em geral.', '["slavery","Afro-Brazilian women","oral tradition","memory","Oxum","Ilhéus","regional history","marginalized voices","social movements"]', '10.7476/9788574555508', '9788574555508', 'https://books.scielo.org/id/d823m', 'https://books.scielo.org/id/d823m/pdf/povoas-9788574555508.pdf', NULL, 'https://books.scielo.org/id/d823m/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d83gz', 'd83gz', 'Pérolas negras – primeiros fios: experiências artísticas e culturais nos fluxos entre África e Brasil', NULL, '["Roberto Conduru"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aborda as diversas ideias e realizações da arte, da história da arte e da cultura vinculadas às questões da africanidade e da afro-brasilidade, com cortes espaciais e temporais heterogêneos, resultando em uma abordagem de caráter multidisciplinar, com incursões na antropologia, na sociologia e em outras áreas do conhecimento humano. Em 42 ensaios, tece reflexões sobre o legado africano para a sociedade brasileira, observando aspectos como a religião, o artesanato e as representações da arte africana nos museus, além de outros tópicos.', '["African diaspora in Brazil","Afro-Brazilian culture","African art","African traditional religion","art history"]', '10.7476/9786588808054', '9788575113042', 'https://books.scielo.org/id/d83gz', NULL, NULL, 'https://books.scielo.org/id/d83gz/cover/cover_thumbnail.jpeg', 390, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d86tj', 'd86tj', 'A busca da perfeição: o ideário eugenista em pauta', NULL, '["Maria Lúcia Boarini"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A imagem que ilustra a capa deste livro apresenta a escultura intitulada ‘Apolo Belvedere’. , em exposição no Museu Pio-Clementino, no Vaticano. A data de sua origem e autoria são controversas, mas considera-se que seja uma cópia romana, em mármore, de um original grego perdido. Representando o deus grego Apolo, tal escultura se tornou a expressão do ideal da perfeição, característico da civilização helênica. Note-se que esse ideal, embora remetendo à beleza, não se restringia ao aspecto estético, pois o belo era associada, pelos gregos, ao amor, à sabedoria, à justiça, à virtude, à bondade e à coragem. Nessa associação está implícita a ideia de um homem superior, perfeito, como modelo cultural, orientado por valores maiores, que geraria os melhores cidadãos. Tal concepção tem suas raízes no período homérico e se consolida no auge da democracia ateniense. Apolo, filho de Zeus e Leto, é o deus da música, das artes, das profecias, da purificação, da cura, da luminosidade solar, da justa medida, da juventude. Ele sintetiza os princípios da ordem, da harmonia, da razão, do equilíbrio e da moderação. Por ser uma divindade multifacetada, por vezes paradoxal, pois também apresenta aspectos antagônicos às suas próprias qualidades, ele harmoniza em si as polaridades, direcionando-as para o ideal da cultura e da sabedoria. Por isso, tornou-se para o povo grego a expressão do ideal da perfeição, sendo considerado uma autêntica personificação do espírito helênico.', '["eugenics","eugenic ideology","perfection","Greek culture","sculpture","beauty and virtue","Athenian democracy"]', '10.7476/9786586383041', '9788576287650', 'https://books.scielo.org/id/d86tj', NULL, NULL, 'https://books.scielo.org/id/d86tj/cover/cover_thumbnail.jpeg', 234, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d8w6k', 'd8w6k', 'Duas ou três páginas despretensiosas: a crônica, Rubem Braga e outros cronistas', NULL, '["Luiz Carlos Santos Simon"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Segundo Eduardo Coutinho, a obra trata de um texto bastante atual, que aborda a crônica em vários de seus aspectos, no período que se estende desde a primeira metade do século XX ao início do século XXI, deixando claro que o gênero continua vivo e em plena efervescência no momento presente. Além disso, inclui uma bibliografia relevante e bastante atualizada sobre o assunto e uma relação bastante completa de livros de crônicas publicados no período de 1936 até o presente.', '["chronicles","Rubem Braga","chronicle writers","chronicle genre","Brazilian literature","literary genre history"]', '10.7476/9788572166522', '9788572166522', 'https://books.scielo.org/id/d8w6k', NULL, NULL, 'https://books.scielo.org/id/d8w6k/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d8ysn', 'd8ysn', 'Memória muscular: um estudo interdisciplinar sobre a performance no violoncelo', NULL, '["Joel Silva de Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Após séculos de desenvolvimento dos aspectos particulares da técnica do violoncelo, entramos numa era de natureza interdisciplinar, ou seja, caracterizada pela busca de respostas em outras áreas do conhecimento. Nas últimas décadas, a Neurociência, Cognição, Psicologia Cognitiva e Educação Física avançaram muito nas pesquisas sobre a aprendizagem motora, incluindo memórias motora de precisão, principalmente nos estudos realizados com músicos. Essas pesquisas podem auxiliar sobremaneira na eficácia do aprendizado e da prática; o resultado poderá gerar uma proposta técnica e pedagógica inovadora de um sistema de aprendizado sensório-motor mais eficiente, baseado em informações científicas. Dessa forma, pretende-se que este trabalho sirva de referência para músicos e educadores, não só de violoncelo, mas também de outros instrumentos, a fim de que se evitem práticas de repetições prejudiciais e que a aprendizagem e a performance sejam otimizadas.', '["motor memory","cello performance","motor learning","musicians","sensorimotor learning","cello pedagogy","cognitive psychology","neuroscience of music","repeated practice"]', '10.7476/9786559542505', '9786559542505', 'https://books.scielo.org/id/d8ysn', 'https://books.scielo.org/id/d8ysn/pdf/souza-9786559542505.pdf', NULL, 'https://books.scielo.org/id/d8ysn/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-d9md3', 'd9md3', 'Incentivo fiscal à alimentação do trabalhador: uma abordagem sociogenética', NULL, '["Jamacy Costa Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Num diálogo entre as áreas da nutrição e da saúde coletiva, o autor realiza um trabalho investigativo acerca do Programa de Incetivo Fiscal à Alimentação do Trabalhor (Pifat) ou Programa de Alimentação do Trabalhador (Pat), até então pouco discutido, enveredando-se numa análise sociogenética do programa. Ele remonta à década de 1930, quando surgiram as primeiras políticas públicas do tipo, desenvolvendo o seu estudo até chegar às problemáticas surgidas durante a implantação do programa, envolvendo os agentes e as instituições que participaram do processo.', '["public health policy","nutrition policy","public policy history","1930s","program implementation problems"]', '10.7476/9788523218560', '9788523217761', 'https://books.scielo.org/id/d9md3', NULL, NULL, 'https://books.scielo.org/id/d9md3/cover/cover_thumbnail.jpeg', 256, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
