INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-db92q', 'db92q', 'Migrações e refúgio: identidade, economia e legislação em debate', NULL, '["Maria Luiza Silva Santos","Clodoaldo Silva da Anunciação"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os temas centrais são debatidos nos diversos textos selecionados no 1o Colóquio Internacional e Interdisciplinar sobre migrações e refúgio, propiciando uma interlocução com a economia, o direito e as legislações que amparam os dois institutos, bem como com a cultura e a identidade.', '["migration","refugees","identity","migration economics","migration law","refugee law","culture","legal protection of migrants"]', '10.7476/9786586213867', '9786586213263', 'https://books.scielo.org/id/db92q', NULL, NULL, 'https://books.scielo.org/id/db92q/cover/cover_thumbnail.jpeg', 350, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dbkwz', 'dbkwz', 'Loucos e degenerados: uma genealogia da psiquiatria ampliada', NULL, '["Sandra Noemi Caponi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'É crescente a lista de problemas que se transformaram em objeto de intervenção da psiquiatria: tristeza profunda, estado de angústia, dificuldade de aprendizagem e sentimento de fracasso - conflitos da vida social são agora pensados em termos médicos e tratados com medicamentos, o que pode ter consequências prejudiciais. Numa perspectiva crítica, a autora deste livro foi buscar na história os elementos que ajudam a entender como se naturalizaram essas explicações biológicas - e reducionistas - para as mazelas humanas, expandindo a psiquiatria e tornando-a uma estratégia biopolítica, segundo o referencial teórico de Michel Foucault. Sandra Caponi, doutora em filosofia e professora da Universidade Federal de Santa Catarina (UFSC), discute, em especial, o desenvolvimento da teoria da degeneração, conceito originário da história natural e aplicado à medicina. “Assim, a transformação epistemológica que permitiu, na segunda metade do século XIX, que a psiquiatria expandisse seu espaço de intervenção para a quase totalidade dos assuntos humanos parece persistir - ainda que profundamente transfigurada - nos atuais esforços para consolidar uma psiquiatria ampliada que se relaciona com a medicalização do não patológico”, resume.', '["degeneration theory","biopolitics","biological reductionism","history of psychiatry","Michel Foucault","epistemology of psychiatry","melancholy","anxiety","learning difficulties","social conflict"]', '10.7476/9788575413340', '9788575412282', 'https://books.scielo.org/id/dbkwz', NULL, NULL, 'https://books.scielo.org/id/dbkwz/cover/cover_thumbnail.jpeg', 210, 126, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dbqbq', 'dbqbq', 'Subjetividade, gestão e cuidado em saúde: abordagens da psicossociologia', NULL, '["Creuza da Silva Azevedo","Marilene de Castilho Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Os valores dominantes na atualidade – onde os laços sociais se enfraquecem e o domínio privado recrudesce em detrimento do público – parecem seguir na contramão dos princípios da Reforma Sanitária, o que coloca um imenso desafio para o campo da saúde coletiva. Para fazer face a esse processo em curso de descuido com as pessoas e valorização exagerada da racionalidade, autores propõem uma abordagem diferenciada de pesquisa e intervenção, apresentada neste livro. Trata-se de um caminho de investigação que vem sendo trilhado pelas organizadoras da coletânea e que articula três eixos: a abordagem da psicossociologia francesa sobre as organizações e a sociedade (de Eugène Enriquez e André Lévy); a teoria psicanalítica sobre os processos intersubjetivos e grupais (de René Kaës); e a psicodinâmica do trabalho (de Christophe Dejours). O livro está dividido em duas partes. A primeira traz uma discussão teórico-conceitual e se encerra com a exposição de bases metodológicas para a abordagem proposta. Analisam-se as possibilidades de mudança no cuidado e na gestão, pautadas pela valorização da subjetividade, pela capacidade de escuta, pelos espaços de diálogo e troca e pela inventividade no cotidiano do trabalho. Já a segunda parte reúne estudos empíricos e exemplos de intervenções. São pesquisas e/ou ações em hospitais, em serviços de atenção psicossocial, em uma unidade de saúde da família e em um serviço especializado de oncologia pediátrica, além de uma intervenção clínica psicossociológica em um curso de gestão da Escola Nacional de Saúde Pública (Ensp/Fiocruz).', '["subjectivity","health management","health care","social psychology","René Kaës","listening","dialogue","Reforma Sanitária","collective care","hospitals","family health unit","pediatric oncology"]', '10.7476/9788575415351', '9788575414316', 'https://books.scielo.org/id/dbqbq', 'https://books.scielo.org/id/dbqbq/pdf/azevedo-9788575415351.pdf', 'https://books.scielo.org/id/dbqbq/epub/azevedo-9788575415351.epub', 'https://books.scielo.org/id/dbqbq/cover/cover_thumbnail.jpeg', 421, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dc3s6', 'dc3s6', 'A militarização da burocracia: a participação militar na administração federal das Comunicações e da Educação - 1963-1990', NULL, '["Suzeley Kalil Mathias"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Livro que enfoca parte importante da militarização da burocracia, com a influência direta das Forças Armadas em instâncias estatais de natureza civil (Comunicações e Educação). Expressa o destaque de tais áreas, a perspectiva gerencial e política de alguns setores militares sobre assuntos relevantes, nos quais reconheciam valor estratégico para o desenvolvimento do Estado. Demonstrada a importância fundamental da Educação e das Comunicações para o Estado no regime militar, a autora revela meandros da administração pública nesses dois Ministérios, durante um período de 27 anos. (co- edição: FAPESP)', '["Brazilian military dictatorship","public administration","telecommunications administration","educational management"]', '10.7476/9788539303243', '9788571395411', 'https://books.scielo.org/id/dc3s6', NULL, NULL, 'https://books.scielo.org/id/dc3s6/cover/cover_thumbnail.jpeg', 226, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dc3xq', 'dc3xq', 'Guimarães Rosa: dimensões da narrativa', NULL, '["Maria Célia Leonel","Edna Maria F. S. Nascimento"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os onze ensaios aqui reunidos agrupam-se em duas partes: “Estudos comparativos” e “Aspectos da narrativa rosiana”. A primeira tem como eixos a relação entre narrativas de Guimarães Rosa e escritos literários de outros autores e a relação entre elas e produções cinematográficas que traduzem para outra linguagem o universo do escritor mineiro. Os estudos da segunda parte – além de sugerirem um possível caminho para a construção de uma poética rosiana a partir de juízos do próprio escritor, sobretudo acerca da literatura e de sua relação com a língua, em escritos não literários e também literários – demonstram como, na construção da narrativa rosiana, é explorada a relação entre som e sentido, analisam como o autor trata as paixões humanas que desafiam os padrões impostos pela razão e salientam a antropomorfização da natureza como componente erótico. As autoras, com esta publicação, almejam contribuir para uma melhor compreensão da obra de Guimarães Rosa e suscitar reflexões, pois, como ele escreveu em Grande sertão: veredas, “Vivendo, se aprende; mas o que se aprende, mais, é só a fazer outras maiores perguntas”.', '["Guimarães Rosa","Brazilian literature","narrative poetics","comparative literature","film adaptation","language and literature","sound and meaning","human passions","reason and passion","anthropomorphism of nature","eroticism","Grande Sertão: Veredas"]', '10.7476/9786557143018', '9786557143018', 'https://books.scielo.org/id/dc3xq', 'https://books.scielo.org/id/dc3xq/pdf/leonel-9786557143018.pdf', NULL, 'https://books.scielo.org/id/dc3xq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dc7xf', 'dc7xf', 'Territórios de Criação: práticas artístico-pedagógicas do teatro de grupo inscritas na construção coletiva da cidade', 'práticas artístico-pedagógicas do teatro de grupo inscritas na construção coletiva da cidade', '["Caio Sérgio de Castro Armada Floret Franzolin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A partir da articulação de referencial teórico, pesquisa de campo e experiências como integrante de coletivo do teatro de grupo, o autor deste livro procura analisar a relação entre núcleos artísticos do teatro de grupo da cidade de São Paulo e o entorno de seus espaços culturais, aqui chamados de territórios de criação, a partir do ponto de vista da ação cultural. Para se entender estas interações foram realizadas entrevistas com integrantes de oito coletivos em atividade. Na leitura da atuação teatral de coletivos da cidade de São Paulo se revelou fundamental um olhar para além das produções de seus espetáculos. As ações arte-educativas nos territórios, desenvolvidas pelos grupos são experiências espalhadas pelo tecido urbano. Para o desenvolvimento do estudo foram estabelecidas interlocuções teóricas com pensadoras e pensadores que abordam como temas a pedagogia do teatro, o sujeito histórico teatro de grupo, o espaço urbano, o território e a ação cultural.', '["group theatre","art education","theatre pedagogy","collective creation","cultural action","urban space","territory","São Paulo","theatre collectives"]', '10.7476/9786559543793', '9786559543793', 'https://books.scielo.org/id/dc7xf', 'https://books.scielo.org/id/dc7xf/pdf/franzolin-9786559543793.pdf', NULL, 'https://books.scielo.org/id/dc7xf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dc9km', 'dc9km', 'Novos horizontes do Brasil na quarta transformação estrutural', NULL, '["Marcio Pochmann"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Os cinco capítulos que estruturam este livro oferecem ao leitor uma narrativa distinta da usual do Brasil contemporâneo, ao partir da hipótese de que a nação se encontra diante de uma profunda mudança de época. A quarta transformação estrutural do Brasil pós-colonial equipara-se tanto à fundação da nação no início do século XIX quanto à passagem para o modo de produção capitalista no final desse mesmo século. Também indica equivalência à transição do antigo e primitivo agrarismo para a moderna sociedade urbana e industrial estabelecida pela Revolução de 1930. Na marcha da quarta transformação estrutural, a passagem para a era digital transcorre diante do deslocamento do centro dinâmico do mundo do Ocidente para o Oriente simultaneamente à emergência climática imposta pelo Antropoceno.', '["nation-building","capitalist mode of production","agrarianism","urbanization","industrialization","1930 Revolution","digital era","Anthropocene","climate change"]', '10.7476/9788526816718', '9788526815636', 'https://books.scielo.org/id/dc9km', NULL, NULL, 'https://books.scielo.org/id/dc9km/cover/cover_thumbnail.jpeg', 167, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dc9yf', 'dc9yf', 'Geografia cultural: uma antologia, Vol. 1', NULL, '["Roberto Lobato Corrêa","Zeny Rosendahl"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Resgata importantes textos da dimensão espacial da cultura, publicados pela EdUERJ nos livros da referida coleção. Desse modo, contempla o leitor com um rico conjunto dedicado à pluralidade temática. Apresenta artigos não só sobre história, mas também sobre conceitos e proposições em geografia cultural que devem ser parte fundamental em qualquer antologia, remetendo o leitor à trajetória do campo da dimensão espacial da cultura.', '["cultural geography","history of cultural geography"]', '10.7476/9788575114384', '9788575112526', 'https://books.scielo.org/id/dc9yf', NULL, NULL, 'https://books.scielo.org/id/dc9yf/cover/cover_thumbnail.jpeg', 344, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = CO