INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dcc7q', 'dcc7q', 'Etnicidade na América Latina: um debate sobre raça, saúde e direitos reprodutivos', NULL, '["Simone Monteiro","Lívio Sansone"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Estudos sobre as trs primeiras dcadas da era republicana estabelecem estreitos vnculos entre polticas de sade pblica e desenvolvimento do capitalismo no Brasil. Subordinadas aos interesses das classes dominantes, as aes dos sanitaristas -concernentes ao controle de determinadas epidemias --', '["ethnicity","race","health","reproductive rights","Latin America","public health policy","capitalism","epidemics"]', '10.7476/9788575416150', '9788575416150', 'https://books.scielo.org/id/dcc7q', 'https://books.scielo.org/id/dcc7q/pdf/monteiro-9788575416150.pdf', NULL, 'https://books.scielo.org/id/dcc7q/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dd8hj', 'dd8hj', 'La protección ciudadana de los derechos humanos', NULL, '["Torres Villarreal, María Lucía","Iregui Parra, Paola Marcela"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, '“Teniendo en cuenta que la garantía de los derechos humanos es interés de todos los ciudadanos, el objetivo de esta publicación es que las personas se apropien de los mecanismos de protección de los derechos creados por la Constitución de 1991 de una manera sencilla, fácil y precisa, que permita su uso por parte de toda persona ante una situación o decisión de una autoridad que afecte sus derechos. Así mismo, busca resaltar la importancia de las acciones constitucionales como un mecanismo con doble propósito: en primer lugar, como mecanismos de participación ciudadana, al ser herramientas que el Constituyente creó para controlar las actuaciones de la administración y en segundo lugar, como un instrumento eficaz para proteger los derechos humanos. Para lograr los fines que hemos planeado con esta publicación, realizamos un trabajo en conjunto con la Fundación Hanns Seidel, organización que respalda en Colombia los proyectos orientados a fortalecer los procesos democráticos y la participación ciudadana, permitiendo así la construcción de un mejor país, respetuoso de la Constitución que lo rige y formado bajo los parámetros de defensa de los derechos humanos. El principal objetivo común con la Fundación es educar en la democracia, es decir, fomentar entre los ciudadanos el estudio de temas relacionados con el modelo democrático, para que sean ellos mismos quienes asuman los deberes y las responsabilidades que trae consigo el ejercicio de los derechos. Esta publicación es la materialización de ese objetivo.”', '[]', '10.7476/9789585005327', '9789587383126', 'https://books.scielo.org/id/dd8hj', 'https://books.scielo.org/id/dd8hj/pdf/torres-9789585005327.pdf', 'https://books.scielo.org/id/dd8hj/epub/torres-9789585005327.epub', 'https://books.scielo.org/id/dd8hj/cover/cover_thumbnail.jpeg', 126, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ddcs5', 'ddcs5', 'As ciências da vida: de Canguilhem a Foucault', NULL, '["Vera Portocarrero"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O conjunto de textos reunidos nesse livro, cronologicamente separados, mas inseridos num único projeto epistemológico, explora o mesmo território: o das ciências da vida. Todos, de maneira bastante homogênea, lidam com a história e com uma tradição que se enraizou no Brasil e, particularmente, com muita força no Rio de Janeiro. O conteúdo desses escritos resulta de anos de pesquisa vivenciada em instituições biomédicas. São agradáveis, bem escritos e maduros: muito próximos da tradição que os inspira.', '["life sciences","history of science","epistemology","Georges Canguilhem","Michel Foucault","Rio de Janeiro","philosophy of biology"]', '10.7476/9788575414101', '9788575414101', 'https://books.scielo.org/id/ddcs5', 'https://books.scielo.org/id/ddcs5/pdf/portocarrero-9788575414101.pdf', NULL, 'https://books.scielo.org/id/ddcs5/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ddnvp', 'ddnvp', 'Science on the trail to the backlands', 'photographs of the scientific expeditions by the Oswaldo Cruz Institute to the hinterlands of Brazil from 1911 to 1913', '["Intituto Oswaldo Cruz. Casa de Oswaldo Cruz."]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, NULL, 'en', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Science on the Trail to the Backlands: photographs of the scientific expeditions by the Oswaldo Cruz Institute to the hinterlands of Brazil from 1911 to 1913, versão em inglês da premiada obra A Ciência a Caminho da Roça: imagens das expedições científicas do Instituto Oswaldo Cruz (IOC) ao interior do Brasil entre 1911 e 1913, o livro reúne registros fotográficos das expedições do Instituto Oswaldo Cruz ao interior do Brasil (1911–1913). A publicação retrata aspectos sanitários, sociais e culturais das regiões visitadas, contribuindo para a memória da saúde pública no país.', '[]', '10.7476/9786557082362', '9786557081990', 'https://books.scielo.org/id/ddnvp', 'https://books.scielo.org/id/ddnvp/pdf/peterson-9786557082362.pdf', 'https://books.scielo.org/id/ddnvp/epub/peterson-9786557082362.epub', 'https://books.scielo.org/id/ddnvp/cover/cover_thumbnail.jpeg', 174, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ddxwv', 'ddxwv', 'Avaliação nutricional', NULL, '["Lílian Ramos Sampaio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'ApresentaçãoO livro de apoio didático ora apresentado emerge como uma proposta de auxílio aos alunos na sistematização e apropriação do conhecimento sobre Avaliação Nutricional (disciplina da graduação em Nutrição -NUT 143).Trata-se de um componente curricular obrigatório de grande relevância para o processo de formação do nutricionista, uma vez que o conhecimento que dele se processa é utilizado nas diferentes áreas de atuação do profissional.Inserido no projeto pedagógico do curso de Nutrição, da Universidade Federal da Bahia, do 6º semestre do curso, o componente curricular NUT 143 -Avaliação Nutricional apresenta a seguinte ementa: Métodos e técnicas de avaliação direta e indireta do estado nutricional de indivíduos e populações.Processo de determinação do estado nutricional nos diferentes ciclos de vida.Planejamento, análise e acompanhamento de diagnóstico nutricional de indivíduos e grupos populacionais.A pretensão é que este material se converta em um importante instrumento pedagógico, capaz de apoiar o professor no processo de ensino e estimular o aluno na busca do conhecimento, de forma organizada e ampliada, considerando que o conhecimento aqui sistematizado está longe de atender a real necessidade do aluno, em termos de aprofundamento, para o futuro exercício da profissão.Assim, a complementaridade deve ser feita com o aluno agregando outros referenciais bibliográficos, indicados pelo professor e por ele descobertos no decorrer das aulas.Este material contempla os métodos e técnicas relacionados aos principais indicadores de avaliação nutricional de indivíduos e coletividades, ou seja: Semiologia, Marcadores bioquímicos, Antropometria, Inquérito Alimentar e Bioimpedância.', '["nutritional assessment","nutritional status","anthropometry","biochemical markers","dietary questionnaire","bioimpedance","semiology","nutritional diagnosis","nutrition education","nutritionist training"]', '10.7476/9788523218744', '9788523218744', 'https://books.scielo.org/id/ddxwv', 'https://books.scielo.org/id/ddxwv/pdf/sampaio-9788523218744.pdf', NULL, 'https://books.scielo.org/id/ddxwv/cover/cover_thumbnail.jpeg', NULL, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
