l), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dfh78', 'dfh78', 'Os (des)limites da leitura: olhares múltiplos sobre os modos de interpretação', 'olhares múltiplos sobre os modos de interpretação', '["Leal, Baktalaia de Lis Andrade","Fernandes, Maria Angélica Rocha","Feistauer, Cláudia Madalena"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esse livro apresenta a versatibilidade da pesquisa com ensaios e uma entrevista com Júlio Hemílio Braz sobre a leitura. De modo vasto, permite explorar o fenômeno da leitura e da intepretação. O conjunto de textos penetra em fragmentos antigos e promove ao leitor a oportunidade de repensar a sua própria ação de ler.', '["reading","interpretation","literary interpretation","essay writing","reading practices"]', '10.7476/9788585813598', '9788585813468', 'https://books.scielo.org/id/dfh78', 'https://books.scielo.org/id/dfh78/pdf/leal-9788585813598.pdf', 'https://books.scielo.org/id/dfh78/epub/leal-9788585813598.epub', 'https://books.scielo.org/id/dfh78/cover/cover_thumbnail.jpeg', 172, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dg2mj', 'dg2mj', 'Da compaixão à solidariedade: uma genealogia da assistência médica', NULL, '["Sandra Noemi Caponi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O compromisso com a pessoa que sofre pode ter as mais diversas motivaçôes.Pode resultar da solidariedade genuína, do respeito mútuo, do reconhecimento de que algo semelhante pode nos acontecer.Pode resultar, também, de um sentimento de ''compaixâo piedosa'' pelos sofredores através do qual acreditamos tornarmo-nos benfeitores virtuosos.Pode, por firfi, ocorrer, simplesmente, porque pensamos que socorrer aos infortunados contribui para o bem comum e para o bem-estar geral.O presente trabalho tem o objetivo de problematizar as motivações que fundamentaram duas modalidades diversas de intervençâo sobre a saúde das papulações no transcurso do século XIX.Trata-se de duas estratégias diferenciadas de assistência à sociedade que, no entanto, como tentaremos mostrar, não sâo inteiramente alheias uma à. outra, embora assim se apresentem.Na primeira parte analisaremos o papel desempenhado por uma ética da-compaixão na constituição e legittmação daquelas modalidades de assistência que, nas últimas décadas do século XVIIt, deram lugar à chamada ''época da bondade''.Esta problematização da ética da compaixão exigirá uma referência ao pensamento de Rousseau e a sua insistência em dar prioridade à piedade -que aproxima os doentes e os cuidadores na imediatez do sentimento compartilhado -sobre a frieza das mtervenções racionalmente fundamentadas.Empreender uma critica às intervenções assistenciais fundamentadas na piedade e na compaixão exigirá que recorramos às análises de Frederico Nietzsche e de Hannah Arendt.Ambos souberam assinalar os limites e os riscos políticos implicados nessas intervenções que se definem-como ''compassivas''.Porém, a segunda modalicfade de assistência antes mencionada será analisada na terceira parte deste trabalho, Tematizaremos esse utilitarismo difuso e generalizado que permeia e sustenta os diversos tipos de intervençôes assistenciais próprios das politicas filantrópicas do século XIX.Deter-nos-emos na análise do pensamento de Bentham por considerar que sua formulação do utilitarismo é a que melhor traduz essa perspectiva.Certamente o utilitarismo contemporâneo, e até o próprio Stuart Mill, introduziram mu danças que nos impedem de generalizar as observações aqui expostas.No entanto, no que diz respeito à perspectiva benthamiana, pode-se afirmar sua indissolúvel vinculaçâo com as políticas filantrópmas que delinearam o perfil da assistência à saúde da comunidade no século XIX.Neste caso, e tomando como ponto de partida as críticas de MacIntyre e Rawls, procuraremos assinalar as dificuldades envolvidas na fundamentação utilitarista das intervenções as sistenciais.No entanto, nosso objetivo é mostrar, a partir da análise de práticas e de estratégias pontuais de assistência, que vão da lei de pobres à medicalização da família, que nào existe uma ruptura absoluta, mas sim continuidade, solidariedade e complementaridade entre as políticas assistenciais fundadas em uma ética compassiva, e aquelas fundadas no utilitarismo clássico.Tal continuidade manifesta-se ainda que estas últimas se apresentem como a garantia de ruptura e de superação das insuficiências das primeiras, j É na segunda parte deste estudo que essa complementaridade se evidencia.Centrar-nos-emos, aqui, nos trabalhos de Michel Foucault.Fazendo uma leitura retrospectiva de seus escritos, acreditamos que é possível afirmar que, na emergência da clínica, do hospital medicalizado e na medicina social, convivem, sem maiores dificuldades, estratégias de poder pastoral (próximas à compaixão piedosa) com estratégias de organização dos espaços e de controle do tempo próprias da sociedade disciplinar e das intervençôes p0Dicas fundamentadas no utilitarismo.Em resumo: pretendemos empreender uma cartografia dessas práticas assistenciais que tomaram por objeto a saúde das populações, tentando assinalar continuidades e rupturas, olhando para os limites éticos e políticos dessas estratégias.Pois, justamente no momento em b que elas dizem auxiliar, parecem reforçar formas coercivas de controle, seja em nome da''utilidade e da felicidade do maior número, seja em nome de uma piedade compassiva pelos que sofrem.Se voltamos para os séculos XVIII e XIX, é porque acreditamos, junto com Foucault e com Rosen, que uma análise crítica do modelo histórico de funcionamento da medicina e da assistência pode nos auxiliar a pensar, de outro modo, na sua existência atual, assim como na procura de alternativas para projetar como podem ser modiflcadas.Trata-se, pois, de fazer um uso estratégico da história, de usar essas análises genealógicas com o olhar direcionado para o presente, com.o objetivo de contribuir para criticar e transformar a assistência médica que ainda hoje, e em muitos casos, parece não poder, prescindir da vigilância e do controle para efetivar-se.Neste sentido, gostaríamos de fazer nossas estas palavras de Roberto Machado (1978:12): Uma dupla relação se estabelece entre a história e a atualidade: por um lado, o desvelamento do passado, do modo específico de emergência das configurações atuais, é indispensável para uma percepção mais lúcida do presente.No momento em que se procuram novas formas de funcionamento da medicina que não veiculem uma dominação de classe, que não sejam uma intensificação dos dispositivos de poder criados pelo capitalismo como condição indispensável à sua perpetuação, a abordagem crítica da história é um instrumento importante para a realização das experiências que pretendem impregnar o futuro.Por outro lado, a ida ao passado, o projeto de pesquisar as origens da (...) medicina como discurso e como prática política, é, ele próprio esclarecido pelo presente, determinado pela exigência de aprofundar sua crítica e de fornecer elementos para a transformação das condições amais de seu modo de intervenção.Para compreender por que se fala aqui de necessidade de transformação dos modos atuais de intervenção, é preciso considerar essas estratégias de poder que no dia-a-dia percorrem o âmbito dos saberes médico-corretivos.Elas nos situam perante conflitos éticos urgentes que, longe de emergir sob circunstâncias excepcionais e limites, definem a maior parte de nosso cotidiano.Estas estratégias de ''biopoder'' interferem em nossa existência, na medida em que cuidam de nossa saúde, vigiam nossos movimentos, discutem nossa sexualidade, admi-l , nistram nossa força de trabalho e assistem nossas necessidades mais elementares, olhando para os aspectos mais ínfimos e as tramas mais íntimas de nossa vida.Se isto é possível, é porque em cada um desses espaços, as tecnologias médicas apontam para a dimensão do humano que mais nos aproxima de uma coisa manipulável: nosso corpo.Mas, para que este controle possa ser aceito, para que ele possa ser entendido'' e até exigido, é mister que se apresente sob a forma, dificilmente objetável, de uma compaixão piedosa para com as pessoas que estão, atual ou virtualmente, em posição de inferioridade: aqueles que precisam ser assistidos.Acreditamos que é fundamental problematizar o fato de que, quase invariavelmente, a assistência compulsiva encontra sua justificativa e se faz aceitável ou por referência a um sentimento de piedade pelos necessitados e pelos sofredores, ou pela afirmação de que esse controle obedece a demandas claras de utilidade, de urgência social ou de bem-estar geral.Quiçá seja Michel Foucault quem mais se deteve na problematização desses conflitos que parecem ser inerentes ao ''saber médico''.Para ele, hoje estamos assistindo a uma extensão abusiva do que pode ser pensado como ''medicalizável'', e isto deriva-se de nossa dificuldade para demarcar os limites desses conceitos ambíguos que são os de ''normalidade'', ''saúde'', ''patologia'' e ''doença''.Faz tempo que assistimos a uma expansão progressiva das consideradas patologias, às quais, portanto, acreditamos que é lícito assistir medicamente.Ao dizer ''medicamente'', referimo-nos não só à intervenção direta de médicos e de enfermeiras, mas também às intromissões não solicitadas, desse conjunto de exp', '["compassion","solidarity","medical assistance","history of medicine","19th century","benevolence","Jean-Jacques Rousseau","Friedrich Nietzsche","Hannah Arendt","Jeremy Bentham","utilitarianism","philanthropy"]', '10.7476/9788575415153', '9788575415153', 'https://books.scielo.org/id/dg2mj', 'https://books.scielo.org/id/dg2mj/pdf/caponi-9788575415153.pdf', NULL, 'https://books.scielo.org/id/dg2mj/cover/cover_thumbnail.jpeg', NULL, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dgjm7', 'dgjm7', 'A problematização em educação em saúde: percepções dos professores tutores e alunos', NULL, '["Marina Lemos Villardi","Eliana Goldfarb Cyrino","Neusi Aparecida Navas Berbel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'In memoriamAo mestre Paulo Freire, que tem nos mostrado tantos caminhos e desafios para uma educação universitária emancipatória.Aos estudantes e professores tutores da IUSC, que ao problematizarem a realidade vivenciada na atenção primária à saúde, abalam concepções cristalizadas de educação, homem, mundo e saúde, e assim, enquanto grupo, reconhecem os profissionais dos serviços, as pessoas sob cuidado, os moradores de cada território como sujeitos vivos, parceiros de mudança. AGRADECIMENTOS À Faculdade deMedicina de Botucatu (FMB), pela pesquisa e por todos os recursos concedidos nestes longos e intensos anos de história.Aos alunos dos segundos anos de Medicina e Enfermagem e aos professores da disciplina Interação Universidade Serviço e Comunidade (IUSC) de 2012, da FMB, preciosidades do trabalho que ajudaram a construir novos olhares sobre o ensino em Saúde, com sua participação comprometida na pesquisa.À Coordenadoria de Aperfeiçoamento de Pessoal de Nível Superior (Capes), pela bolsa concedida e pela oportunidade de me aperfeiçoar como pesquisadora.SUMÁRIO Prefácio 11 Apresentação 13 Introdução 17 1 Mudança de paradigma no ensino superior em Saúde e as metodologias problematizadoras 23 2 A metodologia da problematização no ensino em Saúde: suas etapas e possibilidades 45 3 A trajetória de implantação da disciplina Interação Universidade Serviço Comunidade e suas características 53 4 As percepções dos sujeitos sobre as práticas problematizadoras 63 Considerações finais 101 Referências bibliográficas 109 Sobre as autoras 117 PREFÁCIOAs importantes contribuições que surgem do exercício investigativo em pesquisa na área da Saúde devem também impactar as atividades formativas no processo de ensino e aprendizagem dos futuros profissionais, assim como dos professores e profissionais atuantes na interface entre a universidade e a realidade.Nessa direção, este livro traz importantes e inovadoras contribuições para a formação inicial e continuada dos profissionais da área da Saúde.A pesquisa desenvolvida, e que deu origem a esta obra, visou articular os desafios da docência universitária dos professores, na formação em graduação nos cursos de Medicina e Enfermagem, integralizando essas ações profissionais com os professores e profissionais da rede municipal de saúde, buscando a criação de construtos epistemológicos e pedagógicos de uma formação focada na educação em saúde, e não na doença.Para tanto, a busca por inovações pedagógicas dos profissionais, em seus respectivos espaços de formação, por meio de metodologias ativas e inserções contextuais, pode ser um caminho fundante para o redimensiona- mento de ações profissionais realmente emancipatórias e transformadoras.A possibilidade de construir experiências significativas através da interação com a comunidade, por meio de ações criteriosas e espelhadas por práticas de ensino contextuais nos diferentes espaços institucionais, envolvendo a universidade e o atendimento à comunidade, potencializa a real articulação da área da Educação com a área da Saúde.Os desafios apresentados na referida pesquisa são um forte indicativo de que urgem inúmeras mudanças nas propostas formativas dos cursos, por meio da busca da construção, implementação e avaliação dos Projetos Político-Pedagógicos (PPPs) dos cursos na área da Saúde, num verdadeiro movimento emancipatório de mudança paradigmática do foco e das formas de educação verdadeiramente formativa e qualitativa nesses cursos.Parabenizo as autoras pela coragem, competência e rigorosidade científica de fazer pesquisa na área da Saúde, mapeando e destrinchando os espaços institucionais formativos e, ao mesmo tempo, propondo caminhos e possibilidades.', '["health education","problematization","health professions education","tutor perceptions","student perceptions","health promotion","quality of life","interdisciplinarity"]', '10.7476/9788579836626', '9788579836626', 'https://books.scielo.org/id/dgjm7', 'https://books.scielo.org/id/dgjm7/pdf/villardi-9788579836626.pdf', NULL, 'https://books.scielo.org/id/dgjm7/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dgjvp', 'dgjvp', 'Narrativas, ciclos de protesta y repertorios de acción colectiva en Ecuador 1990-2022', NULL, '["José Antonio Villarreal Velásquez"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La importancia de los movimientos sociales para la innovación democrática, así como la formulación y canalización de demandas y propuestas ciudadanas es incontestable. Esto cobra aún mayor relevancia en países donde las instituciones de la democracia representativa tienen desafíos para cumplir sus roles plenamente. Tal es el caso de Ecuador, donde históricamente los movimientos sociales han sido un vehículo de poblaciones marginalizadas en su lucha para que se cumplan sus derechos democráticamente establecidos. Este libro es una contribución para entender mejor las dinámicas actuales, así como los desafíos que enfrentan los movimientos sociales en Ecuador a través de una visión integral de investigaciones relevantes, revisión de los últimos acontecimientos y un análisis plural desde varias vertientes del conocimiento de las ciencias sociales. A lo largo de este trabajo se analizan las múltiples causas de los conflictos, las características y orígenes de los ciclos de protestas.', '["social movements","protest cycles","collective action repertoires","Ecuador","democratic innovation","marginalized communities","citizen demands","causes of social conflict"]', '10.7476/9789942099457', '9789978108055', 'https://books.scielo.org/id/dgjvp', NULL, NULL, 'https://books.scielo.org/id/dgjvp/cover/cover_thumbnail.jpeg', 541, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
