publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dgt4g', 'dgt4g', 'O significado da comunidade humana autêntica na sociologia de Lucien Goldmann: um pensamento na contracorrente das ideias dominantes', 'um pensamento na contracorrente das ideias dominantes', '["Aline Cristina Ferreira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A pesquisa teve como principal objetivo compreender e explicar o conceito de comunidade humana autêntica no conjunto da obra de Lucien Goldmann, isto é, nos seus escritos de 1945/1948 a 1970. Há poucos trabalhos que tratam diretamente desta ideia, ao passo que ela é mencionada com frequência na produção intelectual do autor. Assim, partimos da seguinte problemática: quais são as implicações do conceito de comunidade humana autêntica na produção sociológica de Lucien Goldmann? Como isso se manifesta concretamente nas suas obras?', '["Lucien Goldmann","community","French sociology"]', '10.7476/9786559544431', '9786559544431', 'https://books.scielo.org/id/dgt4g', 'https://books.scielo.org/id/dgt4g/pdf/ferreira-9786559544431.pdf', NULL, 'https://books.scielo.org/id/dgt4g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dj9m9', 'dj9m9', 'Ensinar e aprender matemática: possibilidades para a prática educativa', NULL, '["Célia Finck Brandt","Méricles Thadeu Moretti"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na presente coletânea reunimos textos de pesquisadores do Brasil com resultados de pesquisas desenvolvidas no campo da educação matemática ou com reflexões sobre temáticas relacionadas aos processos de ensino, aprendizagem, avaliação ou formação de professores. Os diversos estudos e pesquisas desenvolvidos e apresentados, no campo da educação matemática, contribuem tanto para o desenvolvimento e avanço da ciência como para a solução de problemas. Em se tratando da formação matemática dos alunos esses problemas se referem às dificuldades relacionadas aos processos de ensino e aprendizagem, formação de professores, materiais didáticos, dentre outras. Em virtude disso os esforços se concentram nas formas de proceder para tornar concreta a formação matemática dos alunos, nos diferentes graus ou níveis de ensino. As diferentes contribuições, oriundas dos resultados das pesquisas, relatados nessa coletânea apresentam possibilidades para a prática pedagógica dos professores que ensinam matemática e, igualmente para organização de currículos de cursos de formação de professores de matemática ou da disciplina de matemática para a educação básica ou superior.', '["mathematics education","mathematics teaching and learning","teacher professional development","mathematics teacher education","mathematics assessment","teaching materials","teaching practice","curriculum development","basic education","higher education"]', '10.7476/9788577982158', '9788577982158', 'https://books.scielo.org/id/dj9m9', 'https://books.scielo.org/id/dj9m9/pdf/brandt-9788577982158.pdf', NULL, 'https://books.scielo.org/id/dj9m9/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-djcms', 'djcms', 'Fronteiras na História: atores sociais e historicidade na formação do Brasil Meridional (séculos XVIII – XX)', NULL, '["Ânderson Marcelo Schmitt","Murillo Dias Winter"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta resultados de anos de investigações de um sem-número de trabalhos nos mais diferentes formatos, do diálogo estreito com as mais diversas linhas de pesquisa em programas de pós-graduação no Brasil e no exterior e através de projetos financiados por governos estaduais, nacionais e instituições internacionais, os quais convergem seus esforços em um ponto central: demonstrar a profundidade e a riqueza analítica dos estudos sobre a formação da Fronteira Sul, do final do século XVIII até o século XX. Esta publicação, diante da atualidade, complexidade e necessidade de um esforço coletivo, propõe pensar a fronteira e os limites não como linha a ser meramente ultrapassada, mas como espaços que produzem sentido e que merecem reflexão atenta para produção de conhecimento cada vez mais plural, complexo e abrangente. Portanto, sua tarefa fundamental é alimentar, redobrar e aprofundar os estudos sobre as fronteiras. Os autores são renomados historiadores, com destaque no Brasil e no exterior. Eles apresentam um mesmo recorte espacial, distintas territorialidades, temporalidades dessemelhantes, com diferentes pessoas e paisagens, espaços que são compartilhados, disputados, medidos, visitados por estrangeiros, utilizados como ferramenta retórica, modificados em razão de interesses econômicos, ocupados por colonos, indígenas, quilombolas, militares. Trata-se de produtos de uma historicidade, na mesma medida em que são agentes transformadores da mesma dinâmica histórica multifacetada.', '["frontier research","social actors","historicity","territoriality","colonial Brazil","indigenous peoples","quilombola communities","colonial settlers","territorial expansion","18th-20th centuries"]', '10.7476/9786586545623', '9786586545623', 'https://books.scielo.org/id/djcms', 'https://books.scielo.org/id/djcms/pdf/schmitt-9786586545623.pdf', NULL, 'https://books.scielo.org/id/djcms/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-djnty', 'djnty', 'Raça, ciência e sociedade', NULL, '["Marcos Chor Maio","Ricardo Ventura Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Bela coletânea que reúne trabalhos de enfoques plurais e com os seguintes objetivos: abordar os temas da raça e das relações raciais a partir de uma perspectiva diacrônica, desde o século XIX até o presente, com o intuito de observar as mudanças e deslocamentos conceituais de forma abrangente; apresentar um conjunto de trabalhos elaborados a partir de reflexões em diversos campos do conhecimento (antropologia, sociologia, história, ciência política e literatura), revelando assim a pluralidade de enfoques através dos quais a tríade raça, ciência e sociedade tem sido abordada; fornecer subsídios para a compreensão do cenário racial brasileiro contemporâneo.', '["race","race relations","race and science","race and society","history of race concepts","racial identity","anthropology of race","sociology of race"]', '10.7476/9788575415177', '9788575415177', 'https://books.scielo.org/id/djnty', 'https://books.scielo.org/id/djnty/pdf/maio-9788575415177.pdf', NULL, 'https://books.scielo.org/id/djnty/cover/cover_thumbnail.jpeg', NULL, 115, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dk5kd', 'dk5kd', 'Política de indexação', NULL, '["Isidoro Gil Leiva","Mariângela Spotti Lopes Fujita"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é resultado da colaboração científica entre os pesquisadores Profa. Dra. Mariângela Spotti Lopes Fujita da Universidade Estadual Paulista “Júlio de Mesquista Filho”, Campus de Marília, e Prof. Dr. Isidoro Gil Leiva da Universidade de Murcia, Espanha, que trabalham com a temática política de indexação sob diferentes perspectivas. Por meio de desenvolvimento de projetos científicos, iniciados em 2007, essa parceria permitiu que o conhecimento sobre o referido tema ultrapassasse as fronteiras das bibliotecas universitárias e chegasse às bibliotecas públicas da América Latina em estudo inédito sobre a política de indexação neste segmento.', '["indexing policy","subject indexing","public libraries","library cataloging"]', '10.7476/9786559541300', '9786559541300', 'https://books.scielo.org/id/dk5kd', 'https://books.scielo.org/id/dk5kd/pdf/leiva-9786559541300.pdf', NULL, 'https://books.scielo.org/id/dk5kd/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dkf7g', 'dkf7g', 'Flora e fauna um dossiê ambiental', NULL, '["Wilson Uieda","Lucia Maria Paleari"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Resultado de dados apresentados por especialistas de diferentes áreas da Ciências Naturais em dois encontros denominados "Flora, Fauna e Ambiente", realizados em Botucatu - SP, esta obra destina-se ao público leigo, que deseja ampliar seus conhecimentos científicos e aprofundar suas reflexões a respeito das questões ambientais e da responsabilidade do ser humano como protagonistas das ameaças que rodeiam a todos, exigindo uma mudança de postura diante da Natureza.', '["flora","animals","environmental problems","human responsibility","biodiversity threats","human-nature relationship","popular science"]', '10.7476/9788539303076', '9788571395435', 'https://books.scielo.org/id/dkf7g', NULL, NULL, 'https://books.scielo.org/id/dkf7g/cover/cover_thumbnail.jpeg', 238, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dmg3t', 'dmg3t', 'Interfaces do turismo em contextos transatlânticos', NULL, '["Roque Pinto","Sérgio Murilo Santos de. ARAÚJO","Inês Paulo Cordeiro Brasão"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'O livro é uma coletânea de artigos que apresenta um quadro amplo e socialmente contextualizado da atividade turística na América Latina, Europa e África, incluindo aí as expectativas, tensões, preocupações e soluções locais. O livro se divide em três capítulos. O primeiro trata das relações do turismo com comunidades locais e seus desdobramentos. O segundo, aborda a gestão e a formação da imagem turística, um dos eixos mais importantes para o entendimento do turismo como um todo. O terceiro capítulo discute as políticas e estratégias no âmbito do turismo e suas interfaces sociais, refletindo sobre o seu entorno econômico e ecológico e cultural.', '["tourism","local communities","tourism management","destination image","tourism policy","tourism development strategy","Latin America","Europe","Africa"]', '10.7476/9788574556314', '9788574556178', 'https://books.scielo.org/id/dmg3t', 'https://books.scielo.org/id/dmg3t/pdf/pinto-9788574556314.pdf', NULL, 'https://books.scielo.org/id/dmg3t/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dmp3g', 'dmp3g', 'Framing, a teoria do enquadramento: conceitos e aplicações', NULL, '["Nisia Alejandra Rizzo de Azevedo"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro se busca fazer o caminho histórico da teoria do enquadramento (framing) e suas aplicações nos estudos de comunicação e jornalismo, com uma perspectiva construtivista. A partir de autores como Goffman, se analisa como se formam os estereótipos na mídia e na sociedade. Livro importante para pesquisadores, comunicadores e estudantes.', '["framing theory","media framing","stereotypes","Erving Goffman","constructivism","journalism","communication studies"]', '10.7476/9788585813321', '9786588211700', 'https://books.scielo.org/id/dmp3g', 'https://books.scielo.org/id/dmp3g/pdf/azevedo-9788585813321.pdf', 'https://books.scielo.org/id/dmp3g/epub/azevedo-9788585813321.epub', 'https://books.scielo.org/id/dmp3g/cover/cover_thumbnail.jpeg', 117, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dmpyw', 'dmpyw', 'A rebeldia tornou-se de direita? Como o antiprogressismo e a anticorreção política estão construindo um novo sentido comum (e por que a esquerda deveria levá-los a sério)', NULL, '["Pablo Stefanoni"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Talvez seja o momento de prestar mais atenção nas direitas, de analisar algumas de suas transformações e de indagar sobre o ‘discreto charme’ que, em suas diferentes declinações, podem exercer nas novas gerações. Há, em geral, certa pretensão de superioridade moral do progressismo que o coloca em desvantagem no momento de discutir com as direitas emergentes; por uma simples razão: porque a esquerda deixou de ler a direita, enquanto a direita, ao menos a ‘alternativa’, lê e discute com a esquerda. Muitos, nas direitas alternativas, insistem em que a rebeldia juvenil está de seu lado. Podemos responder com um meio sorriso desdenhoso, reafirmar-nos em nossa convicção de que a rebeldia sempre será nossa, mencionar diferentes rebeliões progressistas ou – e esse é o objetivo deste livro – aceitar a provocação e ir ver em que consiste essa rebeldia, que é que querem e por que tem gente que os segue. (Da Introdução)', '["youth rebellion","right-wing populism","political correctness","progressive movement","generational politics"]', '10.7476/9788526816534', '9788526815513', 'https://books.scielo.org/id/dmpyw', NULL, NULL, 'https://books.scielo.org/id/dmpyw/cover/cover_thumbnail.jpeg', 173, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dmw4n', 'dmw4n', 'Gilberto Freyre: um vitoriano dos trópicos', NULL, '["Maria Lúcia Pallares‐Burke"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mais que uma biografia ou uma nova interpretação da obra de Gilberto Freyre, Maria Lúcia Pallares-Burke nos oferece uma narrativa que acompanha os elementos formadores do pensamento freyriano. Esta ampla pesquisa revela a trajetória do autor de Casa grande & senzala, o mundo cultural no qual ele estava inserido e as influências anglo-americanas e nacionais que o levaram a abandonar a falácia do racismo científico e a entender a miscigenação sob uma nova perspectiva. Gilberto Freyre: um vitoriano dos trópicos nos apresenta as idéias que, absorvidas e transformadas, permitiram a Freyre gerar a contribuição original e definitiva que mudou a maneira como o Brasil se percebia.', '["Gilberto Freyre","Casa Grande e Senzala","scientific racism","racial mixing","mestiçagem","Brazilian national identity","Brazilian culture","tropicalism"]', '10.7476/9788539303083', '9788571396104', 'https://books.scielo.org/id/dmw4n', NULL, NULL, 'https://books.scielo.org/id/dmw4n/cover/cover_thumbnail.jpeg', 484, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dmxrg', 'dmxrg', 'Traços épico-brechtianos na dramaturgia portuguesa: o render dos heróis de Cardoso Pires e felizmente há luar!, de Sttau Monteiro', NULL, '["Márcia Regina Rodrigues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em Portugal, durante o Estado Novo, apesar de a comissão de censura proibir a obra do dramaturgo alemão Bertolt Brecht (1889-1956), os dramaturgos, atores e diretores conseguiram, de alguma forma, adquirir conhecimento sobre os pressupostos do teatro épico brechtiano e praticá-los nas suas criações dramatúrgicas e encenações. Assim, algumas das peças produzidas pela dramaturgia portuguesa na segunda metade do século XX, além de explorarem freqüentemente temas históricos – a fim de tratar do passado com vistas a analisar o momento presente –, anunciavam a estética do teatro épico de Brecht como uma inovação das formas dramáticas praticadas até então. Frutos da perspectiva brechtiana de teatro épico, O render dos heróis (1960), de José Cardoso Pires (1925-1998) e Felizmente há luar! (1961), de Luís de Sttau Monteiro (1926-1993) constituem o corpus desta Dissertação de Mestrado. Essas peças apresentam no seu enredo fatos remanescentes ou antecedentes da Revolução Liberal de 1820, com o objetivo de – por meio da alegoria – levar o leitor / espectador a uma análise crítica da situação político-social de Portugal sob o regime ditatorial de António de Oliveira Salazar. Analisamos as formas de apropriação do efeito de distanciamento – elemento caracterizador do teatro épico brechtiano – nessas peças, bem como a relação delas com o período político marcado pela censura salazarista. Para isso, a nossa base teórica é constituída principalmente pelas teorias acerca do teatro épico de Brecht, considerando-as no contexto do teatro português da década de 1960.', '["Bertolt Brecht","epic theatre","Portuguese drama","José Cardoso Pires","Estado Novo","distancing effect","allegory","Liberal Revolution of 1820","political theatre"]', '10.7476/9788579831140', '9788579831140', 'https://books.scielo.org/id/dmxrg', 'https://books.scielo.org/id/dmxrg/pdf/rodrigues-9788579831140.pdf', NULL, 'https://books.scielo.org/id/dmxrg/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dp3cj', 'dp3cj', 'Cidades Novas', NULL, '["Ricardo Trevisan"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Uma viagem ao universo das cidades novas, esse é o convite que essa obra vem oferecer aos leitores a fim de transitar, a partir da visão particular do autor, pelo contexto, pelos conceitos e pelos aspectos inerentes a esse tipo urbanístico, ainda pouco explorado pela literatura especializada brasileira. Uma viagem feita por exemplares de cidades intencionalmente criadas, nacionais e internacionais, da Antiguidade ao século XXI, revelando seus empreendedores, suas funções dominantes, seus locais estratégicos, seus profissionais e seus projetos. Elementos agenciados no tempo, planejados e projetados, tendo por resultado uma diversidade de modelos cuja essência é a mesma: ser uma cidade nova. Uma viagem sem ordem cronológica ou delimitações geográficas, na qual as cidades novas são expostas a fim de proporcionar ao leitor uma compreensão mais fácil e ágil do tema abordado. Igualmente, as referências bibliográficas obtidas em acervos no Brasil, na França e na Itália, permeados por levantamentos realizados em sítios eletrônicos especializados, embasam e dão suporte aos conceitos construídos. Uma viagem aberta, segundo um olhar e uma definição particular, prefaciada por palavras de Philippe Panerai e Sylvia Ficher, enfim, um porto seguro pessoal que compartilho com pesquisadores e estudiosos do urbanismo, do planejamento urbano, da história das cidades e demais curiosos pela temática.', '["new towns","planned cities","urban planning history","urban development","urban models","urban history","urbanism"]', '10.7476/9786558461586', '9786558461586', 'https://books.scielo.org/id/dp3cj', 'https://books.scielo.org/id/dp3cj/pdf/trevisan-9786558461586.pdf', NULL, 'https://books.scielo.org/id/dp3cj/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dpg28', 'dpg28', 'Professores formados na FFP/UERJ e inclusão: entre políticas, práticas e poéticas', NULL, '["Anelice Astrid Ribetto"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Professores formados na FFP/UERJ e inclusão : entre políticas, práticas e poéticas / organização Anelice Ribetto.', '["teacher professional development","inclusive education","special education","teacher education curriculum","education policy","teaching practice","poetry in education","Universidade Federal do Rio de Janeiro"]', '10.7476/9788575115022', '9788575115022', 'https://books.scielo.org/id/dpg28', 'https://books.scielo.org/id/dpg28/pdf/ribetto-9788575115022.pdf', NULL, 'https://books.scielo.org/id/dpg28/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dpzgy', 'dpzgy', 'Pandemiavisión: reflexiones visuales del confinamiento', 'reflexiones visuales del confinamiento', '["Omar Alonso García-Martínez"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'El fracaso es una posibilidad que se tornó sustancial en el proceso individual del confinamiento, producto de la pandemia. La palabra fracasar significa falla y su raíz se deriva del latín frangere que apunta al hecho de romper o estrellarse. De esa forma, la pandemia del coronavirus SARS-CoV-2 se nos presentó como una falla biológica (natural o creada) que atacaba principalmente el sistema respiratorio de los humanos.', '["COVID-19 pandemic","lockdown","visual reflection","failure","SARS-CoV-2","respiratory system"]', '10.7476/9786287725133', '9786289526233', 'https://books.scielo.org/id/dpzgy', 'https://books.scielo.org/id/dpzgy/pdf/garciamartinez-9786287725133.pdf', NULL, 'https://books.scielo.org/id/dpzgy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dqf9k', 'dqf9k', 'O ensino profissional na irradiação do industrialismo', NULL, '["Luiz Antônio Cunha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra aborda a origem e o desenvolvimento até a atualidade dos segmentos da educação brasileira com relação ao "Sistema S" (Senai, Senac, SESI e SESC) e à rede federal de escolas técnicas industriais. Apresenta os conflitos que existiram quanto aos defensores dos modos distintos de funcionamento e organização da qualificação profissional, e as (des)articulações entre os cursos de aprendizagem do SENAI, os cursos técnicos na rede federal, o ensino médio e o ensino superior. Juntamente com os títulos O ENSINO DE OFÍCIOS ARTESANAIS E MANUFATUREIROS NO BRASIL ESCRAVOCRATA e O ENSINO DE OFÍCIOS NOS PRIMÓRDIOS DA INDUSTRIALIZAÇÃO, integra a trilogia do mesmo autor, Luiz Antônio Cunha, professor titular de Educação Brasileira da UFRJ, que trata de minucioso levantamento histórico da educação profissional no Brasil desde o período escravocrata até o ensino profissional na virada do século. (Co-edição: Flacso)', '["professional education","industrialism","Sistema S","SENAI","SENAC","SESI","SESC","vocational qualifications","history of education in Brazil","secondary education","higher education","industrialization"]', '10.7476/9788539303021', '9788571396333', 'https://books.scielo.org/id/dqf9k', NULL, NULL, 'https://books.scielo.org/id/dqf9k/cover/cover_thumbnail.jpeg', 270, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dqhw2', 'dqhw2', 'Provetas e clones: uma antropologia das novas tecnologias reprodutivas', NULL, '["Naara Luna"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'ApresentaçãoProponho, neste livro, uma análise antropológica das novas tecnologias reprodutivas e da clonagem humana.Novas tecnologias reprodutivas ou reprodução assistida são procedimentos que substituem a relação sexual na procriação.Trata-se da inseminação artificial, procedimento que consiste na introdução de sêmen pelo colo do útero, e da fertilização in vitro, conhecida popularmente como ''bebê de proveta'', em que óvulo e espermatozóides são unidos fora do corpo para formar embriões, depois transferidos para o útero.Abordo também a clonagem mediada tecnologicamente, processo que geraria seres idênticos a seu original.Analiso esses recursos biomédicos que dispensam o coito para gerar filhos com base em dois tópicos fundamentais na antropologia: as relações de parentesco e a noção de pessoa.Recursos usados para contornar a ausência involuntária de filhos, seja de caráter médico em situações identificadas como infertilidade, seja de caráter social, entre aqueles cujas práticas sexuais não são fecundas (pessoas sem companheiro, ou duplas homossexuais), as tecnologias reprodutivas incidem nas representações ocidentais de parentesco por permitirem a reprodução sem o intercurso sexual, símbolo central da comunhão do casal na geração de descendentes.Por meio desses procedimentos também é possível ter acesso à fertilidade alheia, com o recurso a sêmen, óvulos e embriões provenientes de doadores, bem como à cessão do útero de mulheres que portam a gravidez com a finalidade de entregar o bebê a quem o encomendou.Essa circulação de material germinativo embaralha noções de parentesco natural.A manipulação de gametas fora do corpo com geração de embriões humanos em laboratório suscita a seguinte questão: qual o estatuto desses entes?Trata-se de pessoas ou de material biológico disponível?Outra figura de pessoa emergente, o clone, desafia as representações ocidentais de pessoa devido a sua replicação, um ser destituído de singularidade.O livro teve origem em minha tese de doutorado, Provetas e Clones: teorias da concepção, pessoa e parentesco nas novas tecnologias reprodutivas, apresentada ao Programa de Pós-Graduação em Antropologia (PPGAS), do Museu Nacional, UFRJ, em 2004.Resulta de um longo processo de reflexão e pesquisa iniciado no mestrado, em curso sobre organização social e parentesco ministrado pelo professor Eduardo Viveiros de Castro.Persegui o objeto desde o mestrado sob orientação do professor Luiz Fernando Dias Duarte, quando escrevi a dissertação Bebê de Proveta, Barriga de Aluguel, Embriões de Laboratório: as representações sociais das novas tecnologias reprodutivas, com levantamento das representações das novas tecnologias 12 reprodutivas em material de imprensa escrita e telejornalismo, além de artigos jurídicos.A continuidade da pesquisa foi este estudo etnográfico com as pessoas envolvidas nas tecnologias de procriação: usuárias e profissionais de serviços de reprodução assistida.O campo de pesquisa sobre reprodução assistida, assunto do primeiro capítulo, apresenta peculiaridades que incitam a reflexão.A entrada no campo implica dificuldades: primeiramente se estranha que uma pesquisadora de fora da área da saúde se debruce sobre o tema da reprodução assistida; além disso, enfrenta-se a ética do segredo por parte dos envolvidos no tratamento.Centros de atendimento, usuários e profissionais envolvidos na reprodução assistida e em tratamentos convencionais, eventos na área da reprodução assistida, a mídia e diferentes saberes estão sob análise no recorte do objeto.No capítulo seguinte, analiso a família, um tema central na abordagem das tecnologias de procriação: meios para se obter filhos.A ausência involuntária de filhos é vivida como um drama.Qual a origem histórica da centralidade dos filhos na família moderna?A infertilidade é condição social estigmatizante.Como se define clinicamente a infertilidade?No terceiro capítulo, debato os modos como a reprodução vira objeto de intervenção médica.Que soluções a biomedicina apresenta para a ausência involuntária de filhos?O desenvolvimento das técnicas tem uma história.A ciência todo-poderosa promete eficácia.Como as pacientes relacionam eficácia e risco?O relacionamento entre médico e paciente constrói-se sobre diferenças.Os profissionais opinam: quem deve ter acesso às técnicas?O discurso biomédico produz representações e conforma o corpo, as teorias da concepção e noções de hereditariedade -temas do quarto capítulo.Como se produz o corpo culturalmente?O discurso biomédico constrói o corpo feminino no contexto das novas tecnologias reprodutivas.As tecnologias reprodutivas conceptivas permitem a reprodução sem sexo.Coloco em perspectiva as teorias da concepção ocidentais, ao mostrar o debate antropológico sobre teorias de outras culturas.As noções ocidentais de hereditariedade, a eugenia e o processo de ''genetização'' do parentesco também formam o quadro em que se inserem as tecnologias de procriação.No último capítulo abordo parentesco e pessoa: os pontos nodais nas polêmicas envolvendo as novas tecnologias reprodutivas.Como se constitui esse parentesco?Sangue e criação são temas centrais.A reprodução sem sexo interfere nas representações de legitimidade da prole?Diante de práticas como a cessão de útero e a doação de gametas, qual a importância do laço constituído pela gestação e dos vínculos genéticos?Representações de gênero estão implicadas na simbólica de parentesco, bem como na relação de médico e paciente.A figura do clone se isola ou se articula em redes de parentesco?Clones e embriões são novas figuras de pessoa que surgem no contexto das novas tecnologias reprodutivas.Que processos de personificação ocorrem?Que estatuto se atribuiu ao embrião humano e quais os seus condicionantes?13', '["assisted reproduction","in vitro fertilization","artificial insemination","human cloning","gamete donation","surrogacy","kinship","concept of person","personhood","infertility","same-sex couples","embryo status"]', '10.7476/9788575413555', '9788575413555', 'https://books.scielo.org/id/dqhw2', 'https://books.scielo.org/id/dqhw2/pdf/luna-9788575413555.pdf', NULL, 'https://books.scielo.org/id/dqhw2/cover/cover_thumbnail.jpeg', NULL, 55, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dqpry', 'dqpry', 'A atuação política da Agência de Informação dos Estados Unidos no Brasil (1953-1964)', NULL, '["Fernando Santomauro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'A Agência de Informação dos Estados Unidos (USIA), órgão criado pelo presidente norte-americano Dwight D. Eisenhower, foi a maior agência daquele país no exterior durante os anos 50 e 60, em número de funcionários e orçamento. No Brasil, a USIA chegou a ter mais de 60 postos locais espalhados por todo o país, fazendo constantes pesquisas qualitativas e quantitativas da opinião pública brasileira; produzindo materiais apócrifos para imprensa (jornais, rádios, TVs e cinema); organizando feiras e exposições; e promovendo intercâmbios educacionais, artísticos e culturais. Este livro se baseou, principalmente, nos arquivos do governo norte-americano e em entrevistas com ex-funcionários da USIA.', '["United States Information Agency","Brazil–United States relations","Cold War","US cultural diplomacy","public opinion research","propaganda","Dwight D. Eisenhower"]', '10.7476/9788579837050', '9788579837050', 'https://books.scielo.org/id/dqpry', 'https://books.scielo.org/id/dqpry/pdf/santomauro-9788579837050.pdf', NULL, 'https://books.scielo.org/id/dqpry/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-drh6n', 'drh6n', 'A Cinemateca Brasileira: das luzes aos anos de chumbo', NULL, '["Fausto Douglas Correa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro aborda o conceito de cinemateca desde o surgimento das primeiras coleções de filmes até os dias atuais, enfocando o final da década de 1950 e início da de 1960, quando um modelo específico de cinemateca, do qual o grande ideólogo foi Henri Langlois, é colocado em xeque no âmbito da Federação Internacional de Arquivos de Filmes (FIAF). O texto procura compreender ainda as especificidades da experiência brasileira no panorama político e cultural do país, analisando sobretudo o projeto político/pedagógico da instituição para o campo da educação e de políticas culturais no Brasil no período entre 1952 e 1973.', '["film archives","Henri Langlois","FIAF","film collections","film education","cultural policy"]', '10.7476/9788539304325', '9788539300105', 'https://books.scielo.org/id/drh6n', NULL, NULL, 'https://books.scielo.org/id/drh6n/cover/cover_thumbnail.jpeg', 296, 37, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ds', 'ds', 'Infância e afrodescendente: epistemologia crítica no ensino fundamental', NULL, '["Ana Kátia Alves dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Essa obra oferece uma importante contribuição para a construção de políticas de educação que atendem à pluralidade étnicoracial deste país. A partir da discussão sobre as concepções de infância, a autora chega a uma etnografia crítica da prática escolar no ensino fundamental, na qual, de forma didática e com base no referencial cultural afro-brasileiro,apresenta os princípios fundadores da infância afrodescendente.', '["critical epistemology","primary education","conceptions of childhood","school practice","education policy","critical ethnography"]', '10.7476/9788523209001', '9788523209001', 'https://books.scielo.org/id/ds', 'https://books.scielo.org/id/ds/pdf/santos-9788523209001.pdf', NULL, 'https://books.scielo.org/id/ds/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ds48k', 'ds48k', 'Nem soldados nem inocentes: juventude e tráfico de drogas no Rio de Janeiro', NULL, '["Otávio Cruz Neto","Marcelo Rasga Moreira","Luiz Fernando Mazzei Sucena"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'other', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Fundamentada em pesquisa sobre o aumento da inserção de adolescentes no universo do tráfico de drogas, esta obra oferece uma análise histórica sobre as razões que levam ao envolvimento dos jovens com o ''mercado de drogas'', especialmente no Rio de Janeiro. A proposta teve como diferencial o fato de ter sido elaborada com base no processo de avaliação do Sistema Aplicado de Proteção, cujo objetivo foi gerar condições socioeconômicas que impedissem a reincidência e favorecessem a reestruturação e o fortalecimento dos vínculos familiares de jovens que cumpriam medidas socioeducativas. A riqueza contida na experiência desses jovens é expressa nos vários depoimentos colhidos. O livro traça um panorama da situação, abordando todos os intrínsecos aspectos sociais que a envolvem.', '["adolescent drug use","drug market","Rio de Janeiro","socio-educational measures","recidivism prevention","family ties","youth testimonies"]', '10.7476/9788575415191', '9788575415191', 'https://books.scielo.org/id/ds48k', 'https://books.scielo.org/id/ds48k/pdf/cruz-9788575415191.pdf', NULL, 'https://books.scielo.org/id/ds48k/cover/cover_thumbnail.jpeg', NULL, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dsg7h', 'dsg7h', 'Viroses emergentes no Brasil', NULL, '["Luiz Jacintho da Silva","Rodrigo Nogueira Angerami"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A IMPORTÂNCIA DAS VIROSES EMERGENTES 1Das 57 milhões de mortes ocorridas anualmente em todo o mundo, cerca de 15 milhões, mais de 25%, se devem a doenças infecciosas, sem contar aquelas que são conseqüência de infecções adquiridas anos antes, como a doença cardíaca causada pela infecção pelo estreptococo do grupo A, a cirrose hepática e o hepatocarcinoma secundários à infecção pelos vírus das hepatites B e C, o câncer do colo uterino causado pela infecção pelo papilomavírus humano e as infecções hospitalares.Apesar de todo o progresso da medicina e da saúde pública, as doenças infecciosas ainda determinam um significativo impacto negativo na saúde humana e, infelizmente, são as crianças que pagam o maior tributo, com aproximadamente três milhões morrendo anualmente somente de malária e doenças diarréicas.Determinar exatamente quanto desses óbitos são devidos a infecções virais é quase um exercício de adivinhação.Muitas doenças virais são de difícil identificação e, como a maior parte dessas mortes se dá em regiões do mundo com sistemas de saúde precários ou mesmo ausentes, sobra apenas o recurso de estimativas grosseiras.Basta lembrar algumas doenças virais, como a Aids, a dengue, a diarréia por rotavírus e a hepatite B, para constatar que o impacto delas em saúde pública é considerável.Adiante comentaremos um pouco a dinâmica dessas doenças, a maioria das quais em franca expansão, seja geográfica, seja em número de casos.', '["emerging viral diseases","viral infection","infectious disease burden","global mortality","malaria","diarrheal disease","HIV/AIDS","dengue","rotavirus gastroenteritis","hepatitis B","human papillomavirus","cervical cancer"]', '10.7476/9788575413814', '9788575413814', 'https://books.scielo.org/id/dsg7h', 'https://books.scielo.org/id/dsg7h/pdf/silva-9788575413814.pdf', NULL, 'https://books.scielo.org/id/dsg7h/cover/cover_thumbnail.jpeg', NULL, 59, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dt3qx', 'dt3qx', 'Pensando a episteme comunicacional', NULL, '["Tiago Quiroga"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'constitui violação', '["epistemology of communication","communication theory"]', '10.7476/9788578792800', '9788578792800', 'https://books.scielo.org/id/dt3qx', 'https://books.scielo.org/id/dt3qx/pdf/quiroga-9788578792800.pdf', NULL, 'https://books.scielo.org/id/dt3qx/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dt9gj', 'dt9gj', 'Industrialização do ensino e política de educação a distância', NULL, '["Antonio Roberto Faustino da Costa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Industrialização do ensino e política de educação a distância coloca-se como um trabalho sério e rigoroso ao aceitar o desafio de afirmar que “o discurso da industrialização do ensino governa a prática discursiva que norteia a política nacional de educação a distância”. O autor recorre a três ideologias que deram origem a diferentes teorias, concepções, abordagens e modelos de educação a distância: a “teoria da interdependência e autonomia”, a “teoria da comunicação e interação” e a “teoria da industrialização do ensino”. A partir desta última, faz um exame da política nacional de EAD, para mostrar que a “abordagem parte da premissa de que, enquanto a educação face a face compreende formas pré-industriais, a educação a distância pressupõe essencialmente condições industriais de ensino”, as quais teriam “como base o princípio da racionalização” que afeta o espírito, a letra e a política do processo de ensino-aprendizagem.', '["industrialization of education","distance education","distance education policy","industrialization theory","rationalization","ideology in education","face-to-face teaching","teaching-learning process"]', '10.7476/9788578793500', '9788578793500', 'https://books.scielo.org/id/dt9gj', 'https://books.scielo.org/id/dt9gj/pdf/costa-9788578793500.pdf', NULL, 'https://books.scielo.org/id/dt9gj/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dty2b', 'dty2b', 'A luta desarmada dos subalternos', NULL, '["Osmar Moreira dos Santos"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma condição para enfrentar e desmontar dispositivos de controle disseminados pelos sistemas de dominação, isto é, o Estado e suas vinculações com o capital, é a crítica permanente a toda e qualquer forma de representação, bem como à criação de espaços nômades de gestão pedagógica dessa (auto)crítica. O esvaziamento de um signo de poder e saber reativos torna-se impotente se não articulado a uma interpelação da lei e suas dobras no espaço público ou clandestino. Oferecemos, neste livro, um encontro com a rebeldia selvagem e libertária, encarada, do ponto de vista do campo linguístico-literário, como ciência e ação direta.', '["subaltern","critique of representation","systems of domination","state and capital","pedagogical management","nomadic space","power and knowledge","law","rebellion"]', '10.7476/9788542302905', '9788542302905', 'https://books.scielo.org/id/dty2b', 'https://books.scielo.org/id/dty2b/pdf/santos-9788542302905.pdf', NULL, 'https://books.scielo.org/id/dty2b/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dv379', 'dv379', 'Além do território: a categoria Ró do povo A’uwẽ Xavante no centro da disputa territorial', 'a categoria Ró do povo A’uwẽ Xavante no centro da disputa territorial', '["Maíra Taquiguthi Ribeiro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, somos convidados a mergulhar nas concepções espaciais próprias do povo indígena A’uwẽ Xavante. Através da identificação de categorias-chave autóctones, a autora Maíra Ribeiro demonstra a conflitualidade e o choque entre estas e as concepções espaciais e territoriais da sociedade não indígena, hegemônica e com base capitalista. As análises e reflexões do livro ocorrem a partir do estudo das estratégias de resistência do povo A’uwẽ frente aos avanços do agronegócio no leste de Mato Grosso, como resultado da pesquisa de mestrado defendido em 2023 pela Unesp.', '["indigenous territoriality","territorial disputes","agronegócio expansion","indigenous land rights","Mato Grosso"]', '10.7476/9786559544486', '9786559544486', 'https://books.scielo.org/id/dv379', 'https://books.scielo.org/id/dv379/pdf/ribeiro-9786559544486.pdf', NULL, 'https://books.scielo.org/id/dv379/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dvqr7', 'dvqr7', 'Retórica e política em Rousseau', NULL, '["Ricardo Monteagudo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Se a história é a história das condições do poder, então a história é a história dos usos e abusos da retórica que sustenta o poder. A luta política talvez seja exclusivamente retórica e com isso a força seria apenas um complemento posterior, pois toda demonstração de força valeria apenas por seu efeito retórico de aumento, manutenção ou perda de poder”. Ao formular nesses termos o problema da ordem (e da desordem) social, Ricardo Monteagudo nos faz entender que o tema da linguagem é, de fato, um lugar privilegiado para discutirmos a simbiose entre retórica e política na obra de J.-J. Rousseau. Tendo como pano de fundo um quadro histórico da retórica, dos autores da Antiguidade até Perelman e Todorov, a tese deste livro pode ser assim enunciada: no âmbito dos escritos políticos do filósofo genebrino, em particular no Discurso sobre a origem da desigualdade e no Contrato social, as condições de possibilidade das relações civis são estabelecidas, tanto para o bem quanto para o mal, pelo uso retórico da linguagem. Longe de se limitar a uma mera exegese acadêmica de textos datados, este trabalho se apresenta a nós, leitores do século XXI, como prova cabal de que certas investigações de Rousseau acerca do discurso político permanecem atualíssimas. Monteagudo se inscreve dessa maneira numa linhagem bibliográfica que, no Brasil, remonta às análises memoráveis de Bento Prado Jr. e Luiz Roberto Salinas Fortes sobre o assunto.', '["Jean-Jacques Rousseau","rhetoric","political discourse","language and power","Discourse on the Origin of Inequality","The Social Contract","civil relations","history of rhetoric","Perelman","Tzvetan Todorov"]', '10.7476/9786557140499', '9786557140499', 'https://books.scielo.org/id/dvqr7', 'https://books.scielo.org/id/dvqr7/pdf/monteagudo-9786557140499.pdf', NULL, 'https://books.scielo.org/id/dvqr7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dvwhh', 'dvwhh', 'Independência do Brasil na Bahia', NULL, '["Luís Henrique Dias Tavares"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro examina os principais episódios de guerra pela independência do Brasil na província da Bahia, que se instalou em Salvador em fevereiro de 1822, estendendo-se até o dia 02 de julho de 1823, data em que o exército e a marinha de Portugal deixaram a Bahia. O título expõe que o desconhecimento a respeito da guerra pela independência é injusto e procura mostrar que a situação singular da Bahia, com a resistência e a luta armada contra o exército português, tornou impossível qualquer acerto conciliatório entre o Brasil e Portugal.', '["Brazilian independence","War of Independence","Bahia","Portuguese Army","Salvador, Bahia","armed resistance","Portuguese-Brazilian relations","military history"]', '10.7476/9788523209018', '9788523203627', 'https://books.scielo.org/id/dvwhh', NULL, NULL, 'https://books.scielo.org/id/dvwhh/cover/cover_thumbnail.jpeg', 242, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dw2p7', 'dw2p7', 'Manejo integrado de bacias hidrográficas para produção de água: exercícios aplicados ao Rio Pardo', NULL, '["Edson Luís Piroli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Na atualidade, os temas de produção de água, segurança hídrica e mudanças climáticas alcançam visibilidade crescente e são discutidos nos meios acadêmicos, científicos, de comunicação e em parlamentos de todo o mundo. No entanto, precisam ser compreendidos e apropriados pelos gestores locais e regionais, por técnicos e pela população e seus representantes, para que as ações locais sejam condizentes com as discussões e o conhecimento globais. Este livro mostra a aplicação de técnicas de diagnóstico, de análises de áreas de municípios e de manejo integrado de bacias hidrográficas. Propõe ainda um conjunto de ações que visam envolver as comunidades na tarefa crucial de aumentar os volumes de água dos rios, potencializar a segurança hídrica da população e auxiliar na mitigação das mudanças climáticas nos territórios de bacias hidrográficas. Quando todas as bacias hidrográficas do Brasil e do mundo forem manejadas integralmente, seus solos, suas águas, seus ecossistemas e suas populações humanas serão mais saudáveis e poderão gozar de adequada segurança hídrica, alimentar e climática.', '["integrated watershed management","water production","water security","climate change mitigation","Rio Pardo","watershed diagnosis","community participation"]', '10.7476/9786557144534', '9786557144534', 'https://books.scielo.org/id/dw2p7', 'https://books.scielo.org/id/dw2p7/pdf/piroli-9786557144534.pdf', NULL, 'https://books.scielo.org/id/dw2p7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dw6bk', 'dw6bk', 'A esfera da política', NULL, '["Maria Francisca Pinheiro Coelho"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Existe grande descrença com a política na atualidade, sobretudo a institucional, particularmente com as instâncias de representação do poder e do Estado. Esse fenômeno não é apenas brasileiro, o que não exclui a gravidade de seus problemas e características específicas. A crise da política configura-se como um sinal dos tempos. Contudo, a política não envolve apenas o âmbito institucional. Constitui uma visão de mundo comum compartilhado. Nesse sentido, todas as pessoas estão envolvidas com a política. Vista como uma esfera de valor, possibilita uma crítica pertinente da ação do Estado. Este livro aborda a esfera da política que extrapola a dimensão institucional. Reúne artigos escritos no período de 2006 a 2014 e divide-se em duas partes: a primeira, “Política e esfera pública”, é constituída por trabalhos baseados no pensamento político de Hannah Arendt, a maior parte deles apresentados em encontros acadêmicos arendtianos; a segunda, “Esfera política: reflexões sobre o Brasil e a América Latina”, trata de temas referentes ao problema das gerações, ideologias, autoritarismo e democracia, com foco no Brasil e na América Latina. A esfera da política abrange tanto o espaço da disputa pelo poder quanto a esfera pública geral, constituída de processos de formação da opinião pública. Compreende a política como uma ação que diz respeito ao mundo no qual se vive e do qual se faz parte.', '["political sphere","crisis of politics","Hannah Arendt","public sphere","public opinion","political thought","generations","ideology","authoritarianism","democracy","Brazil","Latin America"]', '10.7476/9788523013363', '9788523012038', 'https://books.scielo.org/id/dw6bk', NULL, NULL, 'https://books.scielo.org/id/dw6bk/cover/cover_thumbnail.jpeg', 246, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dx2q9', 'dx2q9', 'Economia e Cultura do Candomblé na Bahia: o comércio de objetos litúrgicos afro-brasileiros - 1850/1937', NULL, '["Flávio Gonçalves dos Santos"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esse livro mostra a importância do comércio de objetos litúrgicos no candomblé, cujas oferendas e rituais exigem uma diversidade de produtos que dependem de conhecimentos específicos para uma correta utilização. A economia é analisada sob um prisma amplo, imbricada com a cultura, a religiosidade, as relações sociais e de poder. Além disso, o autor faz um panorama do contexto histórico do comércio baiano desde o princípio do tráfico negreiro.', '["Candomblé","Afro-Brazilian religions","Bahia","Afro-Brazilian culture","religious economy","ritual offerings"]', '10.7476/9788574554464', '9788574554464', 'https://books.scielo.org/id/dx2q9', 'https://books.scielo.org/id/dx2q9/pdf/santos-9788574554464.pdf', NULL, 'https://books.scielo.org/id/dx2q9/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dx9pp', 'dx9pp', 'Jornalismo em branco & preto: ensaios de mídia, cultura e relações étnico-raciais', 'ensaios de mídia, cultura e relações étnico-raciais', '["Fernando Conceição"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne ensaios e artigos de crítica cultural a um dos mais influentes setores de atividade do mundo contemporâneo – o midiático. Alguns são inéditos; outros, já publicados de forma esparsa. É fruto da produção reflexiva e de pesquisas acadêmicas do autor ao longo de mais de três décadas de ativismo e intervenções sociais. Do período da luta pela redemocratização aos dias atuais. Permite ao leitor interessado verificar se houve, ou não, alterações no modus operandi da mídia, particularmente a impressa, no trato das questões raciais no Brasil. Trata-se de obra original – útil a quem lida e consome notícia –, que tem por objetivo tentar preencher uma lacuna na multidisciplinar área da Comunicação Social.', '["media criticism","race relations","ethnic-racial relations","print media","journalism","media activism","social intervention","cultural criticism"]', '10.7476/9786556309422', '9786556308036', 'https://books.scielo.org/id/dx9pp', 'https://books.scielo.org/id/dx9pp/pdf/conceicao-9786556309422.pdf', NULL, 'https://books.scielo.org/id/dx9pp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dxbds', 'dxbds', 'Decadência e superação da metafísica a partir de Heidegger', NULL, '["Flávio de Oliveira Silva"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O texto aborda, a partir do pensamento de Heidegger, três grandes temas da filosofia: a metafísica, a superação da metafísica e o lugar da filosofia na modernidade. A decadência é apresentada como questão fundamental da superação da metafísica. Leitura instigante para pesquisadores da filosofia e para curiosos sobre o nosso tempo.', '["Martin Heidegger","metaphysics","critique of metaphysics","decadence","modernity"]', '10.7476/9786588211991', '9786588211731', 'https://books.scielo.org/id/dxbds', 'https://books.scielo.org/id/dxbds/pdf/silva-9786588211991.pdf', 'https://books.scielo.org/id/dxbds/epub/silva-9786588211991.epub', 'https://books.scielo.org/id/dxbds/cover/cover_thumbnail.jpeg', 158, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dy6t7', 'dy6t7', 'Insurgência do feminino na obra de Inês Sabino', NULL, '["Silveira, Sinéia Maia Teles"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Insurgência do feminino na obra de Inês Sabino tematiza a vida e a obra da escritora baiana oitocentista Maria Inês Sabino Pinho Maia (1853-1911) e é resultado de um encontro das autoras em banca de defesa de mestrado e a feliz ideia de uma produção coletiva sobre Sabino, reunindo a dissertação de mestrado “‘Mulheres illustres do Brazil’, de Ignês Sabino, e sua ressonância em dicionários de autoria feminina nos séculos XX e XIX”, de Antonia Rosane Pereira Lima (2019), e as teses de doutoramento “Tramas femininas na imprensa do século XIX: tessituras de Inês Sabino e Délia”, de Maria Conceição Pinheiro Araújo (2008), e “Múltiplas faces femininas da tessitura literária de Inês Sabino”, de Sinéia Maia Teles Silveira (2014). O objetivo central do livro é apresentar as múltiplas produções da autora como ficcionista, jornalista, biógrafa, ensaísta e divulgadora dos valores do universo feminino na literatura brasileira e no jornalismo, além da sua incansável defesa dos direitos da mulher, em especial o direito à educação, ao voto e à participação feminina na vida política do país oitocentista.', '["women writers","women journalists","women''s rights","women''s education","women''s suffrage","women in politics","19th-century Brazilian literature","women''s biographies","women''s essays","collective authorship","Delias"]', '10.7476/9786588211595', '9786588211502', 'https://books.scielo.org/id/dy6t7', 'https://books.scielo.org/id/dy6t7/pdf/silveira-9786588211595.pdf', 'https://books.scielo.org/id/dy6t7/epub/silveira-9786588211595.epub', 'https://books.scielo.org/id/dy6t7/cover/cover_thumbnail.jpeg', 314, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dy7z7', 'dy7z7', 'Imagem: diálogos e interfaces interdisciplinares', NULL, '["Josie Ágatha Parrilha da Silva","Marcos César Danhoni Neves"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Imagem: diálogos e interfaces interdisciplinares nasceu da ideia desenvolvida por um grupo de docentes da Universidade Estadual de Ponta Grossa, ao estabelecer diálogos sobre o tema Imagem entre diferentes áreas de conhecimento. As imagens se fazem presentes de forma significativa no cotidiano humano e a pesquisa em torno delas possibilita novas formas de comunicações, interpretações e estéticas diferenciadas, alicerçadas em fundamentos, teorias e práticas que requeiram um domínio visual próprio e a busca ininterrupta dos sentidos definidores do próprio conhecimento. Assim, a Imagem foi o tema gerador escolhido para realizar reflexões interdisciplinares teórico-práticas que contribuirão para a construção de um conhecimento que supere as fronteiras disciplinares. Importante destacar que cada área de conhecimento possui distintas concepções e formas de abordar a Imagem. Tal pressuposto justifica as diferentes metodologias adotadas no decorrer dos capítulos do livro. Na estrutura da obra apresentaremos, de um lado, distintas metodologias provenientes de diferentes áreas, e de outro, novas possibilidades de refletir crítica, teórica e metodologicamente sobre estudos, pesquisas e produções ligados à Imagem. O livro apresenta discussões que remontam à década de 1980 e de discussões atuais, de pesquisadores nacionais e internacionais. O livro pode ser fonte de estudos interdisciplinares sobre Imagem, tanto em nível de graduação quanto de pós-graduação.', '["image studies","interdisciplinary dialogue","visual knowledge","visual theory","visual aesthetics","image interpretation","visual communication"]', '10.7476/9786587626079', '9786587626079', 'https://books.scielo.org/id/dy7z7', 'https://books.scielo.org/id/dy7z7/pdf/silva-9786587626079.pdf', NULL, 'https://books.scielo.org/id/dy7z7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dydn3', 'dydn3', 'Formação de pessoal de nível médio para a saúde: desafios e perspectivas', NULL, '["Antenor Amâncio Filho","M. Cecilia G. B. Moreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Reúne artigos que instigam e fundamentam o debate sobre a formação dos trabalhadores de nível médio para a saúde, campo em que estudos e publicações ainda são escassos. Abordando um leque abrangente de temas, a coletânea discute a questão sob variados pontos de vista: histórico, sociológico, pedagógico, técnico e metodológico. Resulta de análises de práticas vivenciadas na EPSJV/Fiocruz, o que em muito confere aos ensaios originalidade e exemplaridade. Sem a pretensão de apresentar respostas dogmáticas, o livro é uma contribuição para a superação de obstáculos e descompassos que vêm caracterizando a trajetória da profissionalização na área da saúde.', '["health professions education","health education"]', '10.7476/9788575412671', '9788575412671', 'https://books.scielo.org/id/dydn3', 'https://books.scielo.org/id/dydn3/pdf/amancio-9788575412671.pdf', NULL, 'https://books.scielo.org/id/dydn3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dymxw', 'dymxw', 'Qualidade de vida: educação, saúde, trabalho e sociedade', 'educação, saúde, trabalho e sociedade', '["Welton Cardoso","Berta Leni Costa Cardoso","Cláudio Pinto Nunes"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, os leitores poderão apreciar uma oportunidade que possa lhes conduzir a importantes refl exões. Ao mergulharem nesta leitura, eles serão apresentados ao tema da Qualidade de Vida (QV) por meio de análises multidisciplinares, de pesquisas e de outros documentos produzidos cientifi camente, sendo unifi cados por uma perspectiva que o amplia e o aprofunda. Neste texto, o tema se torna envolvente ao ser conectado em uma visão de mundo dialética, histórica e material. O objetivo principal dos autores foi o de ressignifi car a vida humana e as suas múltiplas formas de expressão.', '["quality of life","education","health","work","society","human life","dialectical perspective","multidisciplinary analysis"]', '10.7476/9788574556208', '9788574555911', 'https://books.scielo.org/id/dymxw', NULL, NULL, 'https://books.scielo.org/id/dymxw/cover/cover_thumbnail.jpeg', 104, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-dzxgz', 'dzxgz', 'Sem Vieira nem Pombal: índios na Amazônia no século XIX', NULL, '["Márcio Couto Henrique"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Este livro se debruça sobre os índios da Amazônia do século XIX, período em que, sem o jesuíta Antonio Vieira e sem o Marquês de Pombal, figuras às quais se associou a imagem de protetores dos índios, as sociedades indígenas traçaram outras estratégias de enfrentamento e diálogo com os projetos que pretendiam catequizá-los e civilizá-los."', '["Amazonian indigenous peoples","19th century","Jesuit missions","António Vieira","Marquês de Pombal","indigenous resistance","colonial Brazil"]', '10.7476/9788575115039', '9788575114636', 'https://books.scielo.org/id/dzxgz', NULL, NULL, 'https://books.scielo.org/id/dzxgz/cover/cover_thumbnail.jpeg', 260, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f298p', 'f298p', 'Federalismo e democracia: reflexões contemporâneas', NULL, '["Christiane Costa Assis"]', 'Editora UEMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea apresenta textos que analisam as diferentes interações entre democracia e federalismo no contexto brasileiro. São discutidos alguns dos erros estruturais nos quais o federalismo incorre, assim como algumas das fragilidades institucionais entre os poderes e órgãos do Estado, em todos os níveis da federação e nas relações entre os entes federativos, que caracterizam nossa democracia.', '["federalism","democracy","Brazilian federalism","institutional weakness","levels of government","separation of powers"]', '10.7476/9786586832419', '9786586832419', 'https://books.scielo.org/id/f298p', 'https://books.scielo.org/id/f298p/pdf/assis-9786586832419.pdf', NULL, 'https://books.scielo.org/id/f298p/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f2v3j', 'f2v3j', 'Formulário Médico: manuscrito atribuído aos Jesuítas e encontrado em uma arca da Igreja de São Francisco de Curitiba', NULL, '["Heloisa Meireles Gesteira","João Eurípedes Franklin Leal","Maria Cláudia Santiago"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Pertencente ao acervo da Fiocruz, o manuscrito Formulário Médico integra a seção de obras raras da Biblioteca de Manguinhos da Fiocruz. Por meio do selo Clássicos & Fontes da Coleção História & Saúde, a Editora Fiocruz leva aos leitores uma versão transcrita e analisada por diversos especialistas. Indispensável para todas as pessoas interessadas em conhecer e pesquisar as histórias e práticas de cura adotadas no Brasil colonial, o volume é dividido em cinco capítulos, além de uma transcrição paleográfica – com imagens digitalizadas do manuscrito – e um glossário. Profissionais de áreas e campos diversos como História, Arquivologia, Biblioteconomia, Engenharia Química, Paleografia e Ciências Biológicas trabalharam e produziram diversas análises, reflexões e informações sobre o documento. O manuscrito recebeu, em 2017, o título de “Memória do Mundo” pelo Programa Memória do Mundo da Unesco (MoW), que promove a preservação e acesso ao patrimônio documental – arquivístico e bibliográfico – da humanidade. “Para o conhecimento da história colonial, o Formulário Médico está destinado a se tornar um clássico, não apenas para historiadores da medicina, mas também para os estudiosos de outras modalidades, como história ambiental, da vida mterial, do cotidiano, da religião ou da cultura”, afirma a professora e pesquisadora da Casa de Oswaldo Cruz Lorelai Kury. Para a professora, o manuscrito “pode indicar pistas para transformar as práticas presentes e provocar novos olhares para antigos males”. Com mais de 30 títulos publicados, a coleção História & Saúde convida o leitor a participar de um fértil diálogo interdisciplinar, contribuindo para a compreensão do presente e do passado, em consonância com a historiografia contemporânea.', '["colonial medicine","Jesuit missionaries","medical manuscripts","paleography"]', '10.7476/9786557080696', '9788575416334', 'https://books.scielo.org/id/f2v3j', NULL, NULL, 'https://books.scielo.org/id/f2v3j/cover/cover_thumbnail.jpeg', 434, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f365g', 'f365g', 'Olavo Bilac: sátiras', NULL, '["Álvaro Simões Júnior"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Grande expoente do chamado Parnasianismo brasileiro, Olavo Bilac também teve notável atividade jornalística, na qual sobressaiu especialmente sua veia satírica. Em estilo mais leve que aquele adotado na parcela de sua produção que o celebrizou, produziu textos de caráter multifacetado e que ora são resgatados em edição cuidadosa empreendida por Alvaro Simões Junior. Neste título reúnem-se poemas satíricos que Bilac publicou, principalmente em periódicos, de 1887 a 1905. Os textos estão distribuídos de acordo com a forma adotada: poemas herói-cômicos, esquetes, sonetos, odes, crônicas, canções, fábula e epigramas. Em alguns casos, os versos estão "emoldurados" por trechos em prosa, pois Bilac às vezes os divulgava no bojo das crônicas que publicava a intervalos regulares por compromisso profissional. O livro traz uma seção para as crônicas versificadas, ou seja, para textos que, apesar das rimas e do ritmo regular, realizaram o comentário bem-humorado dos fatos cotidianos, como é próprio da crônica.', '["Olavo Bilac","satirical poetry","Brazilian journalism","newspaper columns","verse chronicle","sonnets","odes","epigrams","humorous verse"]', '10.7476/9788595463080', '9788595463080', 'https://books.scielo.org/id/f365g', 'https://books.scielo.org/id/f365g/pdf/simoes-9788595463080.pdf', NULL, 'https://books.scielo.org/id/f365g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f376s', 'f376s', 'Los derechos de los pueblos indígenas de Colombia: luchas, contenido y relaciones', NULL, '["Gloria Amparo Rodríguez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los pueblos indígenas gozan de los derechos humanos y libertades fundamentales consagrados en la Constitución Política, en el Convenio núm. 169 de 1989 de la OIT (ley 21 de 1991) y en otras normas reglamentarias. Sin embargo el Estado no han podido asimilar la diversidad cultural existente en nuestro país aunque colombiano tiene varias obligaciones orientadas a proteger los derechos de estos pueblos y a garantizar el respeto de su integridad que se constituyen actualmente en un reto para la gobernabilidad, la democracia y la ciudadanía. Es indispensable adelantar una acción coordinada y sistemática, con medidas que aseguren que dichos pueblos gocen de los derechos y oportunidades otorgadas al resto de la población y promover la efectividad de los derechos sociales, económicos y culturales de los que ellos son titulares. La escalada de los conflictos que actualmente se presenta en Colombia exige una respuesta urgente y eficaz, con políticas y controles que se traduzcan en el respeto de los derechos de los pueblos indígenas. Porque como lo propone la actora, no podemos desconocer que la solución de los problemas y la garantía de los derechos de los pueblos indígenas son un importante factor de la construcción de la paz en Colombia.', '["indigenous rights","Colombia","ILO Convention 169","cultural diversity","state obligations","economic, social and cultural rights","armed conflict","peacebuilding","constitutional rights","Indigenous self-determination"]', '10.7476/9789587386141', '9789587386134', 'https://books.scielo.org/id/f376s', NULL, NULL, 'https://books.scielo.org/id/f376s/cover/cover_thumbnail.jpeg', 158, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f3hjm', 'f3hjm', 'A experiência como fator determinante na representação espacial da pessoa com deficiência visual', NULL, '["Silvia Helena Ventorini"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O movimento de inclusão de crianças com deficiência visual na rede regular de ensino suscitou, nos últimos anos, uma série de discussões, especialmente pelo fato de haver poucos profissionais preparados para lidar com o assunto. O livro aborda essa questão de maneira atual e com um rico conteúdo, trazendo à tona assuntos que vão ao encontro das necessidades específicas de crianças com deficiência visual.', '["visual impairment","spatial representation","experiential learning","inclusive education","children with visual impairment","special education teachers","special educational needs"]', '10.7476/9788539304363', '9788571399266', 'https://books.scielo.org/id/f3hjm', NULL, NULL, 'https://books.scielo.org/id/f3hjm/cover/cover_thumbnail.jpeg', 112, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f48w3', 'f48w3', 'Medicinas indígenas e as políticas da tradição: entre discursos oficiais e vozes indígenas', NULL, '["Luciane Ouriques Ferreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Compreender o processo de emergência das medicinas tradicionais indígenas no campo das políticas públicas de saúde indígena é o objetivo deste livro, que analisa os discursos proferidos por uma diversidade de atores – indígenas e não indígenas, governamentais e não governamentais, nacionais e internacionais. Dessa forma, a obra revela uma dinâmica que vai do global e ao local, e transforma os contextos envolvidos, originando novas formações culturais. As políticas públicas que qualificam os seus objetos e público-alvo com a categoria ‘tradição’ conformam uma formação discursiva, definida pela autora como ‘políticas da tradição’. Um exemplo são as políticas voltadas à saúde indígena, que têm buscado reconhecer a eficácia das medicinas tradicionais indígenas e articulá-las com o sistema oficial de saúde. No entanto, “ao serem apropriados pelos povos indígenas, os discursos oficiais são postos a serviço dos seus interesses culturalmente situados – assim, estamos diante do fenômeno da indigenização”, diz a pesquisadora. E essa ‘indigenização’ se refere aos processos “levados a efeito pelos povos indígenas ao se apropriarem das políticas públicas a fim de manter a sua autonomia e reverter a seu favor o controle que o Estado passa a exercer sobre o mundo da vida de suas comunidades”. O livro busca contribuir para a consolidação do direito indígena à atenção diferenciada à sua saúde, considerando as relações historicamente construídas entre povos indígenas e Estado.', '["indigenous traditional medicine","Indigenous health policy","indigenization","discursive formations","indigenous autonomy","state-indigenous relations","right to health","cultural appropriation"]', '10.7476/9788575415108', '9788575415108', 'https://books.scielo.org/id/f48w3', 'https://books.scielo.org/id/f48w3/pdf/ferreira-9788575415108.pdf', NULL, 'https://books.scielo.org/id/f48w3/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f4gvg', 'f4gvg', 'A reinvenção do espaço: diálogos em torno da construção do significado de uma categoria', NULL, '["Douglas Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Discute o conceito de espaço sob diversas perspectivas, concluindo que a especificidade da geografia é justamente localizar fenômenos. Isso não impede, porém, um diálogo com outras ciências, como a física, a biologia, a economia e a sociologia. Leitura essencial para geógrafos, engloba desde o nascimento do espaço métrico à filosofia de Kant, passando por pensadores do calibre de Maquiavel, Giordano Bruno, Copérnico, Galileu Galilei, Descartes e Newton.', '["spatial concepts","spatial meaning","philosophy of space","Kantian philosophy","history of geography","interdisciplinary dialogue","metric spaces","Copernican revolution","Cartesian coordinates","classical mechanics","Giordano Bruno","Copernicus"]', '10.7476/9788539303397', '9788571393936', 'https://books.scielo.org/id/f4gvg', NULL, NULL, 'https://books.scielo.org/id/f4gvg/cover/cover_thumbnail.jpeg', 218, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f5jk5', 'f5jk5', 'Memória e formação de professores', NULL, '["Antônio Dias Nascimento","Tânia Maria Hetkowski"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Gira em torno de duas temáticas: memória e educação e formação de professores. A primeira diz respeito à identificação dos processos civilizatórios e o modo como se articulam com os processos educativos no que se refere à história da educação, pluralidade cultural, movimentos sociais, representação social e inclusão. A segunda aborda a importância dos estudos e pesquisas que contribuem para a formação de novos agentes destinados ao papel de formadores de um mundo mais humano e justo.', '["memory","teacher professional development","history of education","cultural pluralism","social movements","social representations","inclusion","civilizational process","educational process"]', '10.7476/9788523209186', '9788523209186', 'https://books.scielo.org/id/f5jk5', 'https://books.scielo.org/id/f5jk5/pdf/nascimento-9788523209186.pdf', NULL, 'https://books.scielo.org/id/f5jk5/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f5mpz', 'f5mpz', 'A literatura movente de Chimamanda Adichie: póscolonialidade, descolonização cultural e diáspora', NULL, '["Cláudio R. V. Braga"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“A literatura movente de Chimamanda Adichie é um livro que, ao trazer uma análise da prosa da escritora que dá nome ao título, explica por que ela tem sido lida e aclamada mundialmente: as temáticas, personagens e enredos de Adichie criam identificação profunda com leitoras e leitores de diversas culturas. Cláudio R. V. Braga perpassa as narrativas de Adichie, principalmente o romance Americanah, discutindo o papel da mulher na atualidade, baseando-se sobretudo na personagem Ifemelu. Quais são as expectativas, angústias e vivências dessa jovem mulher africana, negra e imigrante, oriunda de um país pós-colonial? Existe livre-arbítrio ou as circunstâncias determinam a vida? Qual a relação entre o presente e o passado pós-colonial de pessoas cujos países passaram pelo trauma da colonização europeia? O autor também se dedica à questão da mobilidade humana contemporânea, concebida literariamente por Adichie. Para isso faz uso da teoria da diáspora para abordar a prosa adichieana e questionar: como se dá a tensão entre experiências positivas e negativas vividas pelas pessoas que imigram? Como a mobilidade e sua representação literária influenciam no processo de descolonização cultural do indivíduo pós-colonial? Esses são alguns questionamentos encontrados neste livro, sobre os quais o autor discorre a partir de teorias selecionadas, mas sobretudo à luz da literatura de Adichie. A literatura e os estudos literários constituem formas de se pensar e compreender o que se passa ao nosso redor. Este livro é uma contribuição nesse sentido: o autor Cláudio R. V. Braga investiga a prosa de Chimamanda Adichie, escritora contemporânea globalmente conhecida, propondo uma perspectiva de mundo caracterizada pela pós-colonialidade, que é uma condição dos dias de hoje, perpassada por processos complexos de descolonização cultural e de mobilidade humana em escala global. No decorrer da investigação, percebe-se que a literatura de Adichie é “”movente””, segundo o autor, porque, além de representar um mundo de movimentos incessantes, ela também é agente dessa mobilidade, configurando-se em uma intervenção concreta com o poder de mobilizar e, portanto, mudar pensamentos e atitudes na direção da chamada descolonização cultural.”', '["Americanah","postcolonial literature","cultural decolonization","diaspora","human mobility","Ifemelu","African immigrant women","colonial trauma","free will and determinism","African literature in English","postcolonial identity","race and gender in literature"]', '10.7476/9786558460534', '9786558460534', 'https://books.scielo.org/id/f5mpz', 'https://books.scielo.org/id/f5mpz/pdf/braga-9786558460534.pdf', NULL, 'https://books.scielo.org/id/f5mpz/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f5tt4', 'f5tt4', 'Direitos em disputa: LGBTI+, poder e diferença no Brasil contemporâneo', NULL, '["Regina Facchini","Isadora Lins França"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro reúne um conjunto diverso de estudos sobre diversidade sexual e de gênero, com uma seleção abrangente e inédita de trabalhos que marcam o conhecimento que se produziu sobre gênero e sexualidade nos últimos 20 anos nas ciências humanas, incluindo saúde coletiva, ciências sociais, direito, educação, psicologia e serviços sociais. Diante dos enfrentamentos colocados pelo cenário atual, os textos convidam à releitura das primeiras duas décadas deste século e apresentam uma abordagem acessível de temas que atingiram grande refinamento conceitual e analítico.', '["LGBT rights","sexual diversity","gender diversity","power and difference","contemporary Brazil","collective health","law","education","psychology","social services"]', '10.7476/9786586253726', '9786586253580', 'https://books.scielo.org/id/f5tt4', NULL, NULL, 'https://books.scielo.org/id/f5tt4/cover/cover_thumbnail.jpeg', 535, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f5zjf', 'f5zjf', 'Os Direitos Humanos à Água e ao Saneamento', NULL, '["Léo Heller"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-10-04', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Levar ao público uma visão ampliada da água e do saneamento a partir da lente dos direitos humanos. É esse o intuito da obra, que busca, em suas mais de 600 páginas, explicar e decodificar o significado da água e do saneamento como direitos fundamentais, articulando diferentes campos do conhecimento, como o campo do direito, o campo da saúde coletiva e o campo das políticas públicas. O volume é organizado em 13 capítulos, que compõem quatro partes. A primeira é mais focada nos fundamentos dos conceitos, fazendo um apanhado histórico da emergência dos direitos humanos à ága e ao saneamento. A segunda parte aborda os macro determinantes, que acabam facilitando a violação desses direitos humanos. A terceira é sobre políticas públicas, diretamente relacionadas à realização desses direitos. Por fim, a quarta parte trata de alguns grupos populacionais mais fortemente vulnerabilizados quanto ao cumprimento desses direitos.', '["right to water","sanitation","human rights","fundamental rights","public health","public policy","health determinants","vulnerable populations"]', '10.7476/9786557081693', '9786557081327', 'https://books.scielo.org/id/f5zjf', NULL, NULL, 'https://books.scielo.org/id/f5zjf/cover/cover_thumbnail.jpeg', 620, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f6gwn', 'f6gwn', 'Costa Ribeiro: ensino, pesquisa e desenvolvimento da física no Brasil', NULL, '["Wanderley Vitorino da Silva Filho"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Apesar de visível sucesso midiático, com inúmeras reportagens sobre os avanços em estudos de materiais ligados à FMC, uma figura histórica da mais alta relevância permaneceu, praticamente, ignorada pela recente historiografia da física no Brasil - Joaquim da Costa Ribeiro. O autor mostra Costa Ribeiro como uma figura de liderança na pesquisa científica e com forte interesse em formar jovens pesquisadores, além de dedicar grande parte de sua existência ao ensino da disciplina - física', '["physics education","physics research","scientific leadership","training of young researchers","historiography of physics"]', '10.7476/9788578792763', '9788578792763', 'https://books.scielo.org/id/f6gwn', 'https://books.scielo.org/id/f6gwn/pdf/silva-9788578792763.pdf', NULL, 'https://books.scielo.org/id/f6gwn/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f6k2k', 'f6k2k', 'O futebol nas ciências humanas no Brasil', NULL, '["Sérgio Settani Giglio","Marcelo Weishaupt Proni"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne um time campeão, composto por pesquisadores de peso, oriundos de diversas áreas do conhecimento. É uma iniciativa inédita no Brasil, por sua abrangência. Retrata o futebol como objeto de estudo no campo da política, da história, da sociologia, da antropologia, da geografia, da economia, da pedagogia, da comunicação e da literatura. Os capítulos tratam de temas tradicionais, como identidade nacional, democracia e racismo. E também de assuntos frequentes em debates promovidos pela mídia esportiva, como a produção de ídolos, a violência entre torcidas e a Copa do Mundo. Em sintonia com questões atuais, o livro traz ainda estudos sobre o árbitro de vídeo e sobre gênero. Sem dúvida, na academia, o futebol é levado muito a sério.', '["football","national identity","democracy","racism","sports media","football hooliganism","FIFA World Cup","video assistant referee","sociology of sport","sports history","anthropology of sport"]', '10.7476/9786586253467', '9786586253184', 'https://books.scielo.org/id/f6k2k', NULL, NULL, 'https://books.scielo.org/id/f6k2k/cover/cover_thumbnail.jpeg', 799, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f6qxr', 'f6qxr', 'Histórias de vida e formação de professores: diálogos entre Brasil e Portugal', NULL, '["Inês Ferreira de Souza Bragança"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'fundamental, no Brasil, e às do primeiro ciclo do ensino básico, em Portugal, que, dia a dia, em meio a intensos conflitos e desafios, tecem, com vitalidade e poesia, a educação, a formação e a vida, reafirmando sentidos de antigas lutas que insistem em mobilizar nossos sonhos e projetos coletivos.', '["life history (social science method)","teacher professional development","Brazil-Portugal comparison","first cycle of basic education","teacher education in Brazil","group projects"]', '10.7476/9788575114698', '9788575114698', 'https://books.scielo.org/id/f6qxr', 'https://books.scielo.org/id/f6qxr/pdf/braganca-9788575114698.pdf', NULL, 'https://books.scielo.org/id/f6qxr/cover/cover_thumbnail.jpeg', NULL, 50, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f6rc9', 'f6rc9', 'Fiesta de picó champeta, espacio y cuerpo en Cartagena, Colombia', NULL, '["María Alejandra Giraldo"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, '2012-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'El trabajo aborda el tema de los picós y la champeta en Cartagena resaltando su centralidad en las fiestas y su trascendencia en la vida cotidiana de los habitantes de los barrios populares de la ciudad. Describe y analiza las distintas interacciones de esta música con la fiesta, el cuerpo y el baile, elementos consustanciales de la champeta, música que además se constituye en expresión identitaria de estos barrios. Así mismo la monografía contienen un amplio trabajo de campo que describe detalladamente los actores del universo picotero y los ciclos de producción musical de los diferentes tipos de picó que existen en Cartagena. En el primer capítulo se aborda una geografía musical del fenómeno. El segundo se adentra a describir la estructura de la fiesta picotera, para en el tercero dar paso al lugar que ocupa el cuerpo y el baile dentro de este contexto. El cuarto capítulo expone una serie de tensiones que se desprenden de esta estética, para finalmente concluir que la fiesta de picó es un medio de sustento no sólo económico sino simbólico de una cultura históricamente marginada. Desde la antropología se abordan nociones como, territorio, espacio, lugar, paisaje sonoro, música y musicar, música y poder, fiesta, raza, comunidad, hibridación, resistencia, cuerpo, baile, producción, escena, estética y sus relaciones y tensiones en el campo de lo simbólico. De esta manera se plantea cómo el sonido picotero crea una espacialidad sonora alterna y un contraste entre la Cartagena marginal y la turística, situación que es expresión contemporánea de las relaciones de exclusión y de poder creadas en la ciudad desde la Colonia.', '["champeta","PICO","street music","festivals","dance and the body","popular neighborhoods","identity","music production","soundscape","music and power","hybridity","resistance"]', '10.7476/9789585003941', '9789585003941', 'https://books.scielo.org/id/f6rc9', 'https://books.scielo.org/id/f6rc9/pdf/sanz-giraldo-9789585003941.pdf', NULL, 'https://books.scielo.org/id/f6rc9/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f7', 'f7', 'Modelo de atenção a saúde: promoção, vigilância e saúde da família', NULL, '["Carmen Fontes Teixeira","Jorge Pereira Solla"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Título discute a implementação de idéias que visam modificar a estrutura do sistema público de saúde, de forma a torná-lo mais humano e acessível para a população. Os autores reuniram os seus mais importantes textos sobre o tema, e publicam neste livro como mais um tentativa de mudança no modelo de atenção dado a saúde pública.', '["health care models","health promotion","health surveillance","family health","public health system","health care reform","health care access","humanization of health care"]', '10.7476/9788523209209', '9788523209209', 'https://books.scielo.org/id/f7', 'https://books.scielo.org/id/f7/pdf/teixeira-9788523209209.pdf', NULL, 'https://books.scielo.org/id/f7/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f7dr6', 'f7dr6', 'Estudos de literatura e imprensa', NULL, '["Alvaro Santos Simões Júnior"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Escritos em diferentes momentos e circunstâncias da carreira do pesquisador Alvaro Santos Simões Junior, este conjunto de dez ensaiostrata da produção, circulação e recepção de obras literárias no Brasil a partir do fim dos anos 1800.O primeiro texto reconstrói o ambiente em que, na virada século 19 para o século 20, da Monarquia para a República, do trabalho escravo para o livre, surgiram novas condições para o trabalho intelectual. O texto seguinte fala de uma modalidade bem-sucedida de atuação profissional dos escritores daquele período - as revistas de ano. Enquanto os romancistas seguiam os passos de Émile Zola e Eça de Queiroz, utilizando linguagem depurada, os “revisteiros” aderiam à metalinguagem e à paródia, e abusavam da fantasia, incorporando os variantes regionais e sociais.O terceiro e o quarto ensaios ainda olham para aquele momento histórico. Analisam, respectivamente, romances naturalistas brasileiros e notícias a respeito da morte de Zola, oferecendo, ambos, uma ideia de como era complexa relação dos intelectuais brasileiros com os amados e, eventualmente, odiados mestres europeus. O texto seguinte trata da literatura paradidática da Primeira República, à qual se dedicaram sistematicamente vários escritores daquele período.Os três ensaios subsequentes resultaram de investigação do autor sobre a repercussão do Simbolismo nos periódicos brasileiros e revelam a importância da imprensa periódica para a divulgação e circulação das obras literárias: o primeiro analisa um hebdomadário dirigido de 1893 a 1895 por Artur Azevedo; o segundo examina a atuação de Medeiros e Albuquerque como crítico literário do vespertino A Notícia de 1897 a 1905; o último aborda as intervenções do jovem Paulo Barreto, redator da Cidade do Rio, jornal de José do Patrocínio, contra o Simbolismo brasileiro na virada do século.O penúltimo estudo da coletânea reflete sobre a obra de Ana Cristina Cesar, autora mais representativa da “geração mimeógrafo”, que criou em pleno regime militar um circuito independente de produção e circulação de obras literárias. Encerra o volume um ensaio sobre a obra de Menalton Braff direcionada ao público jovem.', '["Brazilian literature","literary reception","press and literature","yearbooks","Émile Zola","Eça de Queirós","Brazilian Symbolism","Ana Cristina Cesar","First Brazilian Republic"]', '10.7476/9788568334478', '9788568334478', 'https://books.scielo.org/id/f7dr6', 'https://books.scielo.org/id/f7dr6/pdf/simoes-9788568334478.pdf', NULL, 'https://books.scielo.org/id/f7dr6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f8c7h', 'f8c7h', 'Quando o cinema vira urbanismo: o documentário como ferramenta de abordagem da cidade', NULL, '["Silvana Oliveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Quando o cinema vira urbanismo tem como foco a produção cinematográfica e documentária – brasileira e estrangeira – que aborda questões que se relacionam com a cidade e a vida urbana. A autora busca discutir a influência que esses recursos audiovisuais podem exercer sobre a prática de urbanismo, tendo como grande influência as noções de “orgânico” e “cristalino”, desenvolvidas, sobretudo, por Gilles Deleuze.', '["documentary film","urbanism","urban life","Gilles Deleuze","Brazilian documentary"]', '10.7476/9788523212247', '9788523207915', 'https://books.scielo.org/id/f8c7h', NULL, NULL, 'https://books.scielo.org/id/f8c7h/cover/cover_thumbnail.jpeg', 252, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f8pnb', 'f8pnb', 'Necessidades formativas de professores de redes municipais: contribuições para a formação de professores críticos-reflexivos', NULL, '["Cristiano Amaral Garboggini Di Giorgi","Mônica Fürkotter","Naiara Costa Gomes de Mendonça","Vanda Moreira Machado Lima","Yoshie Ussami Ferrari Leite"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os autores do livro apontam a importância de os professores serem propositores dos programas de formação contínua, a partir das necessidades que apontam. Essa perspectiva, que dá voz aos professores, tem se mostrado fértil no desenvolvimento de processos dessa natureza, pois considera fundamental o protagonismo dos sujeitos-professores na implementação de mudanças que se fazem necessárias nas práticas e nos currículos escolares. Procedendo ao levantamento de necessidades junto a uma amostra significativa de 533 professores, em dez municípios da região, com a colaboração da UNDIME - União Nacional dos Dirigentes Municipais de Educação, e desenvolvendo uma análise crítica e contextualizada dos resultados, os autores apresentam indicativos e propostas para a efetivação de políticas de formação contínua que superam eventuais desperdícios de recursos em ações pontuais, fragmentadas e externas às demandas reais das escolas e dos professores. Ao valorizar a formação crítica e reflexiva desses sujeitos, alinham-se às perspectivas que superam a racionalidade técnica instrumental das competências docentes, característica dos governos neoliberais que culpabilizam os professores diretamente pelo fracasso escolar, desvalorizam sua formação universitária de intelectual e pesquisador e não investem na melhoria da infraestrutura necessária ao trabalho docente de qualidade nem nas condições de carreira e salário dos professores.', '["teacher professional development","continuing teacher education","municipal school network","teacher needs assessment","teacher protagonism","education policy","neoliberalism in education","teacher competence","school improvement"]', '10.7476/9788579831065', '9788579831065', 'https://books.scielo.org/id/f8pnb', 'https://books.scielo.org/id/f8pnb/pdf/di-9788579831065.pdf', NULL, 'https://books.scielo.org/id/f8pnb/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
