INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f9jsv', 'f9jsv', 'Desaguar em cinema: documentário, memória e ação com o CachoeiraDoc', NULL, '["Amaranta César","Ana Rosa Marques","Fernanda Pimenta Vasconcelos","Costa, Leonardo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A pretexto de nos falar sobre cinema, Makota Valdina, professora militante e religiosa da Bahia, nos legou essa lição de vida em uma das sessões do CachoeiraDoc, o festival de documentários de Cachoeira cuja memória de ação e reflexão compõem esta obra. Desaguar em cinema, por meio de um ajuntamento de vozes diversas de pesquisadoras(es), cineastas e ativistas, em abordagens multidisciplinares, tenta dar vazão ao fértil movimento do documentário brasileiro contemporâneo que nutriu e foi nutrido pelo festival pioneiro no gênero Norte-Nordeste no Brasil. Trata-se de um festival – e de um livro – dedicado ao cinema impregnado pela vida.', '["documentary film festivals","Brazilian documentary film","contemporary documentary","memory","Cachoeira"]', '10.7476/9786556301921', '9786556301921', 'https://books.scielo.org/id/f9jsv', 'https://books.scielo.org/id/f9jsv/pdf/cesar-9786556301921.pdf', NULL, 'https://books.scielo.org/id/f9jsv/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-f9whn', 'f9whn', 'O Barroco, a arquitetura e a cidade nos séculos XVII e XVIII', NULL, '["Rodrigo Espinha Baeta"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro revela uma apreensão do “espírito” arrebatador que invadiu o mundo ocidental durante quase duzentos anos, contribuindo para as discussões sobre a arquitetura e o espaço urbano desse momento tão importante da História da Arte. O resultado final do estudo ambiciona alcançar um juízo próprio sobre o arcabouço conceitual exposto na poética barroca, uma ação crítica só possível através do reconhecimento e da apreciação pessoal de muitas das mais importantes manifestações barrocas na arquitetura e no espaço urbano do Seicento e do Settecento.', '["Baroque architecture","Baroque poetics","urban space","Baroque city","17th century","18th century","Western art history"]', '10.7476/9788523211639', '9788523207021', 'https://books.scielo.org/id/f9whn', NULL, NULL, 'https://books.scielo.org/id/f9whn/cover/cover_thumbnail.jpeg', 368, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fbhvh', 'fbhvh', 'Palhaços', NULL, '["Mário Fernando Bolognesi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Trata-se de um estudo sobre o circo e seus palhaços no Brasil atual. Resultou de uma pesquisa bibliográfica e empírica, que incluiu viagens por quase todo o país, registros fotográficos, observações diretas e entrevistas. Resultado de uma pesquisa bibliográfica e empírica, com viagens por grande parte do Brasil, este livro não só preenche uma lacuna acadêmica sobre a história do circo e a atividade dos palhaços brasileiros, como também - e principalmente - nos faz voltar um pouquinho à infância, pois estuda a arte do palhaço tal como ela é no circo nacional, tomando como base a dramaturgia, a interpretação e a encenação. O livro realiza ainda uma recuperação bibliográfica de parte da história do circo moderno, com uma investigação das origens dos palhaços, suas influências e aproximações com o teatro. Nesse sentido, inclui a reprodução escrita de toda uma tradição oral de esquetes e entradas, fornecendo um material inédito para pesquisadores e artistas.', '["circus","clowns","circus history","clowning","circus performance","childhood","oral tradition"]', '10.7476/9788539303342', '9788571394568', 'https://books.scielo.org/id/fbhvh', NULL, NULL, 'https://books.scielo.org/id/fbhvh/cover/cover_thumbnail.jpeg', 294, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fbnvy', 'fbnvy', 'Os sertões em movimento: sertanistas, indígenas e escravidão na Bahia colonial, 1651-1720', 'sertanistas, indígenas e escravidão na Bahia colonial, 1651-1720', '["Rafael dos Santos Barros"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro aborda a expansão territorial nos sertões da Bahia colonial entre os séculos XVII e XVIII, destacando as expedições organizadas pela Coroa portuguesa para integrar o interior ao projeto colonial e incorporar os povos indígenas. A obra revisita a história da antiga Capitania de Ilhéus, tradicionalmente vista como exclusivamente litorânea, e revela, com base em fontes da época, a existência e a relevância dos chamados "sertões da Costa do Mar", oferecendo uma nova leitura sobre a ocupação do território e a dinâmica colonial no Brasil.', '["sertão","indigenous peoples","slavery","territorial expansion","colonial Brazil","Bahia","17th century","18th century"]', '10.7476/9788574556505', '9788574555935', 'https://books.scielo.org/id/fbnvy', NULL, NULL, 'https://books.scielo.org/id/fbnvy/cover/cover_thumbnail.jpeg', 271, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fc27h', 'fc27h', 'Produção e difusão de ciência na cibercultura: narrativas em múltiplos olhares', NULL, '["Cristiane de Magalhães Porto","Kaio Eduardo de Jesus Oliveira","Flávia Goulart Mota Garcia Rosa"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra reúne uma diversidade de pesquisas sobre a divulgação da produção científica através da mídia e da internet, além de discorrer sobre os desafios envolvidos, como aspectos jurídicos, produção de infográficos e os estudos nas redes. O livro reúne ainda autores de variadas regiões brasileiras com formações diferentes, o que permite olhares distintos sobre a temática, abrangendo diversas áreas do conhecimento.', '["science communication","science dissemination","digital culture","internet","infographics","social networks","research output"]', '10.7476/9788574555249', '9788574554969', 'https://books.scielo.org/id/fc27h', 'https://books.scielo.org/id/fc27h/pdf/porto-9788574555249.pdf', 'https://books.scielo.org/id/fc27h/epub/porto-9788574555249.epub', 'https://books.scielo.org/id/fc27h/cover/cover_thumbnail.jpeg', 255, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fczgd', 'fczgd', 'Ciência, política e relações internacionais: ensaios sobre Paulo Carneiro', NULL, '["Marcos Chor Maio"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Trata-se de um livro que contém artigos de pesquisadores nacionais e estrangeiros que abordam: o positivismo no Brasil, as relações entre ciência e relações internacionais, o papel da Unesco no pós-2ª Guerra, a luta contra o racismo no pós-Holocausto e o debate sobre a Amazônia no contexto da Guerra Fria. Consta ainda da publicação uma mesa-redonda ocorrida na sede da Unesco em Paris com a presença, entre outros, do físico José Israel Vargas, do biólogo Luiz Hildebrando, do sociólogo Alain Touraine e do historiador Luiz Felipe de Alencastro. A obra apresenta também uma entrevista de Paulo Estevão de Berrêdo Carneiro (1901-1982) prestada ao Museu da Imagem e do Som, uma biobibliografia e, finalmente, uma seção iconográfica. Vale a pena conferir os temas e os problemas enfrentados por Paulo Carneiro, este ''cientista brasileiro'', ''cidadão do mundo'', para que se possa constatar que o tema da globalização e da atuação de atores coletivos e individuais em escala planetária não é uma novidade do final do século XX.', '["science and international relations","UNESCO","post-World War II","anti-racism","Holocaust","Cold War","globalization","science and politics","Brazilian researchers","biobibliography"]', '10.7476/9788575415092', '9788575415092', 'https://books.scielo.org/id/fczgd', 'https://books.scielo.org/id/fczgd/pdf/maio-9788575415092.pdf', NULL, 'https://books.scielo.org/id/fczgd/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fd6jt', 'fd6jt', 'Das loucuras da razão ao sexo dos anjos: biopolítica, hiperprevenção, produtividade científica', 'biopolítica, hiperprevenção, produtividade científica', '["Luís David Castiel","Javier Sanz‐Valero","Paulo Roberto Vasconcellos-Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Excessos: eles fazem parte do espírito de nossa época. E é justamente de excessos de que tratam os autores deste livro. Eles discutem, em especial, os excessos no campo da saúde pública e no território acadêmico, chamando atenção para “a dimensão ideológica que parece rodear muitas abordagens catastrofistas ditas racionais”. Em outras palavras: multiplicam-se estudos científicos que apontam para uma infinidade de riscos à saúde e à vida associados a comportamentos individuais – assim, a ciência respalda a ‘sociedade do risco’, onde as pessoas, de acordo com as mais recentes pesquisas, devem moldar suas condutas para afastar toda e qualquer ameaça. Porém, esta prevenção generalizada – ou hiperprevenção – é inatingível. “Algo que estimula altos teores de ansiedade que marcam a nossa época de modo inapelável”, destacam.', '["excess","public health","catastrophism","risk society","anxiety","ideology"]', '10.7476/9788575413128', '9788575412145', 'https://books.scielo.org/id/fd6jt', 'https://books.scielo.org/id/fd6jt/pdf/castiel-9788575413128.pdf', NULL, 'https://books.scielo.org/id/fd6jt/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fdc6z', 'fdc6z', 'Política externa como ação afirmativa: projeto e ação do governo Lula na África (2003-2006)', NULL, '["Irene Vida Gala"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Ano de 2005. Temia-se que a recém-(re) inaugurada política do Brasil para a África não resistiria a uma mudança de governo. Lula completou dois mandatos e seu nome ficou associado a uma inédita prioridade conferida ao continente africano. Tratava-se, em sua origem, de uma “volta à África”. Passados cerca de quinze anos, a África vive um “boom” diplomático com a abertura de 320 novas embaixadas em seu território entre 2010 e 2016. No plano bilateral, segundo o FMI, o Brasil perdeu, de 2006 a 2018, sete posições no comércio com a África Subsaariana, enquanto Turquia e Indonésia ganharam, respectivamente, 7 e 8 posições. Mingua a política africana do Brasil assim como perdem momentum as políticas públicas de promoção da igualdade racial e sofrem evidentes ataques as pautas identitárias da população brasileira afrodescendente. Neste livro, pela primeira vez na literatura sobre a PEB, a autora aponta a vinculação entre as relações Brasil – África e a promoção da igualdade racial no Brasil, propondo a acadêmicos, a militantes do Movimento Negro e a lideranças políticas comprometidas com a luta contra o racismo no Brasil um debate informado em benefício de avanços conceituais no estudo, na formulação e execução da Política Externa do Brasil para a África.', '["Brazil-Africa relations","affirmative action","racial equality","Black movement","racism","Afro-descendant identity","return to Africa"]', '10.7476/9786589992301', '9786589992301', 'https://books.scielo.org/id/fdc6z', 'https://books.scielo.org/id/fdc6z/pdf/gala-9786589992301.pdf', NULL, 'https://books.scielo.org/id/fdc6z/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fdkvy', 'fdkvy', 'Filosofía, tecnociencia e industria 4.0: una mirada desde el medioambiente', NULL, '["William Ítalo Jumbo González"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Actualizar la experiencia y la práctica tecnocientífica en el siglo XXI y encontrar respuestas proactivas en un contexto de crisis ética, personal, familiar y de convulsión social, económica y política es, sin duda, uno de los retos de la ciencia y tecnología. Ante esta situación, el autor presenta una propuesta de formación -tecnoaxiológica y tecnoética de diálogo interdisciplinar- que tiene como objetivo la creación de proyectos con tecnologías limpias y amigables con el medioambiente. Superar el mito del progreso tecnocientífico y caminar hacia el desarrollo sustentable forma parte de la llamada “Revolución Industrial 4.0”', '["Industry 4.0","philosophy of technology","technoscience","environmental ethics","interdisciplinary teaching","environmental technology","sustainable development","critique of technological progress"]', '10.7476/9789978106778', '9789978106778', 'https://books.scielo.org/id/fdkvy', 'https://books.scielo.org/id/fdkvy/pdf/jumbo-9789978106778.pdf', NULL, 'https://books.scielo.org/id/fdkvy/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fdx3q', 'fdx3q', 'Criação, proteção e uso legal de informação em ambientes da World Wide Web', NULL, '["Elizabeth Roxana Mass Araya","Silvana Aparecida Borsetti Gregório Vidotti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'pela ECA/USP e com pós-graduação em artes visuais pela Univer-10 ELIZABETH ROXANA M. ARAYA • SILVANA APARECIDA B. G. VIDOTTI A informação digital, comparada com a informação analógica, é aquela codificada em um formato que o computador pode interpretar (codificação binária).A computabilidade (necessidade de um computador acompanhando um software ou um algoritmo preciso) é uma de suas propriedades.Qualquer morfologia de informação textual, imagética ou sonora é representada por esse único tipo de linguagem (bits: série de zeros e uns) que, além de lhe atribuir a característica de virtualidade, possibilita a multimídia, ou seja, a combinação de pelo menos um tipo de mídia estática (texto, fotografia, gráfico) com um tipo de mídia dinâmica (vídeo, áudio, animação).Nessa linguagem expressam-se e armazenam-se dados e instruções, fato gerador da interatividade própria dos sistemas de informação digitais, teoricamente sem limites.Essa interatividadeprocesso em que um sistema de informação ou de comunicação permite ações dos usuários e lhes oferece respostas de acordo com suas especificidades -favorece o acesso e a recuperação de informação, pois possibilita que o usuário da informação digital realize diversas operações de busca e de descobrimento no ambiente informacional.Na hipertextualidade, forma de interatividade efetiva possibilitada pelos ambientes hipermídia, o usuário constrói seu próprio caminho de navegação pelos documentos e/ou parte deles utilizando-se dos enlaces que ele próprio realiza (Codina, 2001, p.19-21).A produção, a disseminação e o uso de informação por meio da Internet e em seus ambientes informacionais Web favorecem o desenvolvimento de uma cultura baseada em práticas de colaboração e remix.Consequentemente, cria-se um descompasso', '["digital information","World Wide Web","information creation","information security","hypertextuality","hypertext","interactivity","digital information systems","remix culture","collaboration","information dissemination"]', '10.7476/9788579831157', '9788579831157', 'https://books.scielo.org/id/fdx3q', 'https://books.scielo.org/id/fdx3q/pdf/araya-9788579831157.pdf', NULL, 'https://books.scielo.org/id/fdx3q/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fdzzn', 'fdzzn', 'Quem tem medo da geração shopping? uma abordagem psicosocial', NULL, '["Angelina Bulcão Nascimento"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nestas páginas, nos propomos a tecer algumas considerações teóricas sobre a adolescência, numa perspectiva psicossocial, procurando identificar e analisar as principais mudanças e repetições dos comportamentos e papéis dos adolescentes contemporâneos (trecho retirado da Apresentação do livro).', '["adolescence","psychosocial approach","shopping behavior","consumer behavior","adolescent identity","social roles"]', '10.7476/9788523209254', '9788523209254', 'https://books.scielo.org/id/fdzzn', 'https://books.scielo.org/id/fdzzn/pdf/nascimento-9788523209254.pdf', NULL, 'https://books.scielo.org/id/fdzzn/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ff2x7', 'ff2x7', 'Justiça, cidadania e democracia', NULL, '["Roberto Livianu"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os temas abordados pelos autores são da maior relevância jurídico-social. A universalização do acesso à justiça é condição sino qua non para a prática da cidadania, sendo preocupação de primeira ordem, que a recente criação da Defensoria Pública paulista demonstra. A democracia, por sua vez, é um direito conquistado pelos brasileiros que depositaram no Ministério Público a incumbência de sua defesa. [trecho retirado do livro]', '["access to justice","citizenship","democracy","public defender''s office","public prosecution","right to democracy"]', '10.7476/9788579820137', '9788579820137', 'https://books.scielo.org/id/ff2x7', 'https://books.scielo.org/id/ff2x7/pdf/livianu-9788579820137.pdf', NULL, 'https://books.scielo.org/id/ff2x7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ffd4c', 'ffd4c', 'Psicologia e suas interfaces: estudos interdisciplinares', NULL, '["Alvany Maria dos Santos Santiago","Ana Lucia Barreto da Fonsêca"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Psicologia e suas interfaces O décimo capítulo, Sertão: contextos e representações, tendo em vista as representações sociais de sertão entre moradores de Petrolina (PE) e Juazeiro (BA) trata de representações sociais, mais especificamente as representações sociais de sertão entre moradores da região sertaneja Petrolina, em Pernambuco, e Juazeiro, na Bahia.Dois são os períodos focalizados, a colonização e a Independência do Brasil, marcos de grandes transformações e, por conseguinte, campos de representações sociais na história do Brasil.A representação de miséria e pobreza absoluta diante da proposta de enriquecimento econômico dos municípios sertanejos Petrolina (PE) e Juazeiro (BA) traz o novo campo de representação social de sertão.O sertão rico.O décimo primeiro capítulo, "Que gente é essa?": um estudo das representações sociais da carrocinha para os oficiais de controle animal do Recife (PE), apoiado na Teoria das Representações Sociais (TRS), estruturada por Sèerge Moscovici, e na metodologia da análise de conteúdo descrita por Bardin, pretendeu-se compreender as representações sociais dos trabalhadores da saúde responsáveis pela remoção e eutanásia de animais errantes ou portadores de enfermidades incuráveis, a respeito de seu fazer profissional.Esperamos que os resultados aqui expostos possam apoiar o repensar e o planejar das ações de controle de zoonoses com um olhar também para o trabalhador.Psicologia e suas interfaces WATKINS, 1988) A paz foi definida não apenas como ausência da guerra, mas, em termos ativos, como a construção de relações cooperativas entre povos e nações em longo prazo.No final dos anos 1980, o problema da imagem do inimigo (BRONFENBRENNER, 1961) foi reavaliada com maior ênfase nos vieses perceptuais e cognitivos.(HOLT; SILVERSTEIN, 1989) A ameaça nuclear dos anos 1980 deu início a uma preocupação entre alguns psicólogos que passaram a se identificar como psicólogos da paz (peace psychologists) e, em 1991, criaram a Divisão 48 da American Psychological Association (APA).(WESSELLS, 1996) Contudo, no fim do século XX, a preocupação norte-americana com a guerra nuclear recrudesceu e a Psicologia da Paz começou a lidar com novas ameaças à paz e ao bem estar humanos, incluindo insurgências armadas internacionais, deterioração ambiental, populações deslocadas, entre outros.Segundo Christie e colaboradores (2008), vários temas estão emergindo na área, e apresentam uma: 1) maior sensibilidade ao contexto geo-histórico; 2) perspectiva mais diferenciada sobre os significados e tipos de violência e paz; e 3) visão sistêmica ou multinível dos determinantes da violência e da paz.(CHRISTIE, 2006a, 2006b) As preocupações da Psicologia da Paz pós-Guerra Fria se tornaram mais diversas, globais e formatadas por contextos geo-históricos locais.No Ocidente, a pesquisa recente tem sido dominada por esforços para compreender e evitar o terrorismo.(MOGHADDAM, 2005; MOGHADDAM; MARSELLA, 2005; WAGNER, 2006) No Oriente Médio, os estudos tem focalizado os conflitos religiosos e éticos, principalmente em Israel e seus vizinhos, Irlanda do Norte e África do Sul.(HARE, 2006) Na Oceania, as pesquisas têm procurado entender as dimensões psicológicas da reconciliação com os aborígenes na Austrália.o diálogo entre a Psicologia da Paz e o relacionaMento interPessoal 25 Milhares de pesquisas sobre Psicologia da Paz desde a Guerra Fria foram revisadas em Peace psychology: a comprehensive introduction.(BLUMBERG; HARE; COSTIN, 2007) Contudo, o texto mais utilizado no campo interdisciplinar dos estudos da paz é o de Barash e Webel (2002), cuja obra tem uma quantidade substancial de conteúdo psicológico.Nos dois últimos anos, foram lançadas duas enciclopédias sobre a temática.The Oxford international encyclopedia of peace, lançada em 2010, tendo como editor chefe Nigel Young.Essa enciclopédia focaliza o campo interdisciplinar dos estudos sobre a paz e apresenta uma pesquisa dos fatos políticos, históricos, teóricos e filosóficos ligados à paz e ao conflito desde a antiguidade aos dias atuais.A outra enciclopédia, The encyclopedia of peace psychology, foi lançada em 2011, sob a responsabilidade de edição de Daniel Christie e disponibilizada também eletronicamente, através da Wiley Online Library.Essa obra examina as dimensões psicológicas dos estudos sobre paz e conflito, e conta com a contribuição de vários pesquisadores e ativistas da área.A Divisão de Psicologia da Paz (Divisão 48) da American Psychological Association, foi criada em 1991.Segundo a divisão, os objetivos da Psicologia da Paz são "aumentar e aplicar o conhecimento psicológico na busca da paz [...] [incluindo] ambos a ausência de conflito destrutivo e a criação de condições sociais positivas que minimizem a destruição e promovam o bem estar humano."(SOCIETY FOR THE STUDY OF PEACE, CONFLICT, AND VIOLENCE, [2006]) Segundo Christie e colaboradores (2008), a Psicologia da Paz pode ser aplicada para promover a paz nas famílias, locais de trabalho, comunidades e entre nações.Psicologias da Paz: em busca de um arcabouço conceitual Ardila (2001) pontua que a Psicologia da Paz tem por missão desenvolver sociedades sustentáveis por meio da prevenção do conflito destrutivo, da violência e da mitigação de suas consequências, o empoderamento das pessoas e a construção da cultura da paz e Psicologia e suas interfaces de uma comunidade global.O autor define esse campo de estudo como, O campo de investigação e aplicação que utiliza os achados científicos, os métodos e as teorias da psicologia, para a compreensão e modificação dos problemas associados à paz, guerra, violência, agressão e os conflitos entre grupos, comunidades, instituições e nações.(ARDILA, 2001, p. 40) Souza e colaboradores (2006) definem Psicologia da Paz como "campo de estudos e práticas em Psicologia que aborda as temáticas da paz, da guerra, do conflito e da violência".Acrescenta que, [...] o objetivo fundamental é promover uma convivência mais pacífica entre indivíduos, grupos humanos ou nações.Possibilita a criação de novas estratégias de resolução de conflitos, bem como a consolidação ou desenvolvimento das já existentes.Vollhardt e Bilali (2008, p. 13) trabalham os conceitos de Psicologia da Paz e Psicologia Social e definem o estudo social e psicológico da paz como, O campo da teoria e prática psicológica visando a prevenção e mitigação da violência estrutural e direta entre membros de diferentes grupos sociopolíticos, assim como a promoção de cooperações e uma orientação prossocial que reduzam a ocorrência de violência intergrupal e violência na sociedade e fomente relações intergrupais positivas.A Psicologia da Paz apresenta um amplo campo de estudo com característica multidisciplinar.Ardila (2001) e Souza (2003) enumeram alguns desses temas: origem da agressão e a influência dos fatores biológicos e dos fatores culturais, a guerra e seu lugar na história da humanidade, a solução de conflitos, o terrorismo, a origem ontogenética dos conceitos de guerra e paz, a violência política, social e econômica contra os grupos minoritários (crianças, mulheres, idosos, imigrantes, asilados), a violência sexual, a comunicação entre os grupos em conflitos, formação de valores em crianças e adultos o diálogo entre a Psicologia da Paz e o relacionaMento interPessoal 27 -como cooperação, solidariedade e respeito aos direitos humanos.A Psicologia da Paz trabalha na linha da formação de uma cultura de não violência, educação para a paz e configura-se como uma nova abordagem nas relações internacionais e na prevenção de formas futuras de conflito e violência.De acordo com Christie e colaboradores (2008), a Psicologia da Paz pós-Guerra Fria deve muito ao trabalho conceitual de Johan Galtung (1969), que diferenciou violência direta e estrutural.Violência direta é episódica, tipicamente ferindo ou matando pessoas rápida e dramaticamente.Em contraste, a violência estrutural representa uma ameaça crônica ao bem estar humano, ferindo ou matando pessoas len', '["social representations","sertão","social representations theory","zoonosis control","Petrolina","Juazeiro","social representations of poverty","peace psychology","enemy image","nuclear threat","psychology and society"]', '10.7476/9788523220075', '9788523220075', 'https://books.scielo.org/id/ffd4c', 'https://books.scielo.org/id/ffd4c/pdf/santiago-9788523220075.pdf', NULL, 'https://books.scielo.org/id/ffd4c/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ffk9n', 'ffk9n', 'Gestão e avaliação de risco em saúde ambiental', NULL, '["Ogenis Magno Brilhante","Luiz Querino de Araújo Caldas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Sem cair no diletantismo acadêmico tão comum ao se abordar um tema de ponta, contemporâneo e fascinante como o que é tratado neste livro, os autores objetivam, por meio do resgate de fundamentos conceituais e do surgimento de inovações relacionadas ao manejo de risco com avaliação e gestão, introduzir avanços tecnológicos ainda não aplicados em nosso país. Como resultado, uma reflexão sobre planejamento, gestão, processos e modelos de promoção da saúde ambiental e, ainda, avaliação de riscos ambientais à saúde humana e aos ecossistemas. Instiga o diálogo entre cientistas, planejadores e usuários da saúde coletiva e da engenharia sanitária, o que certamente possibilitará melhores práticas sociais e científicas para ambos os campos.', '["environmental health risk assessment","environmental health planning","health promotion","sanitary engineering","collective health"]', '10.7476/9788575412411', '9788575412411', 'https://books.scielo.org/id/ffk9n', 'https://books.scielo.org/id/ffk9n/pdf/brilhante-9788575412411.pdf', NULL, 'https://books.scielo.org/id/ffk9n/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ffxy9', 'ffxy9', 'Decolonialidade afro-brasileira: a educação para a diferença', 'a educação para a diferença', '["Eduardo O. Miranda"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra elucida sobre Decolonialidade Afro-Brasileira como saber insurgente no combate aos apagamentos e ao epistemicídio sofridos pelos valores civilizatórios afrodiaspóricos e suas tecnologias ancestrais e estabelece o aparato de ética e estética, filosófico e cultural que dá o chão e abre caminho. Nesta escrita, Eduardo Miranda ritualiza e elucida em cada capítulo a Decolonialidade Afro-Brasileira como perspectiva teórica que expande para todas as áreas de conhecimento. É sobre Axé, ciência, tecnologia periférica, ancestral, inovação, desobediência para vencer demandas coloniais. Em tempos de refazimentos das estratégias que ainda insistem em tentar apequenar as existências de corpos-territórios historicamente subalternizados, em Decolonialidade Afro-Brasileira: a educação para a diferença, recorre-se às epistemologias dos Odus para dizer que não se dança um alujá no conforto da sua cadeira, é preciso movimentar-se, inquietar-se.', '["decoloniality","epistemicide","Odu","innovation","disobedience","colonialism"]', '10.7476/9786556309033', '9786556307374', 'https://books.scielo.org/id/ffxy9', 'https://books.scielo.org/id/ffxy9/pdf/miranda-9786556309033.pdf', NULL, 'https://books.scielo.org/id/ffxy9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fghxy', 'fghxy', 'Educação infantil, currículos e linguagens: pesquisas, políticas e práticas', 'pesquisas, políticas e práticas', '["Elaine Luciana Sobral Dantas","Milena Paula Cabral de Oliveira","Denise Maria de Carvalho Lopes"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, intitulada Educação Infantil, Currículos e Linguagens: pesquisas, políticas e práticas, organizada pelo Grupo de Pesquisa e Extensão em Educação da Infância, Cultura, Currículo e Linguagem – EDUCLIN, reúne trabalhos de iniciação científica desenvolvidos entre os anos de 2017 e 2020 no âmbito do projeto de pesquisa Currículos da Educação Infantil: entre propostas e práticas pedagógicas e os textos oriundos das conferências e rodas de diálogos realizadas no I Simpósio de Educação Infantil (SIMEI), realizado no ano de 2019 na Universidade Federal Rural do Semiárido (UFERSA), Campus de Angicos. É constituída por quinze textos de professores, estudantes e pesquisadores do EDUCLIN e de outros grupos de pesquisa envolvidos com a área da educação infantil que apresentam perspectivas e análises críticas e reflexivas de temas que se entrecruzam, como: as significações de cultura, currículos e linguagens em relação aos documentos oficiais e teorizações da área; as políticas curriculares e suas repercussões nas práticas; as especificidades das práticas pedagógicas, considerando sentidos de professores e de crianças; as linguagens que constituem os currículos e as práticas cotidianas; e o trabalho dos profissionais da educação infantil – professores e gestores na efetivação do planejamento e da construção de currículos. A publicação constitui-se portanto, em um trabalho de muitas interlocuções, muitos fios tecidos na construção dos estudos sobre educação infantil, currículos e linguagens nos contextos das pesquisas, das políticas e das práticas. A expectativa é que essa interlocução seja ampliada na relação com cada leitor e na possibilidade de discussão dos textos no cotidiano das instituições de educação infantil em diálogo com os(as) professores(as) e demais profissionais e pesquisadores da primeira infância.', '["early childhood education","course program","language","curriculum policy","teaching practice","teacher professional development","curriculum development","early childhood educators","early childhood education policy"]', '10.7476/9788557571594', '9786587108551', 'https://books.scielo.org/id/fghxy', 'https://books.scielo.org/id/fghxy/pdf/dantas-9788557571594.pdf', NULL, 'https://books.scielo.org/id/fghxy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fhn4p', 'fhn4p', 'Relatório reforma do judiciário', NULL, '["Paulo César Carbonari"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O debate sobre o acesso à justiça, além de oportuno no seio da reforma do Judiciário, é estratégico na perspectiva da promoção dos direitos humanos. Além de ser um direito humano fundamental, o acesso à justiça é uma das condições para garantir a efetividade do conjunto dos direitos humanos. Uma sociedade que não garante o acesso à justiça dificilmente pode se dizer uma sociedade que efetivamente atingiu um Estado Democrático de Direito.', '["judicial reform","access to justice","human rights","rule of law","democratic state","effectiveness of human rights"]', '10.7476/9788579820304', '9788579820304', 'https://books.scielo.org/id/fhn4p', 'https://books.scielo.org/id/fhn4p/pdf/carbonari-9788579820304.pdf', NULL, 'https://books.scielo.org/id/fhn4p/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fhr95', 'fhr95', 'A reinvenção do desenvolvimento: agências multilaterais e produção sociológica', NULL, '["Ivo, Anete B. L."]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro resulta da pesquisa A Reinvenção do Desenvolvimento: agências multilaterais e produção sociológica contemporânea, cujo objetivo é analisar a circulação de ideias, a influência e as relações complexas entre as agências multilaterais e a agenda de pesquisas das Ciências Sociais, especialmente da Sociologia, nas duas últimas décadas.Ele representa a continuidade de esforços anteriores de pesquisa, com a produção de textos coletivos e individuais voltados para recompor o estado da arte da Sociologia do Desenvolvimento, inicialmente publicados no Dicionário Temático Desenvolvimento e Questão Social, São Paulo, Annablume (2013), e no Estado da Arte da Sociologia nos estudos sobre desenvolvimento, Brasília, IPEA (2014).Resulta de uma articulação entre professores pesquisadores de diferentes campos disciplinares, vinculados a programas de pós-graduação e a centros de pesquisas universitários, que buscam analisar e reconstruir os parâmetros do desenvolvimento e das Ciências Sociais no contexto contemporâneo, de uma perspectiva sociológica, política e das relações internacionais, com base numa agenda global formulada por várias organizações internacionais, especialmente em relação aos Objetivos do Desenvolvimento Sustentável (ODS) e a Agenda Pós-2015 das Nações Unidas.Com essa publicação, pretende-se transcender o espaço restrito da pesquisa e da produção individual de cada pesquisador associado e possibilitar diálogos mais amplos, questionando as relações complexas e interdependentes entre as agências multilaterais (PNUD, Banco Mun-desenvolvimento humano na produção sociológica mais recente e as relações de cooperação intergovernamentais entre países.A originalidade desse projeto assenta-se em três perspectivas associadas.A primeira resulta do diálogo e da reconstrução interdisciplinar, ambos alimentados pelas dimensões conceituais do desenvolvimento postuladas pelas agências internacionais em diversos programas e escalas.Esse esforço exigiu um ir e vir constante das diversas disciplinas à produção sociológica em temas específicos.Uma segunda perspectiva inscreve-se numa visão analítica e crítica desses processos, sem adesão normativa aos prognósticos dessas organizações internacionais, visando a contribuir para a dinâmica sempre inacabada entre a pesquisa, a produção de conhecimentos, a política e um regime de ação para a mudança social, protagonizada por diversos agentes.Por fim, essas análises permitem observar, no plano da práxis, como se tecem as relações complexas e dialéticas entre a ciência, os atores e a política, considerando as organizações internacionais como agentes políticos globais em interação permanente com o setor público intergovernamental e a sociedade civil dos países e a comunidade acadêmica.Sabe-se, no entanto, que os resultados aqui apresentados têm caráter provisório, não pela natureza exploratória das análises, mas pelo caráter histórico do conhecimento nas Ciências Sociais, que, em interação com a realidade social, se modifica constantemente, interpelado no curso da sua própria ação pelas críticas, o que alimenta uma dialética continuada e reflexiva entre conhecimento, política e ação social global.Ainda que essas pretensões pareçam ambiciosas, considerado o horizonte modesto desse projeto em termos de equipe e financiamento, sabe-se que os resultados vêm avançando progressivamente, abrindo-se a novas perspectivas e conhecimentos, propiciando uma aprendizagem no debate público e com as reflexões trazidas por interlocutores em diversos fóruns de discussão.Em que pesem os seus limites e a cautela sobre os alcances da pesquisa, os resultados apresentados alimentam e possibilitam novas perspectivas e dilemas das 10 | Anete B. L. Ivo investigações no âmbito da interdisciplinaridade e das escalas entre a produção da Ciência Social e os processos globais.Aos colegas que compartilham dessa iniciativa, e aos demais colegas que integraram etapas anteriores desse projeto expresso aqui meus agradecimentos pelas colaborações inestimáveis, tanto na pesquisa e no fomento como nesta publicação coletiva.Como responsável coordenadora dessa investigação, minha dívida pessoal não se esgota com esses colegas, autores que colaboraram na discussão de aspectos da agenda do desenvolvimento sustentável em escala global e sua relação com a produção sociológica, sob inúmeras formas e estratégias.Cada pesquisador trabalhou com autono', '["development agencies","UNDP","World Bank","Sustainable Development Goals","post-2015 development agenda","sociology of development","circulation of ideas","international organizations","intergovernmental cooperation","development discourse","human development","interdisciplinary dialogue"]', '10.7476/9788523218577', '9788523218577', 'https://books.scielo.org/id/fhr95', 'https://books.scielo.org/id/fhr95/pdf/ivo-9788523218577.pdf', NULL, 'https://books.scielo.org/id/fhr95/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fj5qc', 'fj5qc', 'As sociedades contemporâneas e os direitos humanos = Contemporary societies and human rights', NULL, '["Martins, Bruno Sena","Ana Lúcia Santos","Saskya Miranda Lopes"]', 'SciELO', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os Direitos Humanos têm sido mobilizados para a transformação social em diferentes contextos regionais, nacionais e locais. Neste quadro, este livro, composto por textos de autores internacionais com temas ligados a diferentes regiões do mundo, propõe uma agenda crítica aberta a um diálogo construtivo, intercultural, que tome em consideração lutas, conhecimentos e mundos alternativos.', '["human rights","social change","intercultural dialogue","critical perspective","alternative worlds","social struggles","regional context"]', '10.7476/9788574555256', NULL, 'https://books.scielo.org/id/fj5qc', 'https://books.scielo.org/id/fj5qc/pdf/martins-9788574555256.pdf', NULL, 'https://books.scielo.org/id/fj5qc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fjjv5', 'fjjv5', 'OMINÍBÚ: maternidade negra em um defeito de cor', NULL, '["Fabiana Carneiro da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'É a partir do romance Um defeito de cor, de Ana Maria Gonçalves, que Fabiana Carneiro da Silva revisita os significados da maternidade negra no Brasil. “Das profundezas das águas”, como sugere o título Ominíbú, termo do iorubá, são revolvidas as histórias acerca das travessias feitas por uma mulher corajosa que enfrenta os embates de uma ordem que intenta explorar até a exaustão os corpos marcados pela ideologia escravagista. No romance, o tema da maternidade emerge em um cenário construído por uma mãe que, ao final de sua vida, narra as tentativas de localizar o filho, vendido como escravo pelo próprio pai. Tecendo uma análise estética apurada, Fabiana da Silva evidencia as correspondências entre a conformação do relato-carta da protagonista e o contemporâneo. Desde a teoria literária, esse livro busca um diálogo sensível à experiência das comunidades negras, sobretudo das mulheres a elas pertencentes, a fim de promover uma reflexão comprometida com a construção de um espaço plural questionador do fundamento racista da construção nacional brasileira.', '["Black motherhood","Um defeito de cor","Ana Maria Gonçalves","slavery","slave trade","mother-daughter correspondence","Black women","racism","Brazilian national identity"]', '10.7476/9786556301976', '9788523219079', 'https://books.scielo.org/id/fjjv5', NULL, NULL, 'https://books.scielo.org/id/fjjv5/cover/cover_thumbnail.jpeg', 228, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fjnhs', 'fjnhs', 'Clássicos do pensamento pedagógico: olhares entrecruzados', NULL, '["Carlota Boto"]', 'EDUFU', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Os autores aqui reunidos compreendem que a história do pensamento pedagógico, sob a chave da interpretação das ideias e das teorias educacionais, ainda tem algo a dizer à Pedagogia. Sabe-se que os modos de ser e de atuar na escola e na família são ancorados por um conjunto de teorias e de interpretações pedagógicas passíveis de serem delineados à luz da trajetória que compõe a obra de inúmeros autores do território pedagógico.”', '["history of educational thought","educational theory","pedagogical interpretation","pedagogy"]', '10.7476/9786558240273', '9788570784728', 'https://books.scielo.org/id/fjnhs', 'https://books.scielo.org/id/fjnhs/pdf/boto-9786558240273.pdf', 'https://books.scielo.org/id/fjnhs/epub/boto-9786558240273.epub', 'https://books.scielo.org/id/fjnhs/cover/cover_thumbnail.jpeg', 344, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fjprq', 'fjprq', 'Mulheres e crianças na imprensa paulista (1920-1940): educação e história', NULL, '["Raquel Discini de Campos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No início do século XX, a zona Araraquarense (atual Noroeste Paulista) passou por um grande desenvolvimento econômico, cultural e social, em virtude do fluxo de imigrações, o que mudou em pouco tempo os padrões daquela sociedade. Em meio a esse turbilhão, passaram a circular diversos jornais produzidos regionalmente, que retrataram todas as novidades desse período e os estilos de vida que emergiam. Com base nesses textos antigos, duas importantes temáticas foram pesquisadas e tratadas nesta obra: a contraditória apropriação feminina dos espaços públicos, que naqueles tempos ganhava grande publicidade, e a preservação da educação, assistência e ordenação das crianças do sertão.', '["women in the press","children in the press","regional press","early 20th century","women''s public space","women''s education","child welfare","immigration","sertão","newspaper history"]', '10.7476/9788539304424', '9788571399037', 'https://books.scielo.org/id/fjprq', NULL, NULL, 'https://books.scielo.org/id/fjprq/cover/cover_thumbnail.jpeg', 224, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fjzjm', 'fjzjm', 'Educación legal clínica y litigio estratégico en Iberoamérica', NULL, '["Beatriz Socorro Londoño Toro"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra es resultado de investigación sobre dos conceptos de enorme importancia para la educación jurídica en Iberoamérica: la educación legal clínica como modelo pedagógico en construcción y el litigio estratégico como herramienta de incidencia social y política. Se considera que el proceso de construcción de las clínicas en la región es un hito en la educación jurídica iberoamericana y existen evidencias que permiten afirmarlo, ya que se trata de historias paralelas que se fortalecieron por los intercambios de aprendizajes y experiencias a través de las redes. De igual manera se desarrolla el concepto de litigio estratégico o estructural y se examina la forma como inciden en dicha propuesta las alianzas estratégicas. Se pasa luego a una profundización sobre la agenda de las clínicas y los temas prioritarios de Derechos Humanos en Iberoamérica. Examen que se realiza a partir de casos reales que se han trabajado las clínicas. Se concluye en la necesidad del surgimiento de nuevas clínicas y de más proyectos de investigación.', '["clinical legal education","strategic litigation","structural litigation","Ibero-America","legal education","strategic alliances","human rights","legal clinics","knowledge exchange networks"]', '10.7476/9789587386240', '9789587386240', 'https://books.scielo.org/id/fjzjm', 'https://books.scielo.org/id/fjzjm/pdf/londono-9789587386240.pdf', NULL, 'https://books.scielo.org/id/fjzjm/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fk2qn', 'fk2qn', 'Descobrindo a surdocegueira: educação e comunicação', NULL, '["Fátima Ali Abdalah Abdel Cader-Nascimento","Maria da Piedade Resende da Costa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro representa uma cuidadosa contribuição de profissionais da área de Educação Especial para a ampliação e o fortalecimento de informações sobre surdocegueira. Sua abordagem, para além da disponibilidade e do envolvimento pessoal e profissional das autoras, sua coerência e seu rigor metodológicos, derivados de diversos estudos e pesquisas, resultam em uma mensagem de esperança e compromisso com a construção de uma nova ordem social que priorize o respeito à diversidade e que a reconheça como enriquecedora para a convivência humana. O eixo principal desta obra remete o leitor - de esferas administrativa e legislativa, profissionais da área de Educação Especial, alunos em formação, pais e educadores - à reflexão sobre os diferentes entendimentos e percepções acerca da temática, de forma que se perceba a grandeza das condições humanas de adaptabilidade e flexibilidade. Além disso, pretende-se despertar interrogações e questionamentos sobre diferentes experiências de pessoas que utilizam trilhas perceptuais desconhecidas, incomuns.', '["deafblindness","special education","communication","diversity","social inclusion","human adaptability","deafblind people"]', '10.7476/9788576003717', '9788576003717', 'https://books.scielo.org/id/fk2qn', 'https://books.scielo.org/id/fk2qn/pdf/cadernascimento-9788576003717.pdf', NULL, 'https://books.scielo.org/id/fk2qn/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fk6n4', 'fk6n4', 'Cambio climático. Acuerdos y contradicciones', NULL, '["Tania Alexandra Chicaiza Villalba","García Jiménez, Susana","Núñez Rodríguez, Carlos Juan"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El libro Cambio climático. Acuerdos y contradicciones es el resultado del trabajo continuo que desde hace casi una década realizan la Universidad Politécnica Salesiana de Ecuador y la Universidad Autónoma Metropolitana Unidad Azcapotzalco de México. Después de un intenso trabajo colaborativo que ha dado lugar a publicaciones, recepción de alumnos y alumnas, ciclos de conferencias y enriquecimiento mutuo; ahora damos un paso más y publicamos este trabajo. Se prefiguró en el Congreso de la Red Pilares en Santiago de Chile, donde luego de una mesa sobre Responsabilidad Social, acordamos continuar la discusión sobre los efectos que el neoliberalismo en América Latina había causado, enfrentando la reflexión de los derechos humanos, primero como un horizonte de interpretación y construcción de sentido en el proceso de comprensión de los efectos devastadores de este modelo económico y de práctica política, estatal y empresarial.', '["climate change","neoliberalism","human rights","Latin America","social responsibility","political economy"]', '10.7476/9789978108178', '9789978108178', 'https://books.scielo.org/id/fk6n4', 'https://books.scielo.org/id/fk6n4/pdf/chicaiza-9789978108178.pdf', NULL, 'https://books.scielo.org/id/fk6n4/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fkbbh', 'fkbbh', 'Espaços da Ciência no Brasil: 1800-1930', NULL, '["Maria Amélia M. Dantes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resultado de extensa pesquisa que valoriza a historiografia da ciência no país, discute o papel das instituições que abrigaram práticas científicas desde o período colonial. Analisam-se, na obra, o percurso e a atuação de instituições como o Jardim Botânico, a Faculdade de Medicina e a Academia Brasileira de Ciências, no Rio de Janeiro, e os Institutos Butantan e Adolfo Lutz, em São Paulo. Este livro propõe novas questões, que partem de espaços institucionais fundadores de uma tradição científica para ampliar os estudos em história da ciência, constituindo importante fonte de pesquisa.', '["history of science","research institutions","Brazilian science","Rio de Janeiro","São Paulo","Faculdade de Medicina","Instituto Butantan","Instituto Adolfo Lutz","colonial period"]', '10.7476/9786557081570', '9786557081570', 'https://books.scielo.org/id/fkbbh', 'https://books.scielo.org/id/fkbbh/pdf/dantes-9786557081570.pdf', NULL, 'https://books.scielo.org/id/fkbbh/cover/cover_thumbnail.jpeg', NULL, 44, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fm', 'fm', 'O encantamento de sua santidade: cancão de fogo', NULL, '["Ordep J. Trindade-Serra"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Livro de cordel que repõe em circulação a figura legendária de Cancão de Fogo, um herói popular brasileiro, personagem um tanto esquecido de contos, versos e anedotas picarescas nordestinas. Além de uma trilogia sobre as aventuras de Cancão de Fogo, encerra um outro cordel, intitulado “Bodas de Mangue”, que já fora dado a público sob a forma de peça teatral encenada no Teatro Vila Velha, em Salvador, sob a direção de Carlos Gregório, com narração de Antônio Vieira e papéis dramáticos principais vividos pelos atores Bárbara Borgga e Hilton Sousa.', '["cordel literature","popular heroes","Brazilian popular literature"]', '10.7476/9788523209131', '9788523209131', 'https://books.scielo.org/id/fm', 'https://books.scielo.org/id/fm/pdf/trindade-9788523209131.pdf', NULL, 'https://books.scielo.org/id/fm/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fm24q', 'fm24q', 'Atuação pública e promoção da eficiência coletiva em arranjos produtivos locais: a experiência do polo industrial de Franca-SP', NULL, '["Agnaldo de Sousa Barbosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra tem por objetivo analisar referências em abordagens que reconhecem a centralidade do papel do Estado e suas instituições com a atuação pública. Para tanto, verifica se o Estado é ou não o ator responsável pela emulação de mudanças estruturais indispensáveis ao incremento da dinâmica de desenvolvimento econômico-social.', '["public action","collective efficiency","local productive arrangements","industrial pole","role of the state","state institutions","economic development"]', '10.7476/9788568334768', '9788568334768', 'https://books.scielo.org/id/fm24q', 'https://books.scielo.org/id/fm24q/pdf/barbosa-9788568334768.pdf', NULL, 'https://books.scielo.org/id/fm24q/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fm4ng', 'fm4ng', 'Filosofia da História', NULL, '["Georg Wilhelm Friedrich Hegel"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nestas lições sobre a filosofia da história universal, a trajetória da humanidade é retrilhada e interpretada por aquele que foi o líder indiscutível do pensamento filosófico da Alemanha de sua época e um dos filósofos de maior influência em todos os tempos. Publicada pela primeira vez em 1837, seis anos após a morte do autor, "Filosofia da história" é a obra que representa o estágio mais elevado e desenvolvido de seu pensamento, sendo um resumo e uma conclusão de toda a sua obra anterior. Aqui estão presentes os conceitos fundamentais de Hegel: a idéia, o espírito, a razão, a moralidade objetiva (ética, social) e a subjetiva (pessoal, individual). Os mais importantes fatos e indivíduos históricos são descritos e analisados. É uma viagem no tempo e no espaço, que vai da Ática às Américas, passando pela Ásia, pela África e pela Europa. Da Grécia antiga à Revolução Francesa, acompanhamos a evolução do espírito em busca de sua plena realização na liberdade de seus desígnios.', '["Hegel","philosophy of history","universal history","ideas","alcoholic beverages","reason","objective morality","subjective morality","ethics","social ethics","historical figures","ancient Greece"]', '10.7476/9786558461630', '9788523003623', 'https://books.scielo.org/id/fm4ng', NULL, NULL, 'https://books.scielo.org/id/fm4ng/cover/cover_thumbnail.jpeg', 373, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fmb5z', 'fmb5z', 'A (des)patologização do processo de escolarização: contribuições da psicologia histórico-cultural', NULL, '["Nilza Sanches Tessaro Leonardo","Sílvia Maria Cintra da Silva","Záira Fátima de Rezende Gonzalez Leal"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Considera-se relevante a presente coletânea por aglomerar e apresentar estudos e pesquisas que tratam sobre a patologização e medicalização do processo de escolarização, a partir dos pressupostos teóricos da Psicologia Histórico-Cultural. Busca contribuir para a construção de reflexões e compreensões que abram possibilidades de contraposição às concepções hegemônicas sobre os problemas no processo de escolarização, concepções estas que partem de um viés biologicista e patologizante que culmina na medicalização da educação.', '["school processes","medicalization of education","pathologization","historical-cultural psychology","biological reductionism"]', '10.7476/9786587626086', '9786587626048', 'https://books.scielo.org/id/fmb5z', NULL, NULL, 'https://books.scielo.org/id/fmb5z/cover/cover_thumbnail.jpeg', 382, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fmnch', 'fmnch', 'Corte a mortalha: o cálculo humano da morte infantil no Ceará', NULL, '["Marilyn Kay Nations"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'expressão "Se Deus quiser..." uma atitude de resignação por parte dos pais pobres diante da morte da sua criança, os quais eram vistos, até então, como conformistas e, até mesmo, negligentes na morte dos seus filhos.Permitiu avaliar exaustivamente e confirmar cientificamente a aptidão e as habilidades das pessoas leigas e sem educação formal para captar e entender os procedimentos médicos necessários para salvar a vida da sua criança.E, finalmente, subsidiou a demonstração, passo a passo, de como é possível traduzir a linguagem científico-técnica, incompreensível às pessoas leigas e analfabetas que mais precisam de instruções, na linguagem da vida cotidiana, para, por exemplo, ensiná-las a preparar a receita de soro caseiro, utilizando palavras, conceitos e imagens do seu ambiente de vida, facilmente compreensíveis.Sem dúvida, foi a conjugação interdisciplinar da antropologia com a medicina que forneceu as pistas e a criatividade necessária para a criação de um paradigma alternativo, conhecido hoje como modelo Rezas e Soro, que integra a biomedicina à medicina popular, numa visão humanizada, centrada na cultura local e nas competências das pessoas leigas para pensar e agir diante das doenças diarréicas.O primeiro artigo desta coletânea, intitulado "Anjos com asas molhadas não voam: sentimento materno no Brasil e a imagem da negligência", é atualmente muito consultado ou lido, o que nos indica ter se tornado uma referência na disciplina.A discussão centrada nos aspectos teóricos que nele se trava penetra no cerne da antropologia, refutando e contestando o que é mais sagrado na disciplina: a interpretação do comportamento humano.Publicado originalmente em 1988 na revista Culture, Medicine and Psychiatry, sediada na renomada Universidade de Harvard, EUA, sua divulgação provocou um grande debate entre antropólogos, principalmente nos Estados Unidos, por criticar duramente a teoria da negligência materna seletiva proposta principalmente por Nancy Scheper-Hughes (1984, 1985), antropóloga e professora titular na Universidade da Califórnia, Berkeley, que se baseava em suas pesquisas etnográficas conduzidas em uma favela em Recife, Pernambuco, as quais culminaram na publicação, em 1992, do seu premiado livro, Death without Weeping: the violence of everyday life in Brazil [Morte sem choro: a violência da vida cotidiana no Brasil].Em meu artigo, contestei, juntamente com a co-autora, Linda Anne Rebhun, hoje professora titular de antropologia na Universidade da Califórnia, EUA, essa concepção, colocando para o debate sobre o tema dúvidas e suspeitas não somente sobre a precisão da densa descrição da etnografia eloqüentemente relatada pela professora Scheper-Hughes acerca da morte infantil no nordeste brasileiro, mas também sobre a interpretação teórica dos seus dados qualitativos.Em "Anjos com asas molhadas não voam...", relatamos nossa pesquisa etnográfica conduzida na mesma época da pesquisa de Scheper-Hughes, e, essencialmente, na mesma região do nordeste, ou seja, em um contexto culturalmente parecido.É um estudo comparativo que, nos círculos acadêmicos da antropologia, provocou um debate algo explosivo, pois, do começo até o fim do artigo, apresentamos evidências etnográficas e interpretações que divergiam da teoria da negligência materna seletiva, refutando-a como a mais importante explicação das altas taxas de mortalidade infantil no nordeste brasileiro.Ao menos da forma como alguns filósofos clássicos como Edmund Husserl (1859-1938), Wilhelm Dilthey (1833-1911) e Karl Popper (1902-1994), ou pensadores contemporâneos como Alan Chalmers, nos levam a concluir sobre a epistemologia do pensamento científico.Chalmers, por exemplo, critica duramente a concepção indutivista do conhecimento científico e, no seu âmbito, as afirmações universais, ou seja, as leis e teorias derivadas dos fatos (como a teoria da negligência materna seletiva).Para ele, o raciocínio indutivo -necessário para tornar observações individuais em leis gerais -é "ingênuo" e "completamente equivocado e mesmo perigosamente enganador" (Chalmers, 1993: 24).Para serem consideradas legítimas, as generalizações devem satisfazer três condições: o número de proposições de observação que formam a base de uma generalização deve ser grande; as observações devem ser repetidas sob uma ampla variedade de condições e nenhuma proposição de observação deve conflitar com a lei universal derivada.Com base nesses três requisitos, citados por Chalmers, tentamos, neste nosso artigo, exaustivamente até falsear e, de certa forma, desqualificar a tão divulgada teoria de Scheper-Hughes.Embora tal discussão possa parecer, para alguém de fora, mais uma disputa cruel entre intelectuais, esse debate entre posições divergentes é crucial para a antropologia.Pois Karl Popper (apud Barreto & Moreira, 1993) sustenta a idéia de que generalizações empíricas (teoria e leis) são, de fato, falseáveis, e não verificáveis, e que essa falseabilidade deve ser buscada, e não evitada, pela adição artificial das hipóteses ad hoc (flexibilização da teoria de modo a abranger as anomalias ou casos não previstos em seu escopo, e que, por seu turno, não podem ser falseadas).Popper enfatiza que a ciência é um saber hipotético conjetural de "experimentos cruciais" ou refutações decisivas para aperfeiçoar as teorias e sua potência explicativa.Para esse filósofo, o conhecimento progride por conjecturas e refutações, e não por acumulação de verdades, como no indutivismo.Por isso mesmo, toda teoria, inclusive esta que está em questão aqui, precisa "sofrer um minucioso confronto com a experiência" (Barreto & Moreira, 1993: 84).Numa palavra, falseamento e refutação se tornam critérios essenciais de cientificidade.Como o filósofo Popper mesmo adverte, "A teoria será tanto mais considerada quanto mais resista ao confronto da experiência e das teorias rivais" (apud Barreto & Moreira, 1993: 84-85).Em suas reflexões sobre a produção científica do conhecimento, Popper (1967: 180) aprofundou ainda mais sua linha de raciocínio: O método de procurar verificações parecia-me pouco válido -pareciame, na verdade, ser o método típico de uma pseudociência.Apercebi-me da necessidade de se distinguir, tão claramente quanto possível, este método de um outro -o método de testar uma teoria tão severamente quanto se for capaz -isto é, o método da crítica, o método de procurar casos que constituam falsificação.Nesse sentido, pretendemos concluir que a teoria da negligência materna seletiva seria válida somente até o ponto em é capaz de abarcar a realidade.Do contrário, é falsa.É descartável.Contemporaneamente, o famoso antropólogo americano Clifford Geertz (1973), um defensor admirável da antropologia interpretativa, também adverte que a natureza da etnografia é (e deve ser) essencialmente contestável.Para ele, o perigoso é o monólogo em etnografia, ou seja, a leitura única de uma realidade, visto que a antropologia não costuma trabalhar com grupos de controle, como nas ciências exatas, para testar a veracidade dos dados.Monólogos, disse Geertz, "são de pouco valor quando não há conclusões a serem relatadas, mas sim uma discussão para ser sustentada" (1973: 29).Quando a atenção do leitor é monopolizada pela argumentação de uma só pessoa, não há lugar para interpretações outras.A etnografia interpretativa, conclui Geertz, "é marcada menos pela perfeição do consenso e mais pelo refinamento do debate " (1973: 29).Se para nada mais servir o nosso artigo "Anjos com asas molhadas não voam", ele, pelo menos, terá silenciado para sempre o monólogo de Scheper-Hughes, abrindo a possibilidade de outras interpretações do mesmo fenômeno trágico -a morte de crianças no nordeste brasileiro e a reação materna diante dela.Por outro lado, por que deveria interessar ao pesquisador brasileiro um artigo que contesta tanto a teoria de Scheper-Hughes quanto os seguidores de outras teorias que, em sua essência, a meu ver, culpabilizam mães pobres?Observei, anos atrás, que meus alunos de medicin', '["child mortality","infant diarrhea","lay health workers"]', '10.7476/9788575415139', '9788575415139', 'https://books.scielo.org/id/fmnch', 'https://books.scielo.org/id/fmnch/pdf/nations-9788575415139.pdf', NULL, 'https://books.scielo.org/id/fmnch/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
