INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fn55z', 'fn55z', 'Desenvolvimento de projetos audiovisuais: pela Metodologia DPA', NULL, '["Pablo Del Teso"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta publicação o passo a passo da metodologia DPA para desenvolvimento de projetos audiovisuais de qualquer natureza. Por meio dela, o leitor poderá padronizar práticas profissionais, organizar e controlar processos, determinar papeis e funções de uma equipe de desenvolvimento, além de otimizar recursos. O autor trata da organização do roteiro às ações de marketing, a fim de agregar valor ao projeto e obter financiamento para transformá-lo em um produto audiovisual.', '["audiovisual production","production process control","project financing","marketing planning","value creation","resource optimization"]', '10.7476/9788574554488', '9788574554488', 'https://books.scielo.org/id/fn55z', 'https://books.scielo.org/id/fn55z/pdf/teso-9788574554488.pdf', NULL, 'https://books.scielo.org/id/fn55z/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fnn82', 'fnn82', 'Imaginário e viajantes no Brasil do século XIX: cultura e cotidiano, tradição e resistência', NULL, '["José Carlos Barreiro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro busca compreender alguns aspectos da sociedade brasileira do século XIX. Para isso, a partir da investigação do imaginário dos viajantes, reconstitui o cotidiano e as lutas sociais das classes subalternas do período. Este livro parte do registro das impressões de viajantes estrangeiros e das classes subalternas para traçar um panorama das práticas e dos mecanismos de luta social no Brasil do século XIX. Nesse período, segundo o autor, essas classes não haviam ainda incorporado a noção de propriedade e a ética do trabalho capitalista e expressavam, em suas manifestações culturais, geralmente críticas e bem-humoradas, os primeiros sinais populares de busca de cidadania no país.', '["19th-century Brazilian society","everyday life","social struggles","subaltern groups","popular culture","resistance","tradition","citizenship"]', '10.7476/9788539303144', '9788571394445', 'https://books.scielo.org/id/fnn82', NULL, NULL, 'https://books.scielo.org/id/fnn82/cover/cover_thumbnail.jpeg', 244, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fnrkj', 'fnrkj', 'Radiodifusão e telecomunicações: o paradoxo da desvinculação normativa no Brasil', NULL, '["Chalini Torquato Gonçalves de Barros"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro se dedica a analisar os fatores que permeavam as circunstâncias definidoras do modelo brasileiro de TV digital que foi implementado em 2007. Naquele período ficava evidente a magnitude da influência política que o empresariado da radiodifusão exercia para pressionar por uma decisão favorável às suas expectativas e o quanto isso limava o debate histórico que estava sendo travado sob as novas possibilidades democráticas que a nova plataforma poderia oferecer.', '["digital television","broadcasting regulation","telecommunications regulation","deregulation","democratic media"]', '10.7476/9788523212261', '9788523207441', 'https://books.scielo.org/id/fnrkj', NULL, NULL, 'https://books.scielo.org/id/fnrkj/cover/cover_thumbnail.jpeg', 246, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fp86k', 'fp86k', 'Teorias e práticas em tecnologias educacionais', NULL, '["Robson Pequeno de Sousa","Carolina Cavalcanti Bezerra","Eliane de Moura Silva","Filomema Maria Gonçalves da Silva Mota"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Dividido em dois eixos, em seu primeiro momento, o livro volta-se para a Educação a Distância (EaD) como política pública para o desenvolvimento de ações metodológicas de ensino e aprendizagem. Em seu segundo momento, os textos apontam para a EaD como metodologia propícia à formação continuada de professores e gestores das escolas públicas e privadas, devido a acessibilidade à Educação propiciada pelas tecnologias da informação e comunicação. Tais temáticas poderão ser facilmente identificadas nos oito artigos que trazem tanto trabalhos de cunho qualitativo quanto quantitativos, voltados para a melhoria e aperfeiçoamento das práticas docentes dos professores.', '["distance education","educational technology","continuing teacher education","school management training","information and communication technologies","teaching practice","public education","education policy"]', '10.7476/9788578793265', '9788578793265', 'https://books.scielo.org/id/fp86k', 'https://books.scielo.org/id/fp86k/pdf/sousa-9788578793265.pdf', NULL, 'https://books.scielo.org/id/fp86k/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fp8hr', 'fp8hr', 'Desmídias do Brasil: catálogo taxonômico e distribuição', 'catálogo taxonômico e distribuição', '["Geraldo José Peixoto Ramos","Carlos Eduardo de Mattos Bicudo","Carlos Wallace do Nascimento Moura"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'A obra encanta pelo seu formato, ao incluir lindas fotos sobre os diferentes ambientes em terra brasilis, nos quais podemos encontras desmídias, e pela apresentação de várias ilustrações e imagens que traduzem a beleza das formas que esse grupo de algas apresenta. Mais que encanto, a presente obra representa um necessário aporte sobre a taxonomia de algas no Brasil, ao resgatar o histórico sobre os estudos das desmídias no país, sua distribuição geográfica e a lista de táxons com a devida atualização taxonômica e nomeclatural.', '["desmids","taxonomy","geographic distribution","taxonomic catalogue","nomenclature","freshwater algae"]', '10.7476/9788555921605', '9786589524700', 'https://books.scielo.org/id/fp8hr', NULL, NULL, 'https://books.scielo.org/id/fp8hr/cover/cover_thumbnail.jpeg', 423, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fphn6', 'fphn6', 'Teoria da Reforma Sanitária: diálogos críticos', NULL, '["Sônia Fleury"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea de textos organizada por Sonia Fleury retoma o debate sobre a Reforma Sanitária quando o Sistema Único de Saúde (SUS) completa 30 anos. Teoria da Reforma Sanitária - diálogos crí­ticos cumpre sua proposta: provoca a discussão e busca entender os caminhos trilhados a partir da conquista da incorporação do direito universal à saúde na Constituição de 1988, sem que tenha havido a necessária radicalização da democracia. Num esforço de superar a fragmentação da produção na área da saúde coletiva, autores de formações diversas foram convidados ao debate. Estão ali artigos que falam por si mesmos e expõem diversidade e controvérsias. "A indagação sobre a sustentabilidade e resiliência do projeto da Reforma Sanitária Brasileira em conjuntura tão adversa, assim como sobre as possibilidades de criação de consensos mí­nimos para a articular uma nova coalização reformista, não estão ausentes dos textos desta coletâne", afirma Sonia Fleury, na apresentação. "No entanto, temos certeza de que a reorganização das forças de sustentação de um projeto universal e radicalmente democrático é a tarefa histórica que se coloca neste momento", conclui. O livro traz artigos da organizadora Sonia Fleury, doutora em ciência política pelo Instituto Universitário de Pesquisas do Rio de Janeiro; do doutor em saúde pública professor e titular em polí­tica de saúde do Instituto de Saúde Coletiva da Universidade Federal da Bahia (Ufba), Jairnilson Paim; do doutor em serviço social e professor da Escola Politécnica de Saúde Joaquim Venâncio (EPSJV/Fiocruz) André Vianna Dantas; do doutor em ciência polí­tica da Universidade Federal de Minas Gerais (UFMG) Ronaldo Teodoro; da doutora em Políticas Sociais e Comunitárias pela Universidade Autônoma de Barcelona (Igop/UAB), Maria Gabriela Monteiro; e do mestre em Saúde Pública pela Universidade de São Paulo (USP) Thiago Henrique dos Santos Silva.', '["health care reform","Brazilian health system","health democracy","collective health","health policy","reform coalitions","Brazilian Constitution of 1988"]', '10.7476/9786557080566', '9788575415603', 'https://books.scielo.org/id/fphn6', NULL, NULL, 'https://books.scielo.org/id/fphn6/cover/cover_thumbnail.jpeg', 336, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fpvqr', 'fpvqr', 'Destino, humilhação e direito', NULL, '["Antonio Sá da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, o autor investiga se ainda é possível atribuir um sentido ao Direito no contexto do pensamento jurídico contemporâneo, compreendendo-o como uma das invenções ocidentais destinadas a mitigar o sofrimento humano diante da fragilidade da vida e da fortuna. Resultado de uma tese de doutorado desenvolvida na Universidade de Coimbra e apoiada pela Fapesb, a obra dialoga com a filosofia prática, a teoria do direito e a literatura, mobilizando fontes pouco canônicas da oralidade sertaneja brasileira. Ao confrontar tradições greco-romanas, teorias jurídicas atuais e o testemunho poético do sertão, o livro questiona a centralidade do Direito como projeto civilizacional, sem diluí-lo na experiência literária. Trata-se de uma reflexão original sobre direito, cultura e humanidade, dirigida a juristas, estudiosos da literatura e leitores interessados nas fronteiras entre essas áreas.', '["meaning of law","legal theory","human suffering","fragility of life","fate","humiliation","Brazilian sertão","practical philosophy","law and literature"]', '10.7476/9786556309521', '9786556308579', 'https://books.scielo.org/id/fpvqr', 'https://books.scielo.org/id/fpvqr/pdf/silva-9786556309521.pdf', NULL, 'https://books.scielo.org/id/fpvqr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fqrmr', 'fqrmr', 'Métodos de alfabetização no Brasil: uma história concisa', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"Aqui estão reunidos sete artigos publicados de 1998 a 2018. Tratam da história (concisa) da alfabetização no Brasil, suas circunstâncias e seus métodos. […] Maria do Rosario Mortatti dá a saber os estreitos vínculos entre os modelos pedagógicos para o ensino da leitura e da escrita, propugnados por diversos setores sociais direta ou indiretamente ligados à instrução, e os diferentes projetos de nação. A coletânea […] é excelente estímulo à pesquisa acadêmica tanto sobre o passado quanto sobre o presente do ensino do ler e escrever, do mesmo modo que é um exemplo de clareza, precisão e elegância; portanto, um convite a muitos. Professores ou futuros professores do ensino inicial ganharão ao lê-la, tanto quanto mestrandos, doutorandos e pesquisadores que se vêm debruçando sobre a história da escolarização primária e daquele ensino inicial, que foi denominado usualmente de ‘alfabetização’ […]. Ganhariam, também, com a sua leitura os atuais dirigentes do ensino; os ‘policy makers’, os que elaboram políticas, os que definem as diretrizes para educação neste país.” MIRIAN JORGE WARDE', '["literacy education","reading and writing instruction","teaching model","elementary school","early childhood education","education policy","history of schooling"]', '10.7476/9788595463394', '9788595463394', 'https://books.scielo.org/id/fqrmr', 'https://books.scielo.org/id/fqrmr/pdf/mortatti-9788595463394.pdf', NULL, 'https://books.scielo.org/id/fqrmr/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fqykz', 'fqykz', 'Vértice do impensável: um estudo de narrativas em síndrome de Down', NULL, '["Ana Cristina Bohrer Gilbert"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Ana Cristina Bohrer Gilbert é psicoterapeuta e pesquisadora. Pós-Doutorado em Estudos Culturais no Programa Avançado de Cultura Contemporânea (PACC) da Universidade Federal do Rio de Janeiro (UFRJ), com projeto sobre Festivais de Cinema sobre Deficiência. Pesquisadora colaboradora no grupo de pesquisa Centro de Genética Médica José Carlos Cabral de Almeida no Instituto Fernandes Figueira/Fundação Oswaldo Cruz. Possui Mestrado (2005) e Doutorado (2010) em Saúde da Criança e da Mulher pelo Instituto Fernandes Figueira/Fundação Oswaldo Cruz; Bacharelado e Licenciatura em Psicologia e Formação de Psicólogo pela Universidade Santa Úrsula (1987). Interesses de pesquisa: estudos sobre saúde, mídia e cultura, estudos sobre ciência, complexo cultural (a partir de uma perspectiva da Psicologia Analítica de Carl G. Jung), festivais de cinema sobre deficiência, narrativas, imagens, corpo e deficiência, etnografia, análise semiótica, síndrome de Down, identidade genética, tecnologias do self.', '["Down syndrome","narrative","disability","disability and the body","genetic identity","technologies of the self","media and culture","Jungian psychology","cultural complex"]', '10.7476/9788575415726', '9788575415726', 'https://books.scielo.org/id/fqykz', 'https://books.scielo.org/id/fqykz/pdf/gilbert-9788575415726.pdf', NULL, 'https://books.scielo.org/id/fqykz/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fr23p', 'fr23p', 'La estandarización ortográfica del quichua ecuatoriano. Consideraciones históricas, dialectológicas y sociolingüísticas', NULL, '["Luis Montaluisa Chasiquiza"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este libro arranca con un estudio de términos, principalmente topónimos, de las lenguas pasto, cara, panzaleo, puruhá, cañar, y palta que son sustratos de la lengua quichua. Propone la discusión acerca de las teorías sobre el origen de la familia quechua/quichua. Muestra el mosaico de las variaciones dialectales actuales, a nivel fonético-fonológico y morfológico, en tanto que en los niveles sintáctico y semántico las diferentes hablas son más regulares.', '["orthographic standardization","dialect variation","place names","language contact","sociolinguistics of writing","phonological variation","morphological variation"]', '10.7476/9789978104965', '9789978104965', 'https://books.scielo.org/id/fr23p', 'https://books.scielo.org/id/fr23p/pdf/montaluisa-9789978104965.pdf', NULL, 'https://books.scielo.org/id/fr23p/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fs', 'fs', 'O fazer-dizer do corpo: dança e performatividade', NULL, '["Jussara Sobreira Setenta"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Importante contribuição para a construção do entendimento da dança como área do conhecimento. Resultado de estudos e pesquisas de alguém que vem, de muito, instigada com a busca de uma compreensão da realidade a partir de formas contemporâneas de percepção e visão de mundo onde a arte, e portanto, a dança, emerge como um sistema de alta complexidade.', '["dance","performativity","body","contemporary perceptions","dance theory","embodiment"]', '10.7476/9788523211967', '9788523209179', 'https://books.scielo.org/id/fs', 'https://books.scielo.org/id/fs/pdf/setenta-9788523211967.pdf', NULL, 'https://books.scielo.org/id/fs/cover/cover_thumbnail.jpeg', NULL, 48, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fs5f7', 'fs5f7', 'Revisão crítica das canções para a voz e piano de Heitor Villa-Lobos: publicadas pela Editora Max Eschig', NULL, '["Nahim Marun"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'exemplo admirável de amor à arte e à musicologia.', '["Heitor Villa-Lobos","songs for voice and piano","critical edition","music editing","Brazilian song","musicology"]', '10.7476/9788579831102', '9788579831102', 'https://books.scielo.org/id/fs5f7', 'https://books.scielo.org/id/fs5f7/pdf/marun-9788579831102.pdf', NULL, 'https://books.scielo.org/id/fs5f7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fs5j4', 'fs5j4', 'Pentatominae do Sul de Santa Catarina', NULL, '["Thereza de Almeida Garbelotto","Luiz Alexandre Campos"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'other', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Voltar ao Sumário ApresentaçãoNão é exagero dizer que os insetos governam a Terra, a sua diversidade e abundância desafiam a imaginação de qualquer um.Os insetos habitam quase todos os habitats concebíveis no meio terrestre e na água doce e, de forma menos comum, até zonas de rebentação, entremarés e a superfície dos oceanos.Eles também são encontrados em locais muito improváveis como poços e lagos de óleo, nascentes sulfúricas, riachos glaciais e lagoas marinhas (Brusca & Brusca 2007).As estimativas mais recentes apontam que existe quase um milhão de espécies de insetos descritas no mundo (Grimald & Engel 2005).Essa diversidade de insetos influencia a dinâmica dos ecossistemas por intermédio de numerosos mecanismos, tais como, decomposição da serrapilheira, polinização, supressão do crescimento de plantas e servindo como presa a carnívoros (Thomazini & Thomazini 2000).Alguns grupos de insetos também são indicadores para monitoramento de mudanças ambientais.Os percevejos da família Pentatomidae são um desses grupos na Floresta Atlântica Brasileira, onde respondem principalmente à diversidade química e taxonômica das plantas, com acréscimo de diversidade quando os impactos sobre a vegetação são baixos a moderados e com diminuição de diversidade quando os distúrbios são altos (Brown Jr. 1997).Este guia ilustrado pretende apresentar a diversidade do grupo de percevejos com maior número de espécies no sul do Estado de Santa Catarina, a subfamília Pentatominae.Também se destina a estudantes e pesquisadores que atuam (ou gostariam de atuar) com Pentatomidae, especialmente os pentatomíneos, como um auxiliar na identificação dos insetos em laboratório e guia de identificação em campo.O guia possui uma seção introdutória com uma breve apresentação sobre a Mata Atlântica e a região sul catarinense, ao mesmo tempo o limite sul da floresta ombrófila densa e região de coleta das espécies aqui incluídas.Na mesma seção é caracterizado o grupo de percevejos da subfamília Pentatominae, com suas principais características morfológicas e taxonômicas.Em seguida são apresentadas as 52 espécies de Pentatominae registradas no sul catarinense, incluindo fotos, diagnoses rápidas, principais referências sobre as espécies e informações de plantas hospedeiras quando disponíveis em literatura.', '["Pentatominae","Pentatomidae","insect identification","species identification key","southern Santa Catarina","Atlantic Forest","ombrophilous forest","insect diversity","plant-insect interactions","environmental disturbance","predatory insects","insect parasitoids"]', '10.7476/9788598203089', '9788598203089', 'https://books.scielo.org/id/fs5j4', 'https://books.scielo.org/id/fs5j4/pdf/garbelotto-9788598203089.pdf', NULL, 'https://books.scielo.org/id/fs5j4/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fsdsy', 'fsdsy', 'Monteiro Lobato e seis personagens em busca da nação', NULL, '["Elisângela da Silva Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, Elisângela da Silva Santos investiga qual seria o “”pro­jeto”” de nação – compreendida como projeto político social – na obra destinada ao público infantil de Monteiro Lobato, conhecida também como uma literatura pedagógica. A autora acredita na pos­sibilidade de Lobato ser visto como integrante da galeria de nossos pensadores sociais, pois em seu gênero literário infantil ressoa uma visão de país, um diagnóstico e um projeto de futuro para o Brasil. Nesse sentido, a autora discute a possibilidade de tomar a litera­tura lobatiana como elemento de compreensão da realidade social brasileira dos anos 1920 e 1930. Assim, Elisângela Santos procura ver na obra de Lobato uma crítica à sociedade em que vivia o escritor que, além de estar preocupado com questões estéticas e linguísticas de seu tempo, sempre formulou críticas à nossa “”parasitia intelectual””, aos intelectuais e à elite que, segundo ele, assistia de braços cruza­dos aos diversos problemas de ordem social política e econômica, sem propor alternativas de mudanças.', '["Monteiro Lobato","children''s literature","pedagogical literature","nation-building","national projects","Brazilian intellectuals","social criticism","elites"]', '10.7476/9786557145326', '9786557145326', 'https://books.scielo.org/id/fsdsy', 'https://books.scielo.org/id/fsdsy/pdf/santos-9786557145326.pdf', NULL, 'https://books.scielo.org/id/fsdsy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fstch', 'fstch', 'Ruth Landes e A cidade das mulheres: uma releitura da antropologia do candomblé', NULL, '["Jamie Lee Andreson"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Por meio de fontes primárias, como cartas pessoais, fotos e manuscritos encontrados em arquivos nos EUA e no Brasil, este livro trata da experiência de campo e dos debates relacionados à antropóloga norte-americana Ruth Landes nos candomblés da Bahia entre 1938 a 1939. É uma reflexão feminista na história da antropologia sobre as metodologias e os desafios enfrentados pela antropóloga no campo dos estudos afro- americanos. A obra relata o relacionamento entre Ruth e o etnógrafo baiano Edison Carneiro, bem como suas dinâmicas devido às circunstâncias históricas e às políticas de raça e gênero da época. Além disso, oferece uma análise das fontes primárias que retratam mulheres importantes na história do candomblé soteropolitano para uma releitura do conceito do matriarcado na antropologia.', '["Ruth Landes","Candomblé","Bahia","feminist anthropology","ethnographic fieldwork","race and gender","matriarchy","Afro-Brazilian religions","history of anthropology"]', '10.7476/9786556304014', '9786556304014', 'https://books.scielo.org/id/fstch', 'https://books.scielo.org/id/fstch/pdf/andreson-9786556304014.pdf', NULL, 'https://books.scielo.org/id/fstch/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
