ions.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ftg2t', 'ftg2t', 'O espaço da prisão e suas práticas educativas: enfoques e perspectivas contemporâneas', NULL, '["Arlindo da Silva Lourenço","Elenice Maria Cammarosano Onofre"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O espaço da prisão e suas práticas educativas: enfoques e perspectivas contemporâneas examina questões relativas à educação em espaços de privação de liberdade. Trata-se de obra que apresenta os efeitos do aprisionamento e o embate entre o discurso jurídico - penal, cultura prisional e cultura escolar -, analisa práticas educativas que ocorrem no interior da prisão, especificamente as referentes à educação e ao trabalho, evidencia pistas para o processo de reinserção social pela educação escolar e enfatiza a relevância de políticas locais e nacionais de educação de jovens e adultos em privação de liberdade.', '["prison education","incarceration","prison space","prison culture","school culture","prison labor","social reintegration","youth and adult education"]', '10.7476/9788576002963', '9788576002963', 'https://books.scielo.org/id/ftg2t', 'https://books.scielo.org/id/ftg2t/pdf/lourenco-9788576002963.pdf', NULL, 'https://books.scielo.org/id/ftg2t/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fv3c6', 'fv3c6', 'A Gripe Espanhola na Bahia: saúde, política e medicina em tempos de epidemia', NULL, '["Christiane Maria Cruz de Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A forma como políticos, médicos, farmacêuticos e a população da Bahia se posicionaram diante da desconhecida doença que vitimou cerca de 30 milhões de pessoas nos anos de 1918/19, estrutura o livro. Nele são analisados os diversos aspectos relacionados à gripe que matou o presidente Rodrigues Alves, em janeiro de 1919, antes mesmo de tomar posse. A autora produziu “um belo e inédito mosaico”, tomando por base fontes documentais as mais diversas para fundamentar a pesquisa sobre o enfrentamento do vírus influenza. Gilberto Hochman, pesquisador da COC/Fiocruz e autor do prefácio do livro, exalta “o delicado artesanato” na produção da narrativa que provoca o interesse, a surpresa e até mesmo a compaixão pelos que sofrem nos tempos de epidemia. A obra permite compreender especificidades locais da chamada República Velha na Bahia, além de possibilitar estabelecer comparações da epidemia em perspectiva global, tornando-se importante fonte de pesquisa, ainda mais neste atual momento em que a pandemia pelo vírus da influenza A (H1N1) começa a perder força no hemisfério sul, mas persiste a possibilidade de futura ocorrência de novo repique.', '["1918 influenza pandemic","Bahia","health politics","physicians","pharmacists","outbreak response","First Brazilian Republic","influenza A (H1N1) pandemic","history of medicine"]', '10.7476/9788575415382', '9788575415382', 'https://books.scielo.org/id/fv3c6', 'https://books.scielo.org/id/fv3c6/pdf/souza-9788575415382.pdf', NULL, 'https://books.scielo.org/id/fv3c6/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fwmf8', 'fwmf8', 'O guia intérprete e a inclusão da pessoa com surdocegueira', NULL, '["Wolney Gomes Almeida"]', 'Portuguese National Funding Agency for Science, Research and Technology (RCAAP Project by FCT)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro apresenta a surdocegueira no contexto das deficiências e a grande necessidade de formação profissional daqueles que se configuram como principais mediadores da inclusão socioeducacional das pessoas surdocegas, a saber, o Guia-intérprete. O plano de fundo que norteia as discussões nesta obra compreende a diferença enquanto posicionamento político e a demarcação da legitimidade do outro de forma epistemológica e numa perspectiva sociocultural.', '["deafblindness","sign language interpreters","interpreter training","social inclusion","socio-educational inclusion","disability","difference","sociocultural perspective"]', '10.7476/9788574555270', '9788574555270', 'https://books.scielo.org/id/fwmf8', 'https://books.scielo.org/id/fwmf8/pdf/almeida-9788574555270.pdf', NULL, 'https://books.scielo.org/id/fwmf8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fx5jk', 'fx5jk', 'Judicialização de Políticas Públicas no Brasil', NULL, '["Vanessa Elias de Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Livro de fundamental importância em meio aos debates mais atuais do cenário sociopolítico nacional, Judicialização de Políticas Públicas no Brasil levanta debates e contribuições para “a compreensão dos processos pelos quais nosso sistema de justiça tornou-se um protagonista da política e das políticas, bem como de seus impactos sobre uma gama variada de direitos individuais e coletivos”, afirma a professora titular de Ciência Política da Universidade de São Paulo (USP), Marta Arretche. A obra reúne 12 artigos de juristas e especialistas nos campos das ciências sociais e política e do direito, dialogando sobre temas como as bases institucionais dos processos de judicialização das políticas públicas no país, além de casos e desafios ligados à judicialização, englobando o direito à saúde e à moradia, questões de política habitacional e preservação ambiental, renda, assistência social, aborto, educação, igualdade de gênero e união homoafetiva. No time de renomados pesquisadores que compõem os estudos apresentados no livro estão Conrado Hübner Mendes, Fabiana Luci de Oliveira, Rogério Arantes, Luciana Gross Cunha e a organizadora, Vanessa Elias de Oliveira, doutora em Ciência Política pela USP e professora do Programa de Pós-Graduação em Políticas Públicas da Universidade Federal do ABC (PGPP/UFABC). Para o professor da Escola de Direito de São Paulo da Fundação Getulio Vargas, Oscar Vilhena Vieira, a coletânea “apresenta uma contribuição fundamental para melhor compreender o papel das agências de aplicação, impulsionadas por uma constituição de natureza transformadora, na determinação das políticas públicas no campo social”.', '["judicialization of public policy","judiciary and politics","public policy implementation","right to health","right to housing","housing policy","environmental protection","income policy","social assistance","abortion","education policy","gender equality"]', '10.7476/9786557080733', '9788575416273', 'https://books.scielo.org/id/fx5jk', NULL, NULL, 'https://books.scielo.org/id/fx5jk/cover/cover_thumbnail.jpeg', 332, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fx9hn', 'fx9hn', 'Análise diagnóstica da política nacional de saúde para redução de acidentes e violências', NULL, '["Minayo, Maria Cecília de Souza","Suely Ferreira Deslandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra é a primeira avaliação técnica da Política Nacional de Saúde para Redução de Acidentes e Violências, desde que ela foi criada, em 2001, quando a questão da violência entrou oficialmente na pauta da saúde pública do país. O trabalho teve como foco os atendimentos pré-hospitalares, de emergência, hospitalares e de reabilitação em cinco capitais: Curitiba, Manaus, Recife, Rio de Janeiro e Brasília, que estão entre as mais violentas do país. A reabilitação foi o aspecto mais fraco em todas as cidades estudadas: apesar de haver serviços bons, em geral, eles são insuficientes para atender à demanda da população.', '["violence prevention","injury prevention","prehospital care","emergency care","hospital care","rehabilitation services","health policy evaluation","urban violence","health care demand"]', '10.7476/9788575415412', '9788575415412', 'https://books.scielo.org/id/fx9hn', 'https://books.scielo.org/id/fx9hn/pdf/minayo-9788575415412.pdf', NULL, 'https://books.scielo.org/id/fx9hn/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fyks3', 'fyks3', 'Antropologia da comunicação de massa', NULL, '["Isabel Siqueira Travancas","Sílvia Garcia Nogueira"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'foram apresentados seis trabalhos sobre figuras públicas e o papel da mídia na sua construção, telenovelas, publicidade, imprensa e música.Foi uma tentativa de continuar levando o tema da comunicação de massa para os encontros da Associação Brasileira de Antropologia (ABA).Em 2004, foi organizado pelos professores Peter Fry e Esther Hamburguer o Fórum de Pesquisa "Mercado, consumo e mídia: disputas por representações" na 24ª RBA, realizada em Recife, Pernambuco, em junho.Neste encontro, o foco não foi apenas a questão da comunicação de massa, mas sua perspectiva de consumo e mercado.Dos 24 trabalhos apresentados, as principais temáticas foram: consumo, circulação de mercadorias, propaganda, moda, televisão e representações da mídia, em especial dos jornais.No 25º encontro da ABA, em 2006, não houve nenhum Grupo de Trabalho ou Seminário sobre comunicação de massa sob o olhar antropológico.Isso veio a acontecer na reunião de 2008, em Porto Seguro, Bahia, quando Isabel Travancas e Nara Magalhães coordenaram o Grupo de Trabalho "Diferenças e desigualdades na mídia: um olhar antropológico".Compuseram o GT 14 trabalhos e cinco painéis distribuídos em três sessões cujos temas foram: a representação da diferença na televisão, uma antropologia da mídia e imprensa, televisão, violência e consumo.A televisão foi, sem dúvida, o tema preponderante dos trabalhos e abordada de diversas formas.Estudos empíricos e teóricos, análises de programa e de receptores demonstrando que seu lugar vem crescendo também no contexto acadêmico e em particular no campo da antropologia.Belém, no Pará, foi a cidade da 27ª Reunião Brasileira de Antropologia, realizada de 1 a 4 de agosto de 2010.Nesta reunião, Isabel Travancas com o antropólogo português e pesquisador do Instituto Universitário de Lisboa (ISCTE) Filipe Reis coordenaram o Grupo de Trabalho "Antropologia e meios de comunicação", Antropologia do Mercosul (RAM) de 2011, sobre a qual falaremos em seguida.Um detalhe importante nesta tentativa de mapear a presença da discussão sobre os meios de comunicação no campo da Antropologia corresponde às transformações sofridas pelos títulos dos GTs.Eles começam de forma mais aberta e depois passam a unir os dois campos -Antropologia e Comunicação -, até que, no último congresso, já se postulou uma Antropologia da Comunicação de Massa.Este título procura precisar o objetivo e o enfoque das pesquisas.Além destes encontros nacionais bienais da ABA e dos encontros regionais, um congresso de Antropologia da América Latina vem crescendo a cada evento.Trata-se da Reunião de Antropologia do MERCOSUL -RAM -iniciada em 1995.Ela vem sendo realizada de dois em dois anos, na Argentina, no Brasil e no Uruguai.', '["mass communication","media anthropology","television","public figures","media representation","consumption","advertising","fashion","newspapers","violence","representation of difference","Mercosur"]', '10.7476/9788578793326', '9788578793326', 'https://books.scielo.org/id/fyks3', 'https://books.scielo.org/id/fyks3/pdf/travancas-9788578793326.pdf', NULL, 'https://books.scielo.org/id/fyks3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fyvfv', 'fyvfv', 'Cooperativismo e coletivização no campo: questões sobre a prática da Igreja Popular no Brasil', NULL, '["Neide Esterci"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Acompanhando criticamente a trajetória da Igreja Popular, muitos estudos têm sido dedicados à análise do desempenho político deste setor da Igreja Católica no Brasil dos anos recentes. A contribuição dos autores reunidos neste número dos Cadernos do ISER não se baseia em análises de documentos e declarações - opções que se tem mostrado, sem dúvida, muito produtiva - mas na reflexão sobre um conjunto de práticas, complementação percebida cada vez mais claramente, como indispensável neste campo de discussões.', '["popular church","Catholic Church","rural cooperatives","collectivization","rural development","Brazil"]', '10.7476/9788599662625', '9788599662625', 'https://books.scielo.org/id/fyvfv', 'https://books.scielo.org/id/fyvfv/pdf/esterci-9788599662625.pdf', NULL, 'https://books.scielo.org/id/fyvfv/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-fyyqb', 'fyyqb', 'Vigilância alimentar e nutricional para a saúde Indígena', NULL, '["Denise Cavalcante de Barros","Denise Oliveira e Silva","Sílvia Ângela Gugelmin"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A importância da diversidade étnica brasileira e seus desafios são aspectos fundamentais para os profissionais que atuam no campo da saúde indígena. É nesse contexto que se insere o primeiro volume desta publicação. Trata-se de contribuição relevante e inédita ao debate e à consolidação da vigilância alimentar e nutricional no âmbito da saúde indígena. Povos indígenas e o processo saúde-doença; situações e determinantes de saúde e nutrição da população brasileira; sociodiversidade, alimentação e nutrição indígena; políticas públicas e intervenções nutricionais: eis alguns dos temas abordados nesta coletânea, valioso instrumento de reflexão também sobre as potencialidades do Sistema de Vigilância Alimentar e Nutricional (Sisvan) para a prevenção de agravos nutricionais e a promoção da saúde. Já o segundo volume discute a avaliação nutricional de comunidades e indivíduos, em todas as faixas etárias e mesmo na gestação, e destaca as duas faces de um problema: os déficits de crescimento ou subnutrição, de um lado, e o sobrepeso e a obesidade, de outro. Oferece ao leitor as bases para a realização do diagnóstico nutricional na atenção básica; aprofunda o estudo de técnicas e procedimentos usados nas medições antropométricas; destaca como a informação pode orientar ações, reorganizar serviços e melhorar a assistência; e explica as etapas de organização do fluxo de dados, desde a construção até o uso para o planejamento de intervenções, passando pela análise (com ferramentas estatísticas e epidemiológicas) e pela divulgação de resultados.', '["food and nutrition surveillance","Indigenous health","SISVAN","ethnic diversity","public health policy","nutritional assessment","anthropometry","malnutrition","overweight and obesity","health promotion"]', '10.7476/9788575415870', '9788575415870', 'https://books.scielo.org/id/fyyqb', 'https://books.scielo.org/id/fyyqb/pdf/barros-9788575415870.pdf', NULL, 'https://books.scielo.org/id/fyyqb/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
