 excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g2wt4', 'g2wt4', 'A revolução Alemã [1918-1923]', NULL, '["Isabel Maria Loureiro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este volume da coleção Revoluções do Século XX apresenta um balanço histórico da Revolução Alemã, de 1918 a 1923, a primeira revolução numa sociedade industrial desenvolvida. Depois da Revolução Russa em 1917, pela primeira vez pareciam possíveis as perspectivas de uma vitória do socialismo no Ocidente. Mas contrariamente ao que ocorreu na Rússia, a Revolução Alemã fracassou, e a vitória das forças conservadoras acabou por pavimentar o caminho para a queda da República e a ascensão do nazismo.', '["Weimar Republic","collapse of the Weimar Republic","rise of Nazism","socialist revolution","industrial society","conservative forces","German history","20th-century revolutions"]', '10.7476/9788539303403', '9788571396272', 'https://books.scielo.org/id/g2wt4', NULL, NULL, 'https://books.scielo.org/id/g2wt4/cover/cover_thumbnail.jpeg', 184, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g32p7', 'g32p7', 'Violência, indisciplina e educação', NULL, '["Leoni Maria Padilha Henning","Maria Luiza Macedo Abbud"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] (FINALISTA DO PRÊMIO JABUTI 2011) O tema violência e indisciplina tem sido recorrente nas referências aos problemas atuais que a escola vem enfrentando. Sua discussão apresenta-se, em alguns espaços, de forma banalizada, em outros de forma sensacionalista. O problema não se restringe ao âmbito escolar, no entanto afeta diretamente este espaço, considerado privilegiado a partir da modernidade como responsável pela formação de novas gerações. Orientadas por tais percepções, as organizadoras intentaram ampliar a compreensão da questão a partir da apresentação dos múltiplos olhares sobre o tema, exigidos pela sua complexidade.', '["school violence","student misbehavior","student discipline","social construction of violence"]', '10.7476/9788572166515', '9788572166515', 'https://books.scielo.org/id/g32p7', NULL, NULL, 'https://books.scielo.org/id/g32p7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g3p7n', 'g3p7n', 'Schopenhauer e os conhecimentos intuitivo e abstrato: uma teoria sobre as representações empíricas e abstratas', NULL, '["Eduardo Ramos Coimbra de Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro tem como objetivo principal investigar a teoria do conhecimento desenvolvida por Arthur Schopenhauer no Livro I de O mundo como vontade e como representação. A partir disto, procura-se analisar e examinar como o pensador organiza e explica a possibilidade do conhecimento da realidade fenomênica, ou seja, os modos de conhecimento intuitivo e abstrato, seus objetos próprios, isto é, as representações intuitiva e abstrata, além das faculdades de conhecimento responsáveis por cada uma destas. A investigação tentará delimitar os princípios que tornam o mundo como representação compreensível, formando, por fim, uma teoria sistemática do conhecimento.', '["Arthur Schopenhauer","intuition","abstract knowledge","abstract representation","aesthetic knowledge","pessimism","Immanuel Kant","reason","thing-in-itself","epistemology","idealism","German idealism"]', '10.7476/9788579836879', '9788579836879', 'https://books.scielo.org/id/g3p7n', 'https://books.scielo.org/id/g3p7n/pdf/souza-9788579836879.pdf', NULL, 'https://books.scielo.org/id/g3p7n/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g5q2h', 'g5q2h', 'Ensino de ciências e matemática, I : temas sobre a formação de professores', NULL, '["Roberto Nardi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea de textos apresentados no Programa de Pós-Graduação em Educação para a Ciência, sediado na Faculdade de Ciências da UNESP, na área de ensino de Ciências e Matemática. O núcleo de pesquisa do Programa concentra-se em estudos sobre a ciência, a educação científica e nas relações entre o saber científico e seu ensino. Assim, incentiva a reflexão sobre os processos envolvidos na construção dos conhecimentos científicos e tecnológicos, além de contribuir para a produção de um corpo de conhecimentos filosóficos, científicos e pedagógicos destinados à formação de professores e outros profissionais da área', '["science education","mathematics education","teacher professional development","scientific knowledge construction","scientific and technological knowledge","philosophy of science"]', '10.7476/9788579830044', '9788579830044', 'https://books.scielo.org/id/g5q2h', 'https://books.scielo.org/id/g5q2h/pdf/nardi-9788579830044.pdf', NULL, 'https://books.scielo.org/id/g5q2h/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g6cvb', 'g6cvb', 'Saúde e democracia', 'história e perspectivas do SUS', '["Nísia Trindade Lima","Sílvia Gerschman","Flávio Coelho Edler","Julio Manoel Suárez"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Trata-se de um dos mais abrangentes, profundos e qualificados exercícios analíticos sobre o sistema de saúde brasileiro desenvolvido nos últimos anos. O livro inclui artigos de diferentes autores sobre as diversas fases do SUS, abordando temas como situação de saúde, financiamento do SUS, C&T em saúde, os trabalhadores da saúde no país, a descentralização, os conceitos de saúde, a universalização versus a focalização, o público e o privado, o modelo de atenção à saúde praticado e a estratégia da saúde da família.', '["Unified Health System (SUS)","health care financing","health research and development","healthcare workers","decentralization","concept of health","universal health care","models of care","public and private health services","Family Health Strategy"]', '10.7476/9788575413678', '9788575410585', 'https://books.scielo.org/id/g6cvb', 'https://books.scielo.org/id/g6cvb/pdf/lima-9788575413678.pdf', NULL, 'https://books.scielo.org/id/g6cvb/cover/cover_thumbnail.jpeg', NULL, 86, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g7nvz', 'g7nvz', 'Tempo presente: do MDB a FHC', NULL, '["Fábio Wanderley Reis"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'other', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este volume reúne uma seleção de artigos aparecidos em jornais do país ao longo de mais de vinte anos. A ideia de publicá-lo me ocorreu quando me dei conta do possível interesse, para o leitor, de ter num só volume artigos motivados por aspectos da cambiante conjuntura em que passamos, no plano mundial, da Guerra Fria ao colapso do socialismo e à afirmação da globalização e, no plano nacional, do autoritarismo do regime de 1964 às vacilações do processo de abertura e transição política e ao pleno funcionamento da democracia – que talvez venha mesmo a resultar, com as eleições de 2002, no acesso de uma liderança de esquerda ao poder presidencial.[...][trecho retirado da nota do autor]', '["Brazilian politics","Fernando Henrique Cardoso","political transition","democratization","Cold War","collapse of socialism","globalization","2002 elections"]', '10.7476/9788599662809', '9788599662809', 'https://books.scielo.org/id/g7nvz', 'https://books.scielo.org/id/g7nvz/pdf/reis-9788599662809.pdf', NULL, 'https://books.scielo.org/id/g7nvz/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g7rjr', 'g7rjr', 'Audiovisual independente: política de fomento e organização das produtoras no Brasil', NULL, '["Kátia Santos de Morais"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra vem preencher uma carência de reflexões e publicações no país sobre o tema com uma metodologia rigorosa que dá conta da complexidade desta arte como fenômeno social, de suas especificidades e de sua dinâmica, não apenas na produção, mas também na circulação e fruição. A política audiovisual e a produção independente no Brasil estão aqui atualizadas, incluindo a participação da televisão como janela de exibição estratégica para o conteúdo nacional e como parte da política audiovisual.', '["audiovisual policy","film producers","producer associations","audiovisual consumption","Brazil"]', '10.7476/9786588211298', '9786588211212', 'https://books.scielo.org/id/g7rjr', 'https://books.scielo.org/id/g7rjr/pdf/morais-9786588211298.pdf', 'https://books.scielo.org/id/g7rjr/epub/morais-9786588211298.epub', 'https://books.scielo.org/id/g7rjr/cover/cover_thumbnail.jpeg', 310, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g8qcy', 'g8qcy', 'Aprendizados ao longo da vida: sujeitos, políticas e processos educativos', NULL, '["Paiva, Jane"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O direito à educação como pilar da cidadania e da dignidade humana permeia essa obra, que reúne a produção dos pesquisadores no campo da Educação de Jovens e Adultos (EJA), estimulando o intercâmbio necessário entre a academia e a sociedade. Os capítulos permitem uma reflexão sobre a situação dos sujeitos a quem se destina a EJA, indivíduos que, embora tenham seus direitos constitucionalmente assegurados, vivem ameaçados na prática social e política. Os autores abordam temas como as possibilidades de aprendizados oferecidas pelo Estado em espaços públicos; os aportes teórico-conceituais que analisam a cultura escrita do público-alvo da EJA; a inserção das questões relativas a gênero, sexualidade e envelhecimento, assim como aspectos específicos relacionados à formação de educadores, entre outros.', '["youth and adult education","right to education","citizenship","human dignity","education policy","written culture","gender","sexuality","aging","teacher professional development","lifelong learning"]', '10.7476/9786599036491', '9786599036491', 'https://books.scielo.org/id/g8qcy', 'https://books.scielo.org/id/g8qcy/pdf/paiva-9786599036491.pdf', NULL, 'https://books.scielo.org/id/g8qcy/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g947x', 'g947x', 'A ciência e seus impasses: debates e tendências em filosofia, ciências sociais e saúde', NULL, '["Vaitsman, Jeni","Girardi, Sábado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Coletânea que permite - da densidade téorica da primeira parte à possibilidade de reconstruir o real, na segunda - uma leitura da trajetória da ciência naquilo que esta tem recuperado de mais moderno em suas bases filosóficas/epistemológicas. Ainda que não se busque a unidade, ou não se a exponha como orientadora, isto não é criticável: afinal, o projeto pós-moderno vislumbra um horizonte sem o comprometimento das totalidades e das verdades absolutas. Ao abordar questões filosóficas complexas e debatê-las com investigações sobre problemas contemporâneos, concorre para que os conhecimentos da filosofia, das ciências sociais e da saúde se completem, ganhem especial significado e se enriqueçam mutuamente.', '["philosophy of science","epistemology","postmodernism","social sciences","health sciences","reconstruction of reality","philosophical foundations of science"]', '10.7476/9788575415078', '9788575415078', 'https://books.scielo.org/id/g947x', 'https://books.scielo.org/id/g947x/pdf/vaitsman-9788575415078.pdf', NULL, 'https://books.scielo.org/id/g947x/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-g9nrm', 'g9nrm', 'Planos de saúde e dominância financeira', NULL, '["José Antônio de Freitas Sestelo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Planos de saúde e dominância financeira é o resultado dos esforços para compreender mudanças na estrutura e dinâmica do setor privado assistencial no Brasil. O livro sintetiza um percurso árduo, que vincula a reverência e crítica aos conhecimentos prévios e uma ruptura, embasada teórica e empiricamente, com as explicações correntes sobre o mercado de planos e seguros de saúde. A obra apresenta um debate consistente sobre o mercado assistencial de saúde, a tributação, a dívida pública e as compensações sociais para a perda de renda e status pela destruição criativa do capitalismo.', '["health plans","private healthcare sector","health insurance market","health insurance taxation","public debt","financial dominance","social compensation","creative destruction","capitalism","Brazil"]', '10.7476/9788523220280', '9788523217549', 'https://books.scielo.org/id/g9nrm', NULL, NULL, 'https://books.scielo.org/id/g9nrm/cover/cover_thumbnail.jpeg', 397, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gbgpq', 'gbgpq', 'Catálogo Transfopress Brasil', 'Imprensa estrangeira publicada no Brasil', '["Stephanou, Maria","Luca, Tania Regina de","Guimarães, Valéria dos Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'O Catálogo Transfopress Brasil – imprensa estrangeira publicada no Brasil é um instrumento de pesquisa com uma extensa listagem de impressos periódicos alófonos que constam em acervos nacionais e estrangeiros. Os pesquisadores contarão com informações sistematizadas, organizadas por idioma, como títulos, locais e anos de publicação, além da referência da localização em acervos físicos e digitais, com detalhes acerca dos volumes disponíveis (quando possível). O cruzamento de dados entre local de publicação e idioma é particularmente importante, visto que a maioria dos catálogos não possui essas informações ou não lhes dão destaque. E é justamente o cruzamento destas duas entradas que confere interesse para o pesquisador da área. O Catálogo ainda oferece breves textos explicativos sobre a história dos grupos imigrantes que deram origem a estes impressos e observações gerais ou específicas acerca do corpus arrolado. Os jornais, revistas, almanaques e boletins aqui repertoriados são aqueles que sobreviveram e estão disponíveis para a consulta. Alguns passaram incólumes (ou quase) desde o século XIX, século da consolidação das nações quando a imprensa comercial atuou como um fator de integração de um mundo cujas referências iam se tornando cada vez mais compartilhadas, resultado da modernização tecnológica dos meios de transporte e de comunicação, fenômeno de proporções sem precedentes na história da humanidade.', '[]', '10.7476/9786559544943', '9786559544943', 'https://books.scielo.org/id/gbgpq', 'https://books.scielo.org/id/gbgpq/pdf/stephanou-9786559544943.pdf', 'https://books.scielo.org/id/gbgpq/epub/stephanou-9786559544943.epub', 'https://books.scielo.org/id/gbgpq/cover/cover_thumbnail.jpeg', 322, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gbgzc', 'gbgzc', 'Políticas públicas e pessoa com deficiência: direitos humanos, família e saúde', NULL, '["Isabel Lima","Isabela Rahal de Rezende Pinto","Silvia Pereira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro divide-se em quatro seções: a primeira é dedicada aos Direitos Humanos; a segunda apresenta uma revisão conceitual sobre deficiência e reabilitação; a terceira aborda a implementação de Políticas Públicas através da análise teórica e conceitual de experiências concretas; a quarta e última seção debate a acessibilidade, analisando a dimensão dos serviços de saúde, as consequências de assistência ao parto e a acessibilidade nas cidades.', '["public policy","people with disabilities","human rights","policy implementation","accessibility","health services","childbirth care","urban accessibility"]', '10.7476/9788523209308', '9788523208226', 'https://books.scielo.org/id/gbgzc', NULL, NULL, 'https://books.scielo.org/id/gbgzc/cover/cover_thumbnail.jpeg', 288, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
