excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gbvb4', 'gbvb4', 'Walter da Silveira e o cinema moderno no Brasil: críticas, artigos, cartas, documentos', NULL, '["Cyntia Nogueira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta os artigos de Walter da Silveira (1915 – 1970) sobre o cinema no Brasil e na Bahia, escritos entre 1943 e 1970. Ao lado de um conjunto relevante de críticas, ensaios, conferências e teses do autor, incluindo seleção de seus textos teóricos, estão reunidas na obra as cartas trocadas com dois outros críticos e historiadores do cinema brasileiro, Alex Viany e Paulo Emílio Sales Gomes, e com o crítico e cineasta Glauber Rocha. Além disso, documentos, fortuna crítica e um dossiê de artigos inéditos visam apresentar e contextualizar a importância de suas ações e pensamento para o desenvolvimento das ideias sobre cinema independente e para afirmação da crítica e do cinema modernos.', '["Brazilian cinema","modern cinema","independent film","film criticism","Glauber Rocha","film theory"]', '10.7476/9786556302669', '9786556300023', 'https://books.scielo.org/id/gbvb4', NULL, NULL, 'https://books.scielo.org/id/gbvb4/cover/cover_thumbnail.jpeg', 554, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gc3sh', 'gc3sh', 'Estratégias de ensino da matemática: entrelaçando saberes para a educação básica', NULL, '["Gessilda Cavalheiro Müller","Tânia Maria Hetkowski","Gerusa Soares Pinheiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema desta coletânea, fruto de diversas pesquisas de pós-graduação, situa-se no campo dos estudos da aprendizagem da Matemática, mais especificamente, sobre as estratégias de ensino, tendo como objetivo entrelaçar saberes de pesquisadores, professores e alunos e divulgar a produção sobre as estratégias de ensino e aprendizagem na Matemática.', '["mathematics teaching methods","mathematics learning","basic education","teacher knowledge","student knowledge","integration of research and practice"]', '10.7476/9786588211144', '9788578873257', 'https://books.scielo.org/id/gc3sh', 'https://books.scielo.org/id/gc3sh/pdf/muller-9786588211144.pdf', 'https://books.scielo.org/id/gc3sh/epub/muller-9786588211144.epub', 'https://books.scielo.org/id/gc3sh/cover/cover_thumbnail.jpeg', 304, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gcckh', 'gcckh', '“Aqui dentro só era a gente”: memória e territorialidade nos quilombos baianos (1990 – 2010)', 'memória e territorialidade nos quilombos baianos (1990 – 2010)', '["Fernanda Lemos Pinto","André Luiz Rosa Ribeiro"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta uma síntese histórica dos quilombos da Bahia, construída a partir de duas perspectivas complementares: a memória preservada pelas comunidades quilombolas, registrada por meio de documentários, e as conquistas legais e institucionais oriundas das lutas sociais. Por meio dos relatos orais de descendentes de escravizados, a obra resgata experiências do cativeiro e do pós-abolição, trazendo à tona dimensões da história não contempladas pela documentação oficial. Evidenciando tanto os mecanismos de opressão quanto às estratégias de resistência que garantiram a permanência dos quilombos até a atualidade.', '["quilombos","Bahia","collective memory","territoriality","quilombola communities","descendants of slaves","slavery","post-abolition period","resistance","social struggles","oral history","documentary film"]', '10.7476/9788574556482', '9788574556109', 'https://books.scielo.org/id/gcckh', NULL, NULL, 'https://books.scielo.org/id/gcckh/cover/cover_thumbnail.jpeg', 183, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gcjmx', 'gcjmx', 'Controle penal e violência: repensando os limites do poder punitivo no Brasil contemporâneo', 'repensando os limites do poder punitivo no Brasil contemporâneo', '["Alessandra Rapacci Mascarenhas Prado","Ney Menezes Oliveira Filho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea é composta por textos que discutem os limites da intervenção penal a partir da apresentação dos resultados de pesquisas empíricas e teóricas, que têm como objeto de análise um documentário, notícias divulgadas na mídia, autos de resistência, a legislação penal e a legislação processual penal. Ao tratarem de temas como mídia, teatralidade e linguagem punitiva, violência institucional e descumprimento de medidas protetivas, a máquina burocrática de arquivamento de autos de resistência, coleta coercitiva de material genético e a garantia da não autoincriminação, bem como a mediação no processo penal brasileiro, as autoras e os autores realizam análises críticas sob uma perspectiva contradiscursiva, visando desvelar o que consubstancia o poder punitivo no Brasil.', '["criminal justice","violence","limits of punitive power","media and criminal justice","theatricality","institutional violence","protective measures","privilege against self-incrimination","criminal mediation","criminal procedure"]', '10.7476/9786556309088', '9786556307688', 'https://books.scielo.org/id/gcjmx', 'https://books.scielo.org/id/gcjmx/pdf/prado-9786556309088.pdf', NULL, 'https://books.scielo.org/id/gcjmx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gddrd', 'gddrd', 'Baccharis dracunculifolia: uma das principais fontes vegetais da própolis brasileira', NULL, '["José Maurício Sforcin","João Paulo Barreto Sousa","Ademar Alves da Silva Filho","Jairo Kenupp Bastos","Michelle Cristiane Búfalo","Lígia Ribeiro da Silva Tonuci"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'A Baccharis dracunculifolia, conhecida como alecrim-do-campo, é uma das principais fontes vegetais de própolis no sudeste brasileiro. Atualmente, essa planta tem despertado o interesse de inúmeros pesquisadores pelas suas propriedades biológicas, seu potencial terapêutico e sua relação com as abelhas para a produção de própolis. Neste livro são apresentados os estudos de cultivo e de influência da sazonalidade nas plantas cultivadas, os aspectos fitoquímicos da Baccharis dracunculifolia nativa, o desenvolvimento de métodos analíticos por cromatografia das fases líquida e gasosa e as importantes atividades biológicas descobertas até o presente momento. Considerando o uso crescente de produtos naturais para os mais diferentes fins, os autores apresentam informações com protocolos experimentais consolidados junto à comunidade científica sobre o desenvolvimento de novos medicamentos fitoterápicos a partir de plantas medicinais ou produtos apícolas.', '["Baccharis dracunculifolia","Brazilian propolis","medicinal plants","plant cultivation","seasonal variation","phytochemistry","natural products","biological activity","herbal medicine","apitherapy","bees"]', '10.7476/9786557144961', '9786557144961', 'https://books.scielo.org/id/gddrd', 'https://books.scielo.org/id/gddrd/pdf/sforcin-9786557144961.pdf', NULL, 'https://books.scielo.org/id/gddrd/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-gf5mh', 'gf5mh', 'Abordagens do pós-moderno em música: a incredulidade nas metanarrativas e o saber musical contemporâneo', NULL, '["João Paulo Costa Nascimento"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em 1979, Jean-Fraçois Lyotard publica A Condição Pós-Moderna: Relatório Sobre o Saber sob a encomenda do Conselho da Universidades do estado de Québec. Tal publicação influenciou grande parte do debate sobre pós-modernismo em diversas áreas da pesquisa acadêmica em Humanidades. Tendo em vista tal influência, o presente trabalho tem por objetivo a observação desta influência de A Condição Pós-Moderna sobre as abordagens do pósmoderno em música realizadas posteriormente a década de 1980. Para tal tarefa, será utilizada a noção lyotardiana de pós-moderno como incredulidade nas metanarrativas de legitimação do saber. Esta influência será observada perante importantes textos relativos ao pós-moderno musical e na maneira como algumas obras da música clássica de concerto realizada na década de 1990 e 2000 se relacionam com tal incredulidade.', '["postmodernism in music","Jean-François Lyotard","The Postmodern Condition","incredulity","metanarrative","legitimation of knowledge","concert music","philosophy of music"]', '10.7476/9788579830983', '9788579830983', 'https://books.scielo.org/id/gf5mh', 'https://books.scielo.org/id/gf5mh/pdf/nascimento-9788579830983.pdf', NULL, 'https://books.scielo.org/id/gf5mh/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
